window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-gastrologia-gas-1"]={"block":"medcurso:medcurso-gastrologia-gas-1","label":"Medcurso · GAS 1","count":423,"questions":[{"id":"medcurso-gastrologia-gas-1-345508","number":"345508","sourceNumber":"345508","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Masculino, 20 anos, apresenta quadro de dor abdominal em andar superior e diarréia\nde aspecto secretório. Endoscopia digestiva\nalta mostra extensa lesão ulcerada duodenal com teste\nurease negativo. Ultrassom abdominal e hemograma normais. Gastrinemia sérica de 500 pg/mL\n(VR: até 100 pg/mL). Assinale a alternativa que mostre o local mais provável de origem desta\ndoença:","options":{"A":"Pâncreas.","B":"Duodeno.","C":"Apêndice cecal.","D":"Corpo gástrico."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-283327","number":"283327","sourceNumber":"283327","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 37 anos, sexo feminino, apresenta EDA com lesão ulcerada em incisura\nangularis do estômago com 1 cm, anatomopatológico confirma adenocarcinoma gástrico GII tipo\nintestinal, qual a melhor conduta cirúrgica para esse caso?","options":{"A":"Gastrectomia parcial com linfadenectomia D1.","B":"Gastrectomia parcial com linfadenectomia D2.","C":"Gastrectomia total com linfadenectomia D1.","D":"Gastrectomia total com linfadenectomia D2."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-281171","number":"281171","sourceNumber":"281171","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 67 anos realiza endoscopia digestiva alta para investigação de anemia que\ndemonstra lesão vegetante em antro gástrico. A biópsia evidencia adenocarcinoma. Assinale a\nalternativa que contenha a variante de acordo com a classificação de Lauren e o provável fator\ncausal desta lesão.","options":{"A":"Tipo difuso ? infecção por H. pylori.","B":"Tipo difuso ? mutação do gene p53.","C":"Tipo Intestinal ? infecção por H. pylori.","D":"Tipo difuso ? consumo elevado de nitratos.","E":"Tipo Intestinal ? consumo de vegetais crus."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-251873","number":"251873","sourceNumber":"251873","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A principal causa de hemorragia digestiva alta não varicosa é:","options":{"A":"Úlcera péptica.","B":"Gastrite atrófica.","C":"Linfoma tipo MALT.","D":"Gastroparesia."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-247168","number":"247168","sourceNumber":"247168","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo masculino, 66 anos, tabagista, é internado por hemorragia digestiva\nalta (HDA). Nega comorbidades e refere uso de\nremédio para cefaleia com certa frequência nas\núltimas semanas. O paciente evolui bem no seu terceiro dia de internação, sem novas\nexteriorizações e você pensa em programar a alta. O controle diário de hemoglobina desde a\nadmissão é: maior do corpo gástrico, 1,5 cm, bordas irregulares, com depósito de fibrina. Com\nrelação ao diagnóstico e à conduta para este paciente, assinale a alternativa CORRETA.","options":{"A":"HDA por úlcera gástrica de aspecto péptico. Alta hospitalar com inibidor de bomba de prótons\nVO por duas semanas.","B":"HDA por úlcera gástrica suspeita de ser neoplásica. Manter internação com uso de omeprazol\nEV por sete dias.","C":"HDA por úlcera gástrica medicamentosa. Alta hospitalar com uso contínuo de omeprazol e EDA\nem seis meses.","D":"HDA por úlcera gástrica suspeita de ser neoplásica. Alta hospitalar com inibidor de bomba\nprotônica por quatro semanas e EDA após.","E":"HDA por úlcera gástrica de aspecto péptico. Manter internação com uso de omeprazol EV\nassociado ao tratamento do H. pylori por sete dias."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-247216","number":"247216","sourceNumber":"247216","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale a alternativa que completa CORRETAMENTE a frase abaixo. A doença de\nRendu-Osler-Werber se caracteriza por:","options":{"A":"Tumores desmoides mais sangramentos digestivos.","B":"Tumores neuroendócrinos mais sangramentos digestivos recorrentes.","C":"Telangectasia de pele e membranas mucosas mais sangramentos digestivos recorrentes.","D":"Hamartomas mais sangramentos digestivos.","E":"Polipose familiar mais sangramentos digestivos recorrentes."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-247219","number":"247219","sourceNumber":"247219","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale a alternativa que completa corretamente a frase abaixo. A doença de\nMénétrier está associada à:","options":{"A":"Gastropatia com perda de proteína e hipercloridria.","B":"Gastrite com perda de lipídios.","C":"Gastropatia portal.","D":"Gastropatia com perda de proteína e hipocloridria.","E":"Gastrite lifoncítica."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-251941","number":"251941","sourceNumber":"251941","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Pac. ?, 60 anos, submetido a Gastrectomia a BII e \"Y\" de Roux para tratamento de um\nadenocarcinoma gástrico. Qual a importância do \"Y\" de Roux nesse procedimento?","options":{"A":"Profilaxia da deficiência de Vit. B12.","B":"Profilaxia da S. de Dumping.","C":"Profilaxia da gastrite alcalina.","D":"Profilaxia da perda de peso pôs-gastrectomia."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-251947","number":"251947","sourceNumber":"251947","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente ?, 33 anos, com queixas de pirose e regurgitamento pós-prandial de evolução\ncrônica. Há 3 anos foi diagnosticado pela endoscopia digestiva alta: esofagite grau A de Los\nAngeles, hiato esofagiano alargado e transição esôfago gástrica 3 cm acima do pinçamento\ndiafragmático. Melhora com uso de inibidores de bomba de prótons, medidas posturais e dietéticas,\nmas ao término dos tratamentos apresenta recidiva precoce dos sintomas. Qual sua conduta?","options":{"A":"Solicitar Manometria Esofágica e caso normal indicar tratamento cirúrgico.","B":"Solicitar Phmetria Esofágica e caso anormal indicar tratamento cirúrgico.","C":"Solicitar esofagografia e caso confirme o diagnóstico indicar tratamento cirúrgico.","D":"Indicar tratamento cirúrgico."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-217665","number":"217665","sourceNumber":"217665","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente, sexo masculino, 35 anos, com dor epigástrica súbita de forte intensidade, que\nse irradiou inicialmente para hipogástrio e\nem seguida para todo abdome, evolução de 2 horas.\n\nVinha fazendo uso de AINH há 3 dias por apresentar dor lombar. Ao exame físico encontramos o\n\"abdome em tábua\". O exame mais apropriado para esclarecimento diagnóstico é:","options":{"A":"Ultrassonografia de abdome.","B":"Rotina radiológica para abdome agudo.","C":"Ressonância magnética de abdome superior.","D":"Tomografia computadorizada de abdome."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-217677","number":"217677","sourceNumber":"217677","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente masculino, 68 anos, refere dor epigástrica há 9 meses e nos últimos 2 meses\ncom vômitos pós-prandiais precoces. Refere\nemagrecimento de 6 kg nesse período e ao exame\nfísico nota-se nódulo endurecido em fossa supraclavicular esquerda. Qual a hipótese diagnóstica?","options":{"A":"Tumor de Pancoast.","B":"Câncer de esôfago médio.","C":"Câncer gástrico.","D":"Câncer de cólon."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-183189","number":"183189","sourceNumber":"183189","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente adulta vem apresentando síndrome consuntivo e apresenta placas extensas\npapilomatosas hiperqueratósicas e hipercrômicas nas regiões intertriginosas. Suspeitando-se de\nmanifestação paraneoplásica, o tumor que mais frequentemente se associa a esse quadro é\nadenocarcinoma de:","options":{"A":"Pulmão.","B":"Estômago.","C":"Pâncreas.","D":"Cólon.","E":"Ovários."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-182622","number":"182622","sourceNumber":"182622","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente masculino, 52 anos com queixas de disfagia com evolução de 8 anos. Foi\nrealizado endoscopia digestiva alta que\nevidenciou dilatação esofágica e diagnóstico de acalasia. O\nesofagograma revelou megaesôfago grau II. Qual exame deverá ser realizado para a escolha da\ntécnica operatória apropriada?","options":{"A":"Endoscopia com magnificação e corante vermelho Congo.","B":"Manometria esofágica.","C":"PHmetria esofágica.","D":"Ecoendoscopia."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-159113","number":"159113","sourceNumber":"159113","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo masculino, 58 anos, iniciou quadro de dor em andar superior do\nabdome intensa, há 2 horas. Nega quadro\nsemelhante anterior ou cirurgias prévias. Ao exame\nfísico: abdome plano, em tábua. Considerando a hipótese de perfuração de úlcera péptica, quais as\nprincipais etiologias?","options":{"A":"H. pylori e Anti-Inflamatório Não Hormonal (AINH).","B":"Câncer gástrico e doença de Dieulafoy.","C":"Gastrite erosiva aguda e síndrome de Ménétrier.","D":"Gastrinoma e tumor estromal."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-135927","number":"135927","sourceNumber":"135927","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um lactante com 1 mês e 20 dias de vida é atendido na Unidade de Pronto\nAtendimento de seu bairro com história de\nvômitos alimentares em jato após as mamadas.\nEncontra-se abaixo do peso esperado para idade e desidratado. Após investigação, a ecografia\nabdominal firmou o diagnóstico de estenose hipertrófica de piloro. Quais os distúrbios acidobásicos\nque se espera encontrar?","options":{"A":"Alcalose respiratória;","B":"Alcalose metabólica;","C":"Acidose respiratória;","D":"Acidose metabólica."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-108650","number":"108650","sourceNumber":"108650","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Qual a manifestação cutânea paraneoplásica está mais associada ao câncer gástrico?","options":{"A":"Acantose nigricans.","B":"Prurido.","C":"Pênfigo.","D":"Síndrome de Bazex."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-108688","number":"108688","sourceNumber":"108688","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente feminina, 60 anos, submetida à Gastrectomia a Bll e \"Y\" de Roux para\ntratamento de um adenocarcinoma gástrico. Qual a importância do \"Y\" de Roux nesse\nprocedimento?","options":{"A":"Profilaxia da deficiência de Vit. B12;","B":"Profilaxia da S. de Dumping;","C":"Profilaxia da gastrite alcalina;","D":"Profilaxia da perda de peso pôs-gastrectomia."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-84534","number":"84534","sourceNumber":"84534","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Qual das características do esôfago, a seguir, não está relacionada com altas taxas de\nmorbimortalidade nas perfurações desse órgão?","options":{"A":"Relação anatômica com estruturas nobres.","B":"Presença de serosa delgada.","C":"Parede com pouca espessura.","D":"Trajeto longo.","E":"Tipo de irrigação sanguínea."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-84539","number":"84539","sourceNumber":"84539","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"São indicações clássicas de tratamento cirúrgico para úlcera péptica, exceto:","options":{"A":"úlcera penetrada para pâncreas.","B":"perfuração.","C":"obstrução pilórica.","D":"hemorragia sem controle com tratamento endoscópico/ radiológico.","E":"presença de pneumoperitoneo."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-84530","number":"84530","sourceNumber":"84530","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O que aumenta o risco de se desenvolver câncer de estômago:","options":{"A":"Comer farinha.","B":"Comer pimenta.","C":"Comer sal.","D":"Tomar refrigerante.","E":"Tomar chá."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-84526","number":"84526","sourceNumber":"84526","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Cirurgia de urgência no câncer gástrico, EXCETO?","options":{"A":"Hemorragia com politransfusão.","B":"Obstrução com vômito.","C":"Ascite hemorrágica maligna tensa.","D":"Perfuração sem bloqueio.","E":"Ruptura por distensão."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-67006","number":"67006","sourceNumber":"67006","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Pac. sexo masculino. 26 anos, iniciou quadro de dor epigástrica e retroesternal,\nseguidos de vômitos com raios de sangue com\nevolução de 12h. Refere ingestão abusiva de álcool\nna noite anterior. Nega episódios semelhantes anteriormente e se apresenta hemodinamicamente\nestável. Qual a hipóstese diagnóstica?","options":{"A":"Síndrome de Mallory-Weiss;","B":"Úlcera duodenal;","C":"Síndrome de Boerhaave;","D":"Rutura de varizes de esôfago."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-66923","number":"66923","sourceNumber":"66923","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Pac. sexo masculino, 26 anos, iniciou quadro de dor epigástrica e retroesternal,\nseguidos de vômitos com raios de sangue com\nevolução de 12h. Refere ingestão abusiva de álcool\nna noite anterior. Nega episódios semelhantes anteriormente e se apresenta hemodinamicamente\nestável. Com relação ao caso clínico, qual a melhor conduta?","options":{"A":"Passar sonda nasogástrica e iniciar lavagem com soro fisiológico;","B":"Endoscopia digestiva alta de imediato;","C":"Solicitar hematócrito para avaliar a perda sanguínea;","D":"Solicitar seriografia esôfago-estômago-duodeno."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-66987","number":"66987","sourceNumber":"66987","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 37 anos, sexo feminino, apresenta EDA com lesão ulcerada em incisura\nangulares do estômago com 1 cm, anatomopatológico confirma adenocarcinoma gástrico GII tipo\nintestinal. Qual a melhor conduta?","options":{"A":"Gastrectomia parcial com linfadenectomia D1;","B":"Gastrectomia parcial com linfadenectomia D2;","C":"Gastrectomia total com linfadenectomia D1;","D":"Gastrectomia total com linfadenectomia D2;"},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-50064","number":"50064","sourceNumber":"50064","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente feminino, 35 dias de vida, dieta exclusiva com leite materno, apresenta\nvômitos recorrentes, pós-prandiais, com piora\nprogressiva desde o nascimento. Ao exame físico,\npalpa-se massa de consistência firme, móvel, de 3 cm em região periumbilical direita. Qual a\nhipótese diagnóstica mais provável?","options":{"A":"Estenose hipertrófica de piloro.","B":"Duplicação duodenal.","C":"Intolerância ao leite materno.","D":"Atresia de íleo."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-37054","number":"37054","sourceNumber":"37054","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre os aspectos clínicos do câncer de esôfago, é INCORRETO afirmar:","options":{"A":"A queixa principal é a disfagia.","B":"A odinofagia ocorre nos tumores ulcerados.","C":"A anorexia e o emagrecimento não estão presentes.","D":"O relato de dor torácica com irradiação indica a invasão das estruturas neuromediastinais.","E":"Nenhuma das alternativas."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-37056","number":"37056","sourceNumber":"37056","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação às gastrectomias, a reconstrução em \"Y\" de Roux é indicada por qual dos\nfatores abaixo?","options":{"A":"Para evitar a Síndrome de Dumping que pode levar a quadros de desnutrição.","B":"Para evitar a gastrite alcalina que em longo prazo pode evoluir para adenocarcinoma de boca\nanastomótica.","C":"Para evitar a síndrome da alça aferente que leva a quadros diarreicos.","D":"Para haver melhor absorção de vit. B12 e dessa forma evitar anemia megaloblástica.","E":"Essa técnica não difere de outras e depende apenas da preferência do cirurgião."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-29363","number":"29363","sourceNumber":"29363","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente H.pylori positivo. Qual situação está indicada fortemente erradicação do\nmicrorganismo?","options":{"A":"Úlcera duodenal","B":"Dispepsia funcional","C":"Doença do refluxo gastro-esofágico","D":"Desejo do paciente após esclarecimentos","E":"Uso crônico de AINES"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-29382","number":"29382","sourceNumber":"29382","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O exame complementar mais eficaz para o diagnóstico do câncer gástrico é:","options":{"A":"Ultrassonografia abdominal","B":"Ultrassonografia endoscópica","C":"Tomografia computadorizada","D":"Seriografia de esôfago, estômago e duodeno","E":"Endoscopia digestiva alta com biópsia"},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-341053","number":"341053","sourceNumber":"341053","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem, 65 anos de idade, é levado ao Ambulatório de Cirurgia Geral com história de\ndor em epigástrio, de moderada\nintensidade, com piora à alimentação há dois meses. O paciente\nrefere, também, hiporexia, alguns episódios de náuseas e vômitos e perda de peso (não\nmensurada) neste mesmo período. Relata tabagismo 30 cigarros/dia e etilismo social há 30 anos.\nAo exame físico, regular estado geral, descorado +2/+4, ictérico +1/+4, FC: 72bpm, PA:\n110x74mmHg, ausculta cardíaca e respiratória sem alterações; abdome um pouco distendido;\nruídos hidroaéreos presentes, flácido; dor à palpação profunda de epigástrio, sem sinais de\nirritação\nperitoneal; palpado nódulo em região umbilical, medindo cerca de 1,0cm. Os exames laboratoriais\niniciais apresentaram Hb: 10g/dL, Ht: 32%, Leucócitos totais: 9500células/mm³, Ureia: 35mg/dL,\nCreatina: 1,0mg/dL, Na: 142mEq/L, K: 4,0mEq/L, Bilirrubinas totais 3,5mg/dL (direta: 2,5/dL e\nindireta: 1,0mg/dL). Diante do caso clínico e dos exames complementares, indique a principal\nsuspeita diagnóstica que justifique o quadro clínico do paciente:","options":{"A":"Hepatite crônica alcoólica.","B":"Pancreatite crônica alcoólica.","C":"Linfoma não-Hodgkin.","D":"Câncer gástrico."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-341054","number":"341054","sourceNumber":"341054","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem, 65 anos de idade, é levado ao Ambulatório de Cirurgia Geral com história de\ndor em epigástrio, de moderada\nintensidade, com piora à alimentação há dois meses. O paciente\nrefere, também, hiporexia, alguns episódios de náuseas e vômitos e perda de peso (não\nmensurada) neste mesmo período. Relata tabagismo 30 cigarros/dia e etilismo social há 30 anos.\nAo exame físico, regular estado geral, descorado +2/+4, ictérico +1/+4, FC: 72bpm, PA:\n110x74mmHg, ausculta cardíaca e respiratória sem alterações; abdome um pouco distendido;\nruídos hidroaéreos presentes, flácido; dor à palpação profunda de epigástrio, sem sinais de\nirritação\nperitoneal; palpado nódulo em região umbilical, medindo cerca de 1,0cm. Os exames laboratoriais\niniciais apresentaram Hb: 10g/dL, Ht: 32%, Leucócitos totais: 9500células/mm³, Ureia: 35mg/dL,\nCreatina: 1,0mg/dL, Na: 142mEq/L, K: 4,0mEq/L, Bilirrubinas totais 3,5mg/dL (direta: 2,5/dL e\nindireta: 1,0mg/dL). Com base no quadro, indique o exame complementar mais adequado para a\nconfirmação do diagnóstico:","options":{"A":"Punção por agulha grossa do fígado guiada por ultrassonografia.","B":"Tomografia computadorizada do abdome.","C":"Endoscopia digestiva alta.","D":"Videolaparoscopia diagnóstica."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-341055","number":"341055","sourceNumber":"341055","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem, 65 anos de idade, é levado ao Ambulatório de Cirurgia Geral com história de\ndor em epigástrio, de moderada\nintensidade, com piora à alimentação há dois meses. O paciente\nrefere, também, hiporexia, alguns episódios de náuseas e vômitos e perda de peso (não\nmensurada) neste mesmo período. Relata tabagismo 30 cigarros/dia e etilismo social há 30 anos.\nAo exame físico, regular estado geral, descorado +2/+4, ictérico +1/+4, FC: 72bpm, PA:\n110x74mmHg, ausculta cardíaca e respiratória sem alterações; abdome um pouco distendido;\nruídos hidroaéreos presentes, flácido; dor à palpação profunda de epigástrio, sem sinais de\nirritação\nperitoneal; palpado nódulo em região umbilical, medindo cerca de 1,0cm. Os exames laboratoriais\niniciais apresentaram Hb: 10g/dL, Ht: 32%, Leucócitos totais: 9500células/mm³, Ureia: 35mg/dL,\nCreatina: 1,0mg/dL, Na: 142mEq/L, K: 4,0mEq/L, Bilirrubinas totais 3,5mg/dL (direta: 2,5/dL e\nindireta: 1,0mg/dL). Identifique, entre os achados da história clínica e do exame físico do\npaciente,\no fator de pior prognóstico:","options":{"A":"Anemia.","B":"Nódulo palpável em região umbilical.","C":"Icterícia.","D":"Perda de peso."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-343187","number":"343187","sourceNumber":"343187","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O divertículo faringoesofágico é o divertículo esofágico mais comum. Situa-se\nherniando em uma região denominada trígono de\nKillian. A complicação mais mórbida do não\ntratamento desta doença em pacientes idosos é:","options":{"A":"Carcinoma escamoso.","B":"Esôfago de Barret.","C":"Pneumonias por aspiração.","D":"Perda ponderal."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-343191","number":"343191","sourceNumber":"343191","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale a alternativa que se associa a condições de aumento da secreção péptica\ngástrica como na síndrome de Zollinger-Ellison.","options":{"A":"Carcinoma epidermoide de estômago","B":"Gastrinoma","C":"GIST duodenal","D":"Insulinoma"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-315164","number":"315164","sourceNumber":"315164","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A alteração fisiológica causada pela vagotomia troncular é a seguinte:","options":{"A":"Diminuição do volume da vesícula biliar","B":"Aumento da sensibilidade à histamina","C":"Aumento da secreção exócrina do pâncreas","D":"Diminuição do fluxo biliar pós-prandial","E":"Hipoplasia das células secretoras de gastrina"},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-315165","number":"315165","sourceNumber":"315165","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Durante uma gastrectomia parcial (antrectomia), que estrutura serve de referência para\ndelimitar o antrogástrico?","options":{"A":"Artéria gástrica esquerda.","B":"Ramo de Latarjet do nervo vago.","C":"Borda superior do pâncreas.","D":"Ligamento Redondo.","E":"Artéria gastro-omental direita."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-275978","number":"275978","sourceNumber":"275978","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Na doença do refluxo gastroesofágico, qual o exame complementar considerado como\npadrão ouro?","options":{"A":"Manometria.","B":"Endoscopia.","C":"Rx contrastado do esôfago.","D":"Phmetria.","E":"Impedanciometria."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-275980","number":"275980","sourceNumber":"275980","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Na classificação morfológica dos tumores do estômago, Bormann 4, é:","options":{"A":"Tumor ulcerado.","B":"Infiltrativo local.","C":"Infiltrativo difuso (Linite).","D":"Escavado.","E":"Ulcerado e infiltrativo local."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-279056","number":"279056","sourceNumber":"279056","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"É o divertículo faringoesofágico mais comum encontrado hoje em dia. Apresenta-se,\ngeralmente, em pacientes idosos na sétima\ndécada de vida e tem sido postulado como resultado de\nperda da elasticidade tecidual e tônus muscular com a idade. É encontrado especificamente\nherniando no triângulo de Killian, entre as fibras oblíquas do músculo tireofaríngeo e as fibras\nhorizontais do músculo cricofaríngeo. Trata-se do:","options":{"A":"Divertículo de Meckel.","B":"Divertículo de Zenker.","C":"Divertículo de Hinchey.","D":"Divertículo de Hutch."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-278638","number":"278638","sourceNumber":"278638","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A seriografia contrastada a seguir de esôfago, estômago e duodeno tem maiores\nchances de serem encontradas em pacientes com o diagnóstico de:","options":{"A":"Acalásia.","B":"Carcinoma espinocelular.","C":"Adenocarcinoma.","D":"Espasmo esofágico difuso."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/278638.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-278643","number":"278643","sourceNumber":"278643","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"As úlceras gástricas podem ocorrer em qualquer local no estômago, apesar de\ngeralmente estarem presentes na curvatura menor, perto da incisura angularis. Sobre a\nclassificação de Johnson, assinale a correta.","options":{"A":"Úlcera tipo I: sempre estão associadas à secreção excessiva de ácidos.","B":"Úlcera tipo II: geralmente estão associadas a uma elevada secreção de ácido, em combinação\ncom uma úlcera duodenal.","C":"Úlcera tipo III: são úlceras em corpo gástrico e responsáveis por cerca de 90% das lesões.","D":"As úlceras gástricas do tipo IV ocorrem em uma parte distal do corpo gástrico, próximo ao\npiloro."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-279064","number":"279064","sourceNumber":"279064","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"É a falha de relaxamento da musculatura esofágica. Essa doença é a mais bem\ncompreendida de todos os distúrbios da motilidade esofágica. A tríade clássica de sintomas\nconsiste em disfagia, regurgitação e perda de peso. Pode ser diagnosticada pelo esofagograma\nabaixo. Trata-se do(a):","options":{"A":"Esôfago em quebra-nozes.","B":"Adenocarcinoma de esôfago.","C":"Doença do refluxo gastroesofágico.","D":"Acalásia."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/279064.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-231355","number":"231355","sourceNumber":"231355","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale qual o esquema terapêutico considerado como primeira opção para o\ntratamento do H. Pylori de acordo com o IV Consenso Brasileiro do H. Pylori:","options":{"A":"IBP (dose plena) + amoxicilina 1G + Claritromicina 500 MG 2 vezes ao dia ? durante 14 dias.","B":"IBP (dose plena + amoxicilina 1G + Claritromicina 500 MG 2 vezes ao dia, durante 07 dias.","C":"A alternativa (A) e (E), durante 10 dias.","D":"IBP (dose plena) + amoxicilina 1G + Metronidazol 400 MG duas vezes ao dia 14 dias","E":"IBP (dose plena 1 x dia) + tetraciclina 500 MG (6 em 6 horas) + Claritromicina 500 MG (2 x dia),\ndurante 14 dias."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-249304","number":"249304","sourceNumber":"249304","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O tronco celíaco é uma importante fonte de irrigação de vísceras abdominais. Emite 3\nramos arteriais principais:","options":{"A":"mesentérica superior, hepática comum e frênica inferior.","B":"mesentérica superior, hepática própria e esplênica.","C":"hepática comum, gástrica esquerda e esplênica.","D":"mesentérica inferior, gástrica esquerda e esplênica acessória."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-249306","number":"249306","sourceNumber":"249306","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A fundoplicatura de Nissen é um procedimento cirúrgico utilizado para tratamento de:","options":{"A":"dolicomegaesôfago.","B":"atresia duodenal.","C":"gastrite alcalina.","D":"doença do refluxo gastroesofágico."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-249412","number":"249412","sourceNumber":"249412","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"São fatores estimulantes da secreção ácida gástrica:","options":{"A":"Gastrina, histamina e acetilcolina.","B":"Gastrina, bradicinina e acetilcolina.","C":"Somatostatina, histamina e acetilcolina.","D":"Somatostatina, bradicinina e adrenalina."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-249422","number":"249422","sourceNumber":"249422","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Originalmente descrito por Zenker e Von Ziemssen, o divertículo faringo-esofágico é o\ndivertículo esofágico mais comum. Encontra-se herniando em uma região denominada trígono de\nKillian. A complicação mais mórbida do não tratamento desta doença em pacientes idosos é:","options":{"A":"Abscesso pulmonar e/ou pneumonias por aspiração.","B":"Perfuração esofágica.","C":"Esôfago de Barret.","D":"Caquexia."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-249225","number":"249225","sourceNumber":"249225","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A técnica cirúrgica para correção de doença do refluxo gastroesofágico que\noriginalmente há abordagem intra-torácica e abdominal é:","options":{"A":"Nissen","B":"Lindi","C":"Toupet","D":"Belsey-Mark IV"},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-249229","number":"249229","sourceNumber":"249229","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"São estimulantes da secreção de ácido clorídrico pelas células parietais no estômago:","options":{"A":"histamina, acetilcolina e gastrina.","B":"histamina, acetilcolina e prostaglandina.","C":"tiamina, acetilcolina e bicarbonato.","D":"gastrina, acetilcolina e óxido pentanitroso."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-212185","number":"212185","sourceNumber":"212185","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 55 anos, ex-etilista, 20 g de álcool por 12 anos, parou há 20 anos, sem\noutras comorbidades, apresentando dor epigástrica\nem queimação, sem irradiação, sem relação\ncom alimentação há 2 meses. Emagreceu cerca de 8 kg desde então. Fazia uso de hidróxido de\nmagnésio com pouca melhora do quadro. Em consulta médica observa-se paciente em bom estado\ngeral, hipocorado, hidratado, pouco emagrecido. Abdome plano, flácido, indolor, sem cicatrizes\ncirúrgicas nem massas palpáveis. Não são identificadas adenopatias à palpação axilar, cervical e\ninguinal. É realizada endoscopia digestiva alta onde se observa lesão ulcerada, bordos elevados e\nbem delimitados, com cerca de 3 cm de diâmetro em incisura angular, pequena curvatura. Biópsia\nde lesão diagnóstica adenocarcinoma moderadamente diferenciado, tipo intestinal. Tomografia de\nabdome e tórax evidencia espessamento parietal de porção antral do estômago, com densificação\nda gordura mesentérica e adenopatias maiores que 1 cm adjacentes a artéria gástrica esquerda,\nsem líquido livre. Assinale a alternativa correta sobre o caso.","options":{"A":"Trata-se de uma lesão Bormann II.","B":"Trata-se de uma neoplasia gástrica Siewert II.","C":"Quimioterapia neoadjuvante não altera sobrevida.","D":"É uma lesão passível de dissecção endoscópica submucosa, menos invasiva para esse tipo de\nlesão.","E":"Ultrassonografia endoscópica é o melhor exame para estadiamento locoregional dessa doença."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-212155","number":"212155","sourceNumber":"212155","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 60 anos, sexo feminino, relata que há 6 meses iniciou um quadro de dor\nem região epigástrica de moderada\nintensidade, sem irradiação e 2 vezes por semana. Há 3 meses\nevoluiu com piora da intensidade e da frequência do sintoma. Refere dor epigástrica diária,\nprincipalmente após a alimentação. Foi à consulta com o gastroenterologista, que solicitou uma\nendoscopia digestiva alta. O exame histológico evidenciou gastrite crônica com presença de H.\npylori. De acordo com o IV Consenso Brasileiro sobre a infecção por Helicobacter pylori, assinale a\nalternativa CORRETA.","options":{"A":"A fase adulta é considerada o período de maior risco para aquisição de H. pylori.","B":"Os seres humanos são o único reservatório e principal fonte de transmissão de H. pylori.","C":"A pesquisa de H. pylori após a terapia de erradicação deverá ser realizada pelo menos 12\nsemanas após o término do tratamento.","D":"O teste do antígeno fecal usando anticorpos monoclonais é o exame padrão ouro para o\ndiagnóstico não invasivo de infecção por H. pylori.","E":"O teste rápido da urease é o exame recomendado para controle da erradicação de H. pylori\napós o tratamento, sem a necessidade de exame adicional."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-201751","number":"201751","sourceNumber":"201751","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Quais destas operações são realizadas no tratamento do megaesôfago chagásico em\ngraus iniciais?","options":{"A":"Esofagocoloplastia.","B":"Esofagogastroplastia.","C":"Esofagectomia total.","D":"Todas as anteriores.","E":"Nenhuma das anteriores."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-201794","number":"201794","sourceNumber":"201794","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No estadiamento morfológico dos tumores do estômago, a classificação Bormann 4, é:","options":{"A":"Tumor ulcerado.","B":"Infiltrativo local.","C":"Infiltrativo difuso (Linite).","D":"Escavado.","E":"Ulcerado e infiltrativo local."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-216260","number":"216260","sourceNumber":"216260","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre os tumores de esôfago é INCORRETO que","options":{"A":"a tomografia computadorizada é o principal método de estadiamento do câncer de esôfago.","B":"o melhor tratamento para câncer epidermoide do esôfago é a ressecção cirúrgica R0","C":"quimioterapia e/ou radioterapia associados ao tratamento cirúrgico não aumentam a\nsobrevivência.","D":"radioterapia terapêutica exclusiva não deve ser indicada com intenção paliativa."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-180138","number":"180138","sourceNumber":"180138","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O triângulo de Killian tem relação etiopatogênica com:","options":{"A":"Hernia lombar superior","B":"Hernia inguinal","C":"Divertículo de Zenker","D":"Divertículo de Meckel","E":"Anel de Schatzki"},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-180145","number":"180145","sourceNumber":"180145","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre suturas gastrointestinais é incorreto afirmar:","options":{"A":"O plano total tem por objetivo a hemostasia e a continência.","B":"A sutura contínua ancorada permite melhor controle hemostático.","C":"A gastroenteroanastomose geralmente é realizada na face posterior do estômago, por causa do\nmelhor suprimento arterial.","D":"A sutura seromuscular é a que permanence e a que mantém a justaposição correta das\nestruturas\n\nanatômicas anastomosadas.","E":"A anastomose é dita isoperistáltica quando o sentido do trânsito é o mesmo em cada uma das\nvísceras anastomosadas."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-181312","number":"181312","sourceNumber":"181312","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em relação à doença de Chagas e à acalásia da cárdia, é correto afirmar:","options":{"A":"o tratamento curativo da acalásia é cirúrgico, sendo as cirurgias de Heller e Thal-Hatafuku as\nmais realizadas em todo o mundo.","B":"apesar de doenças diferentes, a esofagopatia chagásica e a acalásia idiopática têm\nfisiopatologia, manifestações clínicas e tratamento iguais.","C":"o tratamento não cirúrgico mais eficaz para acalásia é a dilatação pneumática da transição\nesôfago-gástrica levando a alívio duradouro da disfagia.","D":"os pacientes com doença de Chagas apresentam sintomas brandos e inespecíficos na fase\naguda e, após 2 a 4 meses, mais da metade dos pacientes evoluem para fase crônica.","E":"as características radiológicas do megaesôfago do grupo II, segundo a classificação de\nRezende, são pequeno a moderado aumento de\ndiâmetro e retenção de contraste e hipotonia do\nesôfago inferior."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-181403","number":"181403","sourceNumber":"181403","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Dadas as afirmativas, quanto à doença do refluxo gastroesofágico (DRGE), I. Tosse\ncrônica, pigarro e desgaste no esmalte dentário são considerados manifestações atípicas da\nDRGE.; II. A obesidade é um fator de risco na DRGE.; III. A DRGE pode ser classificada em duas\nformas de apresentação, sendo a erosiva a forma mais frequente de apresentação.; IV. Os\ninibidores da bomba de prótons (IBP) são considerados medicamentos de escolha no tratamento\nda DRGE. Pacientes com manifestações atípicas têm indicação de iniciar tratamento com dose\nplena de IBP por um período prolongado. verifica-se que estão corretas","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e IV, apenas.","D":"III e IV, apenas.","E":"I, II, III e IV."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-183086","number":"183086","sourceNumber":"183086","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Qual das alternativas abaixo é a causa mais comum de perfuração do esôfago?","options":{"A":"Arma branca.","B":"Arma de fogo.","C":"Iatrogênica.","D":"Ingestão de corpo estranho."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-182824","number":"182824","sourceNumber":"182824","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre os divertículos de Zenker, marque a afirmativa INCORRETA.","options":{"A":"É encontrado no triângulo de Killian, entre as fibras oblíquas do músculo tireofaríngeo e as\nfibras\nhorizontais do músculo cricofaríngeo.","B":"Os procedimentos endoscópicos para tratamento dos divertículos de Zenker são sujeitos a\ncomplicações, destacando-se hemorragia e perfurações, que podem cursar com grave mediastinite.","C":"O diagnóstico é feito por seriografia contrastada faringoesofágica.","D":"A vantagem da diverticulopexia sobre a diverticulectomia é a ausência do risco de fístula."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-183615","number":"183615","sourceNumber":"183615","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"É INCORRETO afirmar sobre o carcinoma esofágico:","options":{"A":"Pacientes com a Síndrome de Plummer-Vinson tem risco aumentado para desenvolver câncer\nde células escamosas do esôfago cervical.","B":"Menos da metade dos pacientes que se apresentam com câncer esofágico são elegíveis para\nressecção cirúrgica.","C":"O Adenocarcinoma é mais sensível à quimiorradioterapia.","D":"Na esofagectomia em bloco uma linfadenectomia torácica radical é realizada, e todos os\nlinfonodos mediastinais (incluindo paratraqueal direito, subcarinal, paraesofágico e ligamento\npulmonar inferior esquerdo e direito) e linfonodos diafragmáticos, bem como tecidos linfáticos\nligados ao ducto torácico, são removidos."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-183622","number":"183622","sourceNumber":"183622","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O papel do tratamento cirúrgico para o refluxo gastroesofágico e hérnias de hiato\nmudou drasticamente durante a década de 1990. A\npopularização da intervenção cirúrgica\nminimante invasiva foi a força motriz responsável pelo aumento das indicações para o tratamento\ncirúrgico destas doenças. É INCORRETO afirmar sobre as complicações relacionadas aos\nprocedimentos antirrefluxo laparoscópicos:","options":{"A":"Pneumotórax é uma das complicações intraoperatórias mais comuns, que se resolvem na maior\nparte das vezes com drenagem pleural fechada.","B":"Plenitude pode ocorrer em até 30% dos pacientes, no entanto a maioria tem melhora dos\nsintomas após 2 meses.","C":"Insucesso cirúrgico se refere a pacientes com sintomas persistentes e evidência de exposição\nao ácido, a incidência é de cerca de 5 a 10%.","D":"A taxa de mortalidade é muito baixa. Sendo maior em paciente com mais de 60 anos."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-161306","number":"161306","sourceNumber":"161306","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Aponte a alternativa INCORRETA com relação às síndromes pós-gastrectomia.","options":{"A":"A síndrome de Dumping pode ser precoce (20-30 minutos após a ingestão) ou tardia (duas ou\ntrês horas após uma refeição) e é mais comum após gastrectomia parcial com reconstrução à\nBillroth II.","B":"A síndrome da alça aferente ocorre como resultado de uma obstrução parcial da alça aferente,\nque é incapaz de esvaziar os seus conteúdos.","C":"A obstrução da alça eferente geralmente é rara e pode ocorrer a qualquer momento após a\noperação; no entanto, mais de 50% dos pacientes ficam obstruídos no primeiro mês de\n\npós-operatório.","D":"A maior parte dos pacientes que sofrem de gastrite por refluxo alcalino foi submetida à\nressecção gástrica com anastomose à Billroth I."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-161310","number":"161310","sourceNumber":"161310","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Associe os Hormônios Gastrointestinais a seus respectivos Efeitos Primários e, em\nseguida, marque a opção contendo a sequência CORRETA. (Conforme imagem do caderno de\nquestões).","options":{"A":"1-b / 2-d / 3-c / 4-a","B":"1-b / 2-c / 3-a / 4-d","C":"1-b / 2-c / 3-d / 4-a","D":"1-d / 2-a / 3-b / 4-c"},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/161310.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-158788","number":"158788","sourceNumber":"158788","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Suponha que você está realizando uma gastrectomia subtotal oncológica, seguindo\ntodos os passos técnicos corretamente. Depois\nde realizar o descolamento intercoloepiploico,\nligadura dos vasos gastroepiploicos direitos e dos vasos gástricos esquerdos e suas respectivas\nlinfadenectomias, inadvertidamente, promove uma lesão esplênica durante linfadenectomia desta\nregião. Você tenta realizar hemostasia, esplenorrafia, confecção de patch, todas sem sucesso e\nopta, finalmente, por esplenectomia para não comprometer a estabilidade clínica e hemodinâmica\ndo paciente. Após todos esses passos técnicos, qual será sua próxima conduta para continuação\nda cirurgia?","options":{"A":"Gastrectomia a 4/5.","B":"Cirurgia de Traverso-Longmire.","C":"Gastrectomia total com reconstrução em Y de Roux.","D":"Gastrectomia subtotal com reconstrução em Y de Roux.","E":"Abortar cirurgia para controle de dano e nova abordagem em 48 hs."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-161262","number":"161262","sourceNumber":"161262","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale a alternativa INCORRETA em relação à anatomia gástrica macroscópica.","options":{"A":"O plexo celíaco é a principal fonte do suprimento sanguíneo para o estômago. Existem quatro\nartérias principais ? as artérias gástricas\nesquerda e direita e a artéria gastroepiplóica direita e\nesquerda. Uma quantidade substancial de sangue pod ser suprida pelas artérias frênicas inferiores\ne pelas artérias gástricas curtas.","B":"A mais volumosa artéria para o estômago é a artéria gástrica direita, e não é incomum (15-20%)\nque uma artéria hepática esquerda aberrante\nse origine dela.","C":"A inervação extrínseca do estômago é parassimpática (via vago) e simpática (pelo plexo\ncelíaco). Na junção gastroesofágica, o vago esquerdo é anterior e o vago direito é posterior.","D":"As veias gástricas esquerda e direita geralmente drenam para dentro da veia porta. A veia\ngastroepiploica direita drena para a veia mesentérica superior, e a veia gastroepiplóica esquerda\ndrena para veia esplênica."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-152663","number":"152663","sourceNumber":"152663","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Na doença do refluxo gastroesofágico, qual o exame complementar considerado como\npadrão-ouro?","options":{"A":"Manometria.","B":"Endoscopia.","C":"Rx contrastado do esôfago.","D":"pHmetria.","E":"Cintilografia."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-152667","number":"152667","sourceNumber":"152667","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No estadiamento morfológico dos tumores do estômago, a classificação Bormann 4, é:","options":{"A":"Tumor ulcerado.","B":"Infiltrativo local.","C":"Infiltrativo difuso (Linite).","D":"Escavado.","E":"Ulcerado e infiltrativo local."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134854","number":"134854","sourceNumber":"134854","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Divertículos são formações saculares em fundo cego que podem estar localizados em\nvárias partes do corpo humano. Os divertículos de Zenker localizam-se no:","options":{"A":"Esôfago superior.","B":"Intestino grosso.","C":"Intestino delgado.","D":"Esôfago inferior."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134893","number":"134893","sourceNumber":"134893","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem de 43 anos, na sala de urgência, com dor abdominal intensa e dor torácica\nsubesternal há 12 horas (após ingestão de\ngrande quantidade de álcool em uma festa). Antes do\ninício da dor teve vários episódios de vômito. História prévia não é digna de nota e não usa\nmedicamentos. Ao exame clínico, encontra-se desconfortável e ansioso, temperatura de 38,8°C,\nfrequência cardíaca de 120/min, pressão arterial de 120 x 80 mmHg e frequência respiratória de\n32/min. Pulmões limpos bilateralmente, porém com diminuição dos murmúrios à esquerda. Exame\ncardíaco revela taquicardia sem outros comemorativos. Abdome sensível à palpação epigástrica.\nTem leucocitose de 26 mil/mm³, ECG de 12 derivações normais, RX de tórax com derrame pleural\nmoderado à esquerda, pneumotórax e pneumomediastino à esquerda. Em se tratando de uma\nruptura esofágica espontânea (Síndrome de Boerhaave), seu próximo passo é","options":{"A":"Manejo das vias aéreas, respiração e circulação (ABC).","B":"Drenagem torácica à esquerda.","C":"Administração de fluidos e antibiótico de amplo espectro.","D":"Todas as alternativas acima."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134113","number":"134113","sourceNumber":"134113","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A técnica de Ivor Lewis é uma técnica consagrada, caracterizada por","options":{"A":"Gastrectomia parcial e reconstrução com gastrojejunostomia pré-cólica.","B":"Gastrectomia parcial e reconstrução com gastrojejunostomia transmesocólica.","C":"Gastrectomia proximal e esofagectomia distal.","D":"Gastrectomia total e reconstrução com Y de Roux."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134823","number":"134823","sourceNumber":"134823","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No paciente com doença do refluxo gastroesofágico, cuja manometria revela uma\natividade peristáltica de 45% e amplitude da onda\nperistáltica distal de 21 mmHg, deve-se optar por:","options":{"A":"fundoplicatura total.","B":"esofagogastrectomia.","C":"fundoplicatura parcial.","D":"gastrectomia parcial a BII."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134117","number":"134117","sourceNumber":"134117","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Úlcera duodenal perfurada ou ruptura de baço podem ter dores referidas para qual\nregião anatômica?","options":{"A":"Dorsal supraclavicular.","B":"Membros inferiores.","C":"Hipogastro.","D":"Sacral."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134842","number":"134842","sourceNumber":"134842","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Indique a alternativa que contenha, CORRETAMENTE, o tipo histológico mais\ncomum de neoplasia gástrica e a classificação de neoplasia avançada.","options":{"A":"Linfoma e classificação de Boorman.","B":"Adenocarcinoma e classificação de Boorman.","C":"Carcinoma espinocelular e classificação de Boorman.","D":"Adenocarcinoma e classificação de Rezende."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134048","number":"134048","sourceNumber":"134048","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Manoel, 70 anos, com anemia microcítica hipocrômica. A endoscopia digestiva\nalta revelou gastrite inespecífica difusa. O\nteste respiratório foi positivo para presença do H.\npylori e exame histopatológico das biópsias gástricas mostrou linfoma Malt. A conduta MAIS\nadequada é","options":{"A":"Quimioterapia.","B":"Radioterapia.","C":"Gastrectomia.","D":"Tratar o H. pylori e estadiar a doença."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134056","number":"134056","sourceNumber":"134056","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A síndrome da alça aferente é em consequência","options":{"A":"da obstrução da anastomose Billroth I.","B":"da obstrução da anastomose Billroth II.","C":"do rápido esvaziamento gástrico da anastomose Billroth I.","D":"do rápido esvaziamento gástrico da anastomose Billroth II."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134862","number":"134862","sourceNumber":"134862","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No tratamento cirúrgico de Úlcera Péptica Duodenal, um procedimento é considerado\nMAIS fisiológico. Aponte-o.","options":{"A":"Vagotomia com antrectomia.","B":"Vagotomia seletiva com piloroplastia.","C":"Vagotomia troncular com piloroplastia.","D":"Vagotomia gástrica proximal."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-131347","number":"131347","sourceNumber":"131347","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A cirurgia mais eficaz para correção de refluxo gastroesofágico:","options":{"A":"Cirurgia de Lind.","B":"Cirurgia de Nissen.","C":"Cirurgia de Lotart-Jacob.","D":"Cirurgia de Merendino.","E":"Gastrectomia proximal."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-131352","number":"131352","sourceNumber":"131352","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Anel de Schatzki é achado em doença:","options":{"A":"Gástrica.","B":"Duodenal.","C":"Esofágica.","D":"Ileal.","E":"Retal."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-131387","number":"131387","sourceNumber":"131387","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Na doença do refluxo gastroesofágico, qual o exame complementar considerado como\npadrão-ouro?","options":{"A":"Manometria.","B":"Endoscopia.","C":"RX contrastado do esôfago.","D":"pHmetria.","E":"Cintilografia."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-110054","number":"110054","sourceNumber":"110054","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo masculino, 50 anos, com quadro de dor em região epigástrica há dois\ndias, é admitido no pronto-socorro com piora da dor. Tem antecedente de hipertensão arterial\nsistêmica e obesidade. Ao exame clínico, apresenta palpação dolorosa em região epigástrica e\nflancos. Raios X abdominal em posição ortostática revelam presença de ar em região\nsubdiafragmática bilateral. Hemograma com leucocitose e dosagem de amilase com valor duas\nvezes superior ao limite da normalidade. Assinale abaixo o diagnóstico MAIS provável:","options":{"A":"Pancreatite aguda.","B":"Úlcera duodenal perfurada.","C":"Colelitíase.","D":"Nefrolitíase."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-110546","number":"110546","sourceNumber":"110546","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"De acordo com o consenso Roma III, o tempo necessário de sintomas para que se faça\no diagnóstico de Dispepsia Funcional é:","options":{"A":"sintomas tenham iniciado a 12 meses e ativos nos últimos 3 meses.","B":"6 meses com sintomas presentes e ativos nos últimos 2 meses.","C":"sintomas tenham iniciado há pelo menos 6 meses e ativos nos últimos 3 meses.","D":"12 meses com sintomas presentes e 3 meses não necessariamente consecutivos.","E":"nenhuma das alternativas acima."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-110557","number":"110557","sourceNumber":"110557","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Dentre as alternativas abaixo, assinale a mais CORRETA em relação ao H. pylori:","options":{"A":"O H. pylori é uma bacilo espiralado Gram-positivo.","B":"Produz a enzima \"urease\" que facilita a sua colonização e multiplicação no epitélio\ngastrointestinal.","C":"Foi descoberta por Warren e Marshall em um final de semana prolongado no ano de 1993.","D":"Está presente em cerca de setenta por\ncento (70%) dos caso de úlcera duodenal.","E":"As alternativas \"A e B\" estão corretas."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-110584","number":"110584","sourceNumber":"110584","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em um paciente com Hemorragia Digestiva Alta de moderada a severa é correto\nafirmar:","options":{"A":"Hematêmese, melena, hipotensão arterial e taquicardia são sinais importantes no diagnóstico e\navaliação clinica do paciente.","B":"Hematêmese, melena, hipertensão arterial e taquicardia são sinais importantes no diagnóstico e\navaliação clínica do paciente.","C":"Em relação à mensuração da hemorragia considera-se uma perda moderada o paciente que\napresente PA = 90 a 100 mmHg, FC = 120 bpm e perda sanguínea em torno de 1.000 ml.","D":"As alternativas B e C estão corretas.","E":"As alternativas A e C estão corretas."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-109777","number":"109777","sourceNumber":"109777","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação à causa de abdome agudo hemorrágico, a MENOS provável é:","options":{"A":"laceração do fígado + baço no trauma.","B":"gravidez ectópica rota.","C":"úlcera perfurada + diverticulite aguda.","D":"laceração do mesentério no trauma."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-109780","number":"109780","sourceNumber":"109780","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Divertículo de Zenker está localizado no:","options":{"A":"íleo terminal.","B":"esôfago inferior.","C":"próximo apêndice vermiforme.","D":"esôfago proximal."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-109988","number":"109988","sourceNumber":"109988","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"NÃO deve ser passada a sonda nasogástrica às cegas, em casos de:","options":{"A":"Queimaduras extensas.","B":"Volvo de sigmoide.","C":"Gastrectomia parcial.","D":"Esofagite por soda cáustica."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-109719","number":"109719","sourceNumber":"109719","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O câncer gástrico precoce é definido como lesão que:","options":{"A":"atinge mucosa ou até submucosa.","B":"sempre só atinge mucosa.","C":"atinge mucosa ou até submucosa e, nunca ocorre comprometimento de linfonodos.","D":"atinge até a serosa."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-110030","number":"110030","sourceNumber":"110030","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Qual é a posição MAIS adequada de Raios-X simples de abdome que deve ser\nrealizada frente à suspeita de abdome agudo perfurativo?","options":{"A":"Em decúbito ventral.","B":"Em decúbito lateral esquerdo com raios horizontais.","C":"Em decúbito dorsal.","D":"Em Trendelemburg."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-110615","number":"110615","sourceNumber":"110615","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No estadiamento morfológico dos tumores do estômago, a classificação Bormann 4, é:","options":{"A":"Tumor ulcerado.","B":"Infiltrativo local.","C":"Infiltrativo difuso (Linite).","D":"Escavado.","E":"Ulcerado e infiltrativo local."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-110551","number":"110551","sourceNumber":"110551","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Neoplasia maligna do 1/3 médio do esôfago, o tipo histológico mais frequente é:","options":{"A":"Carcinoma epidermoide.","B":"Adenocarcinoma.","C":"Linfoma.","D":"Sarcoma.","E":"NDR."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-86685","number":"86685","sourceNumber":"86685","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"São ramos diretos da artéria aorta:","options":{"A":"Hepática comum, mesentérica superior e mesentérica inferior.","B":"Esplênica, tronco celíaco e renal direita.","C":"Mesentérica superior, tronco celíaco e renal esquerda.","D":"Renal direita, renal esquerda e hepática própria.","E":"Mesentérica inferior, torácica interna e esplênica."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-86622","number":"86622","sourceNumber":"86622","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em relação ao nervo vago, marque a alternativa INCORRETA:","options":{"A":"É o 10º par craniano.","B":"Possui fibras eferentes viscerais parassimpáticas.","C":"Acima do diafragma o nervo emite seus ramos principais.","D":"O tronco anterior recebe fibras predominantes do nervo vago direito.","E":"O nervo principal anterior (nervo de Latarjet anterior) tem origem no tronco anterior."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-86631","number":"86631","sourceNumber":"86631","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale a alternativa correta no tratamento da úlcera péptica complicada:","options":{"A":"O tratamento cirúrgico se impõe ao tratamento clínico.","B":"Na úlcera perfurada o tratamento cirúrgico é considerado como de exceção.","C":"Na hemorragia por úlcera, a endoscopia digestiva terapêutica só deve ser utilizada quando o\npaciente não tem condição cirúrgica.","D":"Cerca de 10% das obstruções do segmento gastroduodenal são atribuídos à causa péptica.","E":"Nos casos de estenose pilórica severa péptica, a cirurgia deve ser realizada imediatamente."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-158431","number":"158431","sourceNumber":"158431","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"As neoplasias malignas do esôfago podem ser divididas em epiteliais e não-epiteliais.\nDentre as lesões não epiteliais identificam-se,\nEXCETO:","options":{"A":"Sarcomas.","B":"Linfomas.","C":"Apudomas.","D":"Adenocarcinomas.","E":"Melanoma Primário."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-158436","number":"158436","sourceNumber":"158436","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação às úlceras gástricas e, mais especificamente, às fases de Sakita, assinale\na alternativa CORRETA:","options":{"A":"Cicatriz (A1 e A2).","B":"Ativa (A1 e A2).","C":"Cicatrização (A1 e A2).","D":"Cicatriz (H1 e H2).","E":"Cicatrização (S1 e S2)."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-158439","number":"158439","sourceNumber":"158439","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O estômago é a sede de tumores malignos e menos frequentemente de neoplasias\nbenignas. O adenocarcinoma é o tipo mais comum\nde neoplasia maligna do estômago. Uma vez\nestabelecido o diagnóstico, a ressecção cirúrgica se impõe. O estudo dos linfonodos dissecados e\nacometidos permite a classificação segundo a proposta da Union Internationale Contre le Cancer\n(UICC). Marque a CORRETA:","options":{"A":"Nx: sem linfonodos regionais acometidos.","B":"N0: linfonodos regionais não estão disponíveis para classificação.","C":"N3a: 1 a 6 linfonodos regionais não estão disponíveis para classificação.","D":"N2: 3 a 6 linfonodos regionais acometidos.","E":"N1: mais de 15 linfonodos acometidos."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-108567","number":"108567","sourceNumber":"108567","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em relação aos tumores estromais (GIST) do aparelho digestivo, marque a alternativa\nCORRETA. A ressecção do GIST gástrico e/ou de reto deve ser:","options":{"A":"Com margem de segurança de no mínimo 5 cm.","B":"Enucleação é suficiente.","C":"Sempre ressecção total do órgão.","D":"Ressecção segmentar.","E":"Não é necessária."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-108579","number":"108579","sourceNumber":"108579","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"É um medicamento utilizado para tratar refluxo gastroesofágico por reduzir a secreção\nde ácido clorídrico:","options":{"A":"Domperidona.","B":"Omeprazol.","C":"Metoclopramida.","D":"Betanecol.","E":"Albendazol."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-49630","number":"49630","sourceNumber":"49630","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em relação ao Câncer Gástrico, assinale a alternativa INCORRETA.","options":{"A":"A incidência de câncer gástrico está em declínio no Brasil.","B":"Consumo elevado de álcool e presença da bactéria H. Pylori são fatores relacionados ao\nsurgimento de câncer gástrico.","C":"O diagnóstico de câncer gástrico precoce pode ser definido por exame histopatológico e\necoendoscopia.","D":"A principal via de disseminação dos adenocarcinomas gástricos é linfonodal. Por esse motivo, a\nforma de recidiva mais comum é nos linfonodos perigástricos.","E":"O câncer gástrico precoce pode ser tratado por ressecção endoscópica."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-49627","number":"49627","sourceNumber":"49627","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"São indicações para tratamento do Helicobacter pylori, segundo o II Conselho Brasileiro\nsobre Helicobacter pylori, EXCETO:","options":{"A":"Úlcera gastroduodenal, ativa ou cicatrizada.","B":"Linfoma MALT de baixo grau.","C":"Gastrite endoscópica erosiva.","D":"Pós-ressecção de câncer gástrico precoce (endoscópica ou cirúrgica).","E":"Gastrite histológica intensiva."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-362513","number":"362513","sourceNumber":"362513","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo feminino, 45 anos, obesa, vem ao consultório queixando história de\npirose crônica que tratava no domicílio com chás caseiros. Evolui há cerca de 2 meses com\naumento da frequência da pirose, associada a dor retroesternal, regurgitação e perda de peso. Traz\nconsigo endoscopia digestiva que fez por conta própria, que evidenciou duas erosões de 75mm em\nesôfago distal, não coalescentes. Sobre o caso, assinale a alternativa CORRETA:","options":{"A":"Os sintomas típicos descritos pela paciente, associados aos seus achados endoscópicos,\nexcluem a necessidade de realização de Phmetria\nesofagiana para confirmação diagnóstica do\ncaso.","B":"Já que os sintomas apresentados não são típicos e os achados endoscópicos são inespecíficos,\no próximo passo para diagnóstico é o início de\nterapia com bloqueadores de bomba de prótons e\nrealização de Phmetria sem fio por 96 horas.","C":"A ausência de hérnia hiatal na endoscopia digestiva exclui diagnóstico de doença do refluxo\ngastroesofágico.","D":"O diagnóstico de acalasia será confirmado caso a Phmetria sem fio observe tempo de exposição\nda mucosa esofágica ao ácido gástrico menor que\n4% em todos os dias do exame."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-327253","number":"327253","sourceNumber":"327253","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo feminino, 62 anos, tabagista, hipertensa e diabética, com queixa de\nsintomas dispépticos há cerca de 6 meses. Em atendimento médico prévio, foi prescrito Omeprazol\n40mg diário, o qual fez uso por 4 meses, sem resposta satisfatória da sua sintomatologia, evoluindo\ncom anorexia. Evolui com emagrecimento de cerca de 5kg no período. Nega febre, uso crônico de\nanti-inflamatórios não hormonais e história familiar de neoplasias do trato gastrointestinal. Você\nsolicita endoscopia digestiva alta e esta evidencia lesão plana, com ulceração rasa e bordas\nelevadas, de cerca de 2cm, em incisura angularis. Qual das conclusões a seguir sobre o caso\ndescrito é falsa?","options":{"A":"Os dados fornecidos não nos permitem diferenciar com segurança diagnósticos como úlcera\nbenigna, neoplasia gástrica precoce ou neoplasia gástrica avançada.","B":"A observação de anorexia e perda de peso, associada ao fato de ulceração gástrica persistente\na despeito do tratamento com inibidor de bomba\nde prótons pode sugerir etiologia maligna para a\nlesão descrita.","C":"A cromoscopia com uso de corantes, a ecoendoscopia e a injeção de solução salina na camada\nsubmucosa abaixo da lesão podem fornecer\ndados referentes a possível ressecabilidade\nendoscópica da lesão.","D":"Uma vez que a endoscopia não evidenciou lesão tipo Borrmann IV, a conduta mais segura é o\ntratamento empírico para Helicobacter pylori, a troca do omeprazol pelo esomeprazol e a repetição\nda endoscopia após 4 meses."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-327257","number":"327257","sourceNumber":"327257","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo feminino, 43 anos, refere que, há 1 ano e meio, iniciou quadro de\ndisfagia inicialmente para sólidos que evoluiu progressivamente para disfagia para alimentos\npastosos, associada a regurgitação de alimentos não digeridos e tosse seca. Refere piora da\nregurgitação e tosse durante o decúbito, além de perda de 10kg no período. Seu exame físico\ncervical, torácico e abdominal não tem alterações relevantes. Solicitada endoscopia digestiva alta,\nesta evidenciou esofagite leve, discreta dilatação esofagiana, ausência de hérnia hiatal e discreta\nresistência do esfíncter esofagiano inferior (EEI) à insuflação com ar. Sobre o caso acima, assinale\na alternativa INCORRETA:","options":{"A":"O esofagograma baritado deve ser útil na avaliação do grau da doença e no seu direcionamento\nterapêutico.","B":"Uma adequada opção terapêutica para esta paciente é a Cirurgia de Heller associada a\nconfecção de válvula antirrefluxo à Lind.","C":"O exame padrão ouro para o diagnóstico do quadro acima é a Phmetria esofagiana que\nobservaria hipotonia da parede do esôfago e hipertonia do EEI.","D":"Tratamentos endoscópicos como a injeção de toxina botulínica ou dilatação pneumática do EEI\nsão opções terapêuticas à abordagem cirúrgica."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-298219","number":"298219","sourceNumber":"298219","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Os casos clínicos abaixo são sugestivos de Doença de Refluxo Gastroesifágico\n(DRGE), EXCETO:","options":{"A":"Paciente do sexo masculino, obeso, com história de episódio de pirose ocasional associada a\nalimentação copiosa rica em gordura e consumo de álcool, com endoscopia normal.","B":"Grávida de 32 semanas, queixando mais de 4 episódios de pirose após refeições por semana.","C":"Paciente do sexo masculino, 38 anos, com rouquidão crônica de difícil tratamento e volumosa\nhérnia de hiato à endoscopia.","D":"Neuropata, 2 anos de idade, com história de episódios frequentes de regurgitação de leite e\ninternações por pneumonia."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-286710","number":"286710","sourceNumber":"286710","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O tratamento da DRGE (Doença do Refluxo Gastroesofágico) objetiva controlar os\nsintomas, cicatrizar as lesões e prevenir as complicações. Fazem parte do tratamento da DRGE,\nEXCETO:","options":{"A":"Elevação da cabeceira da cama (15 cm).","B":"Moderação na ingestão dos seguintes alimentos, com observação à correlação com os\nsintomas: alimentos gordurosos, cítricos, café, chocolate, bebidas alcoólicas, hortelã e tomate.","C":"Inibidores da bomba de prótons em ciclo de 4 a 8 semanas de tratamento.","D":"Anticolinérgicos e antidepressivos tricíclicos."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-286731","number":"286731","sourceNumber":"286731","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo feminino, 32 anos, refere história de laringite crônica refratária a\ntratamentos convencionais, sendo diagnosticada com doença do refluxo gastroesofágico há cerca\nde 5 anos. Refere ter realizado endoscopia, Phmetria e esofagomanometria à época. A paciente\nentão iniciou tratamento com 40mg diários de Omeprazol com melhora da pirose e do quadro de\nlaringite, porém apresentava recorrências frequentes devido a uso irregular da medicação e não se\nadaptar adequadamente à dieta. Você é o quarto médico que esta paciente procura porque os\nmédicos anteriores ?não resolveram o problema?. O quadro vem piorando no último ano com\naumento da intensidade e frequência da pirose e aparecimento de tosse crônica. Realizou\nrecentemente e por conta própria uma endoscopia digestiva alta que revelou transição\nesofagogástrica 3cm acima da prega diafragmática, além de esofagite em terços médio e distal do\nesôfago, sem sinais macroscópicos de áreas sugestivas de metaplasia. Sobre o caso acima,\nassinale a alternativa CORRETA:","options":{"A":"Os dados fornecidos acima sugerem que a hiatoplastia com fundoplicatura laparoscópica parece\nser opção terapêutica adequada para esta\npaciente.","B":"Os dados fornecidos acima nos permitem afirmar que a conduta adequada só pode ser definida\napós realização de nova Phmetria e esofagomanometria.","C":"Já que o diagnóstico de hérnia hiatal não foi adequadamente fechado, o próximo passo na\ninvestigação desta paciente é o esofagograma baritado.","D":"A esofagite grave presente à endoscopia desta paciente nos leva a cogitar a indicação de\nesofagectomia devido ao iminente risco de malignização."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-256575","number":"256575","sourceNumber":"256575","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A hemorragia digestiva é uma ocorrência frequente nos atendimentos das emergências\nhospitalares. Trata-se de uma manifestação particularmente grave associada à mortalidade de 15 a\n20% dos pacientes. A fonte da maioria das hemorragias digestivas pode ser suspeitada pelos\nsintomas clínicos e exame físico e confirmadas pela endoscopia digestiva alta (EDA) e/ou\ncolonoscopia. Assinale a alternativa INCORRETA:","options":{"A":"A primeira conduta em pacientes com suspeita de hemorragia digestiva deve ser encaminha-los\nimediatamente para realização de endoscopia digestiva alta. Caso não seja evidenciado\nsangramento, deve-se iniciar o preparo expresso para realização de colonoscopia.","B":"A avaliação rápida e a ressuscitação devem preceder os procedimentos diagnósticos em\npacientes instáveis com hemorragia aguda grave.","C":"Na hemorragia digestiva alta a proteção das vias aéreas é importante, pela possibilidade de\naspiração do sangue vomitado ou regurgitado, o que está associado a significativas morbidade e\nmortalidade.","D":"A história clínica deve ser bem-feita, às vezes com a ajuda de familiares ou acompanhantes."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-256583","number":"256583","sourceNumber":"256583","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre o câncer gástrico difuso, as afirmações estão CORRETAS, EXCETO:","options":{"A":"Pode acometer pacientes mais jovens.","B":"Acometem mais o corpo gástrico e o cárdia.","C":"Pode estar associado ao grupo sanguíneo ?O?.","D":"Tendência a invadir precocemente toda a espessura da parede gástrica."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-256589","number":"256589","sourceNumber":"256589","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A incidência e mortalidade de câncer gástrico tem reduzido substancialmente em\ngrande parte do mundo desenvolvido nas\núltimas décadas. Entretanto, cânceres do trato\ngastrointestinal superior originados no estômago, esôfago ou junção esofagogástrica ainda\nconstituem o maior problema mundial de saúde, especialmente nos países de baixa e média renda.\nGlobalmente, havia uma estimativa de 1,03 milhão de casos resultando em 780.000 mortes em\n2018, tornando o câncer gástrico o 5º câncer diagnosticado mais frequente e o 3º relacionado a\nmortes no mundo. Mais de 95% dos cânceres gástricos são Adenocarcinomas, que são\nclassificados baseados na localização anatômica, como Distal e Proximal, e tipo histológico, como\nDifuso e Intestinal. Sobre o câncer gástrico intestinal, qual a questão que não mostra um fator\nambiental relacionado ao risco desse tipo de câncer gástrico?","options":{"A":"Ingesta rica em sal","B":"Tabagismo","C":"Associação com álcool","D":"Infecção pelo Helicobacter pilory"},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-252238","number":"252238","sourceNumber":"252238","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente com epigastralgia refratária, realizou endoscopia com identificação de várias\nlesões ulceradas em estômago e dosagem de gastrina elevada. Que síndrome pode estar\nrelacionada?","options":{"A":"Paterson Kelly.","B":"Zolinger Ellison.","C":"Mallory Weiss.","D":"Prune Belly."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-208437","number":"208437","sourceNumber":"208437","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Uma paciente do sexo feminino, 55 anos, entra no seu consultório com queixa\ndispéptica crônica. Por ser procedente de\nmunicípio do Interior do Estado, o único exame que pôde\nser realizado na sua cidade foi radiografia contrastada de esôfago, estômago e duodeno. O exame\nevidencia imagem que sugere lesão ulcerada em região antral, com dificuldade de passagem de\ncontraste para o duodeno. Assinale a alternativa CORRETA:","options":{"A":"Há indicação precisa de endoscopia digestiva alta com biópsia para definição do caráter\n(benigno ou maligno) da lesão.","B":"Os dados acima são suficientes para afirmar a necessidade de gastrectomia total para esta\npaciente.","C":"Vômitos contendo alimentos não digeridos, melena e perda de peso são elementos que\nprovavelmente estarão presentes na história detalhada desta paciente.","D":"A observação de ascite, prateleira de Blumer e esplenomegalia ao exame físico indicam\nprognóstico ruim para esta paciente."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-208432","number":"208432","sourceNumber":"208432","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo feminino, 46 anos, vem à avaliação médica com história de pirose há\nmuitos anos, frequentemente associada a alimentação copiosa rica em gordura, refrigerantes e\ncafé. Controla a sintomatologia com chás caseiros, hidróxido de alumínio e antiácidos\nefervescentes. Foi submetida a endoscopia digestiva alta que evidenciou áreas de epitélio\navermelhado em esôfago distal, medindo 5 cm acima da linha Z. A biópsia revelou tratar-se de\nmetaplasia colunar e áreas de displasia de alto grau. Qual das seguintes orientações a esta\npaciente é inadequada?","options":{"A":"A senhora apresenta um quadro de doença do refluxo gastroesofágico bastante complicada que\nse não for tratado adequadamente pode\nevoluir para um câncer.","B":"As chances dessa metaplasia no esôfago que apareceu na sua endoscopia melhorar apenas\ncom remédios é muito baixa.","C":"Seu exame demonstra que a cirurgia de fundoplicatura evitará que a sua lesão do esôfago se\ntransforme em câncer.","D":"A senhora tem indicação de tratamento cirúrgico, mas antes deveremos iniciar tratamento com\nmedicações em dose máxima por 3 meses e repetir a endoscopia para ver se a displasia melhorou."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-176103","number":"176103","sourceNumber":"176103","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo masculino, 55 anos, apresenta disfagia progressiva de sólidos para\nlíquidos há 4 meses, associada a perda ponderal. Traz consigo esofagograma contrastado que\nrevela imagem de subtração com contornos irregulares em terço médio do esôfago. Marque a\nalternativa CORRETA:","options":{"A":"A lesão é compatível com leiomioma e deve-se proceder à esofagectomia.","B":"Deve-se realizar endoscopia digestiva alta com biópsia, sendo o resultado mais provável\ncarcinoma epidermoide.","C":"Essa imagem se trata de uma provável complicação do esôfago de Barrett.","D":"Uma boa opção terapêutica é realizar endoscopia associada à dilatação com balão."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-176009","number":"176009","sourceNumber":"176009","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Qual o sintoma mais comum no câncer de esôfago?","options":{"A":"Disfagia e perda ponderal.","B":"Tosse e vômitos.","C":"Odinofagia e tosse.","D":"Hematêmese e pneumonia de aspiração."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-176017","number":"176017","sourceNumber":"176017","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Qual a localização mais comum do tumor estromal gastrointestinal?","options":{"A":"Intestino delgado.","B":"Mesentério.","C":"Esôfago.","D":"Estômago."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-176030","number":"176030","sourceNumber":"176030","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em relação aos divertículos de esôfago, assinale a alternativa INCORRETA:","options":{"A":"O divertículo esofágico mais comum é o divertículo de Zenker, que ocorre na junção da\nfaringe ao esôfago.","B":"Os divertículos epifrênicos, assim como os parabronquiais, são divertículos verdadeiros.","C":"Divertículos de pulsão são divertículos falsos, decorrentes de altas pressões intraluminares.","D":"Divertículos parabronquiais resultam de reações inflamatórias externas nos linfonodos\nadjacentes."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-176038","number":"176038","sourceNumber":"176038","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre acalasia, é INCORRETO afirmar:","options":{"A":"É considerada uma lesão pré-maligna, pois pode levar, após anos de evolução, ao\ndesenvolvimento de carcinoma de esôfago, sendo o tipo histológico mais comum o\nadenocarcinoma.","B":"A tríade clássica dos sintomas inclui disfagia, regurgitação e perda de peso.","C":"Ao exame de manometria, ocorre falha de relaxamento do esfíncter esofágico inferior em\nresposta à deglutição.","D":"Estágios mais avançados levam à dilatação maciça e tortuosidade do órgão, o chamado\nmegaesôfago."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-176043","number":"176043","sourceNumber":"176043","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No tratamento cirúrgico da doença do refluxo gastroesofágico, a fundoplicatura à\nNissen corresponde à confecção de uma válvula de:","options":{"A":"360º.","B":"270º.","C":"180º anterior.","D":"180º posterior."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-176051","number":"176051","sourceNumber":"176051","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Os tipos de úlcera péptica que estão relacionados à hipercloridria são:","options":{"A":"I e II.","B":"I e IV.","C":"II e III.","D":"II e IV."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-151871","number":"151871","sourceNumber":"151871","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Caracteriza histologicamente o esôfago de Barrett a presença de:","options":{"A":"Epitélio colunar.","B":"Epitélio cilíndrico.","C":"Células caliciformes.","D":"Células eosinofílicas."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-151921","number":"151921","sourceNumber":"151921","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A cirurgia de Heller é indicada para portadores de:","options":{"A":"Acalásia.","B":"Úlcera péptica.","C":"Divertículo de Zenker.","D":"Síndrome de Plummer-Vinson."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-151932","number":"151932","sourceNumber":"151932","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O teste respiratório da ureia marcada com carbono 13 é usado no controle da\nerradicação de:","options":{"A":"Helicobacter pylori.","B":"Clamidia tracomatis.","C":"Papilomavírus humano.","D":"BAAR (Bacilo Álcool Ácido Resistente)."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-151997","number":"151997","sourceNumber":"151997","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre a úlcera péptica perfurada todas a alternativas estão corretas, EXCETO:","options":{"A":"O exame físico abdominal mostra sinal de irritação peritoneal.","B":"A radiografia de tórax em ortostase mostra pneumotórax livre.","C":"Quase sempre o paciente pode dar a hora exata do início da dor lancinante.","D":"O tratamento clínico é indicado apenas quando há evidências de que a ferida tenha se fechado\ne na ausência de peritonite química."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-151966","number":"151966","sourceNumber":"151966","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"São indicações cirúrgica de úlcera péptica hemorrágica, EXCETO:","options":{"A":"Quando a úlcera está associada ao Helicobacter pylori.","B":"Ausência de disponibilidade de sangue para transfusão.","C":"Hemorragia maciça não responsiva a tratamento endoscópico.","D":"Necessidade de transfusão de mais de 4 a 6 unidades de concentrado de hemácias, apesar das\ntentativas de controle endoscópico."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-151878","number":"151878","sourceNumber":"151878","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Define-se como carcinoma gástrico precoce:","options":{"A":"Limitado à mucosa e submucosa com linfonodo não contaminado.","B":"Limitado somente à mucosa e sem envolvimento de linfonodo.","C":"Limitado à mucosa e submucosa, independentemente do estado do linfonodo.","D":"Limitado à parede gástrica, sem invadir a serosa ou órgãos vizinhos."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-151901","number":"151901","sourceNumber":"151901","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo feminino, 45 anos, sobrepeso, vem ao consultório de cirurgia,\nencaminhada do otorrinolaringologista,\nqueixando pirose e regurgitação ácida após alimentação\nrica em gordura e ácidos. Tais sintomas ocorrem quase que diariamente há cerca de 2 anos e\npioraram após gravidez e ganho de peso. Refere ainda dor torácica esporádica, retroesternal em\nqueimação, não relacionada a exercícios físicos, episódios ocasionais de disfonia e sensação de\nglobo faríngeo. Nega disfasia e hematêmese. Seu exame físico não tem alterações. Traz consigo\numa endoscopia digestiva alta que evidencia hérnia hiatal de 2 cm e ausência de lesões\nesofagianas, tais como ulcerações ou esofagite. Assinale a alternativa INCORRETA:","options":{"A":"A ausência de lesões esofagianas à endoscopia não exclui a hipótese de Doença do Refluxo\nGastroesofágico (DRGE), havendo necessidade de prosseguir com a investigação diagnóstica.","B":"A esofagomanometria não fecha diagnóstico de DRGE, porém pode evidenciar situações, tais\ncomo a hipotonia do esfíncter esofagiano inferior, que são sugestivas deste diagnóstico.","C":"A demonstração de refluxo gastroesofágico através do exame contrastado do esôfago tem maior\nsensibilidade e especificidade no diagnóstico de DRGE que a pHmetria esofagiana.","D":"Caso esta paciente não se adapte ao tratamento clínico com uso crônico de inibidores da bomba\nde prótons, a indicação de fundoplicatura\ngástrica com hiatoplastia via laparoscópica deve ser\nconsiderada."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-151905","number":"151905","sourceNumber":"151905","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Considerando o linfoma MALT de baixo grau, qual o tratamento de escolha como\nprimeira linha?","options":{"A":"Radioterapia.","B":"Quimioterapia.","C":"Quimioradioterapia.","D":"Erradicação do Helicobacter pylori."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-129752","number":"129752","sourceNumber":"129752","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"As alternativas sobre a erradicação de H. pylori são verdadeiras, EXCETO:","options":{"A":"A cura da infecção prognóstica, uma taxa bastante reduzida de recorrência de úlcera.","B":"A terapia antimicrobiana adequada leva à erradicação em mais de 80% dos casos.","C":"O tratamento bem-sucedido pode ser documentado repetindo-se a sorologia em quatro a seis\nsemanas.","D":"Os pacientes em uso crônico de aspirina ou anti-inflamatórios têm indicação de pesquisa e\nerradicação da infecção."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-129760","number":"129760","sourceNumber":"129760","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Endoscopia digestiva alta é indicada para todas as condições, EXCETO:","options":{"A":"Um homem de 62 anos de idade com uma úlcera gástrica tratada há 30 dias, tem necessidade\nde repetir o exame de endoscopia.","B":"Uma mulher de 26 anos de idade, HIV-positiva, com odinofagia.","C":"Um homem de 32 anos de idade com polipose adenomatosa familiar de diagnóstico recente.","D":"Uma mulher de 65 anos de idade sem ruídos intestinais, com abdome rígido, descompressão\ndolorosa e com história pregressa de úlcera\npéptica."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-139139","number":"139139","sourceNumber":"139139","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O esôfago de Barret caracteriza-se:","options":{"A":"Seu epitélio faz semelhança com as células cilíndricas.","B":"Por apresentar células caliciformes de permeio a células cilíndricas.","C":"Originar a síndrome de Plummer Vinson.","D":"Pela linhagem glandular no epitálio escamoso."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-129795","number":"129795","sourceNumber":"129795","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"OGM, 67 anos, masculino, procedência Santa Isabel do Rio Negro-AM, vem evoluindo\ncom disfagia progressiva com piora extrema há\n90 dias, aproximadamente, associada a um quadro\nde tosse produtiva e sialorreia intensa. Concomitante ao quadro, foi tratado de pneumonia com\ninternação recente. Emagrecimento de 15 kg. Constipação de 7 dias desde a faixa dos seus 30 - 40\nanos, aliviando com laxativos e enteroclismas. Cardiopatia, fazendo uso de anti-arrítmicos. Nega\nhematêmese e ou melena; fumante desde os 16 anos, alcoolismo crônico (cachaça e cerveja). Ao\nexame físico apresenta-se: MEG, emagrecido, dispneico, com sialorreia freqüente, sem sangue de\npermeio, anictérico, afebril. Anemia +/+++, língua saburrosa, sem linfonodomegalia, perda muscular\n(cervical, torácica, abdominal, mmiis): sem linfonomegalia cervical e ou fúrculas; ausculta pulmonar\nnotadamente caracterizada por estertores creptantes em terço médio do HTE, arritmias cardíacas\nesparsas; abdome distendido, desconfortável, sem cicatrizes, indolor, sem visceromegalias,\ntimpanismo em trajeto colônico. Toque retal apresentando volumoso fecaloma, pétreo;\n\ndedo-de-luva sem sangue. Submetido à radiografia do esôfago com contrastre iodado que revelou\nfistula esôfago-brônquica em contiguidade com o\nsegmento de pulmão esquerdo; endoscopia\ndigestiva alta apresentando uma lesão estenosante (impedia a passagem do aparelho), a 25\ncentímetros da ADS; laudo anátomo-patológico revelou carcinoma escamocelular; TC de tórax:\npresença de linfonodomegalias paratraqueais e interbrônquios circundando uma massa sólida de 5\ncm no seu maior diâmetro em topografia de hilo pulmonar esquerdo. Clíster opaco: dolicocolon e\nfecaloma segmentar em sigmoide e reto. Pelo exposto e considerando o manejo clínico dos\ntumores do esôfago, responda a questão: Considerando a inoperabilidade do caso acima, são\nmétodos paliativos para os tumores do esôfago, EXCETO:","options":{"A":"Terapia Nutricional Parenteral.","B":"Stent Esofágico.","C":"Quimioradioterapia.","D":"Jejunostomia e Esôfago-Gastro-Coloplastia."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-129784","number":"129784","sourceNumber":"129784","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Desde muitas décadas passadas, vem sendo observada uma diminuição espetacular\nna taxa de morte e na incidência de câncer\ngástrico nos EUA e nos países desenvolvidos do\nOcidente. Considerando a classificação de Lauren, qual a forma de câncer que mais se reduziu\nneste processo de involução?","options":{"A":"Carcinoma em \"anel de sinete\".","B":"Tipo difuso.","C":"Tipo intestinal.","D":"Carcinoide."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-129787","number":"129787","sourceNumber":"129787","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em 1962, foi definido pela Sociedade Japonesa para Pesquisa de Câncer Gástrico um\ntipo de lesão limitada à mucosa ou submucosa, independentemente da presença ou não de\nmetástase para linfonodo denominado:","options":{"A":"Carcinoma avançado.","B":"Carcinoma precoce ou incipiente.","C":"Carcinoma invasivo.","D":"Carcinoma intestinal."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-129792","number":"129792","sourceNumber":"129792","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"As lesões benignas do estômago vem sendo o foco de discussões em grandes eventos\ncientíficos pela peculiaridade de transformação carcinogênica. Das lesões abaixo citadas, quais as\nde maior incidência?","options":{"A":"Lipoma","B":"Leiomioma","C":"Pólipos epiteliais.","D":"Tumor neurogênico."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-103806","number":"103806","sourceNumber":"103806","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O divertículo faringoesofagico de Zenker:","options":{"A":"É classificados como divertículo de tração.","B":"Em geral aparece na segunda década da vida.","C":"É formado com camada de mucosa e submucosa.","D":"Ocorre entre as fibras do músculo platisma e cricofaríngeo."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-103857","number":"103857","sourceNumber":"103857","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Esôfago com peristalse hipertensa ou contrações de alta amplitude. Sem predileção por\nfaixa etária ou sexo e é o distúrbio de hipermotilidade esofágica mais comum e o mais doloroso,\ncaracteriza:","options":{"A":"Acalásia.","B":"Espasmo esofágico difuso.","C":"Esôfago quebra-nozes.","D":"Esfíncter Esofagiano Inferior (EEI) hipertenso."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-107661","number":"107661","sourceNumber":"107661","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo masculino, 54 anos, será submetido à gastrectomia subtotal por\nadenocarcinoma de estômago. É diabético, hipertenso e faz uso de glibenclamida, losartana e AAS,\nalém do uso crônico de prednisona para o tratamento de artrite reumatoide. Sobre os cuidados\n\npré-operatórios deste paciente, assinale a alternativa INCORRETA:","options":{"A":"O paciente deve suspender o uso do hipoglicemiante oral durante o período da internação e seu\ncontrole glicêmicos será feito com medidas regulares de glicemia capilar e uso de insulina NPH de\nacordo com o resultado das glicemias.","B":"A paciente deve continuar o uso do anti-hipertensivo oral, mesmo no dia do procedimento\ncirúrgico e no pós-operatório imediato.","C":"A Prednisona deve ser suspensa no dia da cirurgia, porém devemos substitui-la por\nhidrocortisona venosa devido ao risco de insuficiência adrenal aguda.","D":"O uso do AAS deve ser suspenso 7 dias antes do procedimento cirúrgico devido ao risco de\nsangramento, porém há indicação precisa do uso de heparina de baixo peso molecular subcutânea\ndurante a internação."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-107706","number":"107706","sourceNumber":"107706","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo feminino, 28 anos, obesa, vem ao ambulatório com queixa de pirose\ncrônica, principalmente após alimentação copiosa, rica em gordura e condimentados. Ela traz\nconsigo endoscopia digestiva alta que evidencia esôfago de elasticidade preservada, com transição\nesôfago-gástrica a nível do pinçamento diafragmático, apresentando lesões avermelhadas\nsemelhantes à mucosa gástrica em seu terço distal, cuja biópsia evidenciou tratar-se de metaplasia\ncolunar. O estômago encontrava-se hiperemiado (gastrite enantematosa), sem outras lesões.\n\nAnalise as assertivas abaixo e assinale a alternativa INCORRETA: I. A esofagomanometria é o\nexame de maior sensibilidade para\ndiagnosticar a patologia de base do paciente acima; II. Já que\nnão há hérnia hiatal, não há indicação de tratamento cirúrgico; III. O esofagograma contrastado e a\nPhmetria esofagiana são exames dispensáveis na avaliação do caso acima; IV. Caso o tratamento\nnão seja adequado, há possibilidade de evolução do caso para carcinoma escamocelular de\nesôfago; V. A ranitidina é medicação obrigatória no tratamento deste paciente.","options":{"A":"As assertivas III e IV são incorretas.","B":"Todas são falsas.","C":"As assertivas II e V são incorretas.","D":"A assertiva IV não é correta já que a neoplasia de evolução provável no caso é o linfoma\nesofagiano."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-87450","number":"87450","sourceNumber":"87450","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo feminino, 45 anos, chega ao pronto-socorro com quadro de\nhematêmese. Apresenta história de epigastralgia\nem queimação com evolução de vários anos e\nassociação com alimentos ácidos e com temperos fortes. Evoluiu há cerca de 4 meses com\naumento discreto da dor e plenitude pós-prandial progressiva. Vômitos alimentares. Perda de peso\nde 15 kg nos últimos 2 meses. Ao exame físico, apresenta-se ansiosa, pálida, emagrecida e\nanictérica. O abdome é plano, flácido, com massa palpável pouco dolorosa em epigástrio. Não\nhavia linfadenomegalias. Toque retal sem alterações. A paciente acima foi submetida à laparotomia\nexploradora, que evidenciou massa gástrica volumosa a nível de região pilórica não aderida a\nplanos profundos, moderada quantidade de ascite, linfonodomegalia adjacente à aorta abdominal e\nlesões nodulares difusas em peritônio e mesocólon. Assinale a alternativa CORRETA:","options":{"A":"Já que a massa gástrica é restrita ao antro e não invade planos profundos, podemos afirmar que\nhá chance de cura para esta paciente.","B":"A presença de ascite não interfere no prognóstico desta paciente.","C":"A gastrectomia parcial não faz parte das opções terapêuticas para esta paciente.","D":"Já que o paciente não apresentava linfonodo de Virchow, linfonodo de Sister Mary Joseph ou\nprateleira de Blummer, o prognóstico é bom.","E":"A USG no estadiamento pré-operatório indicaria provável tratamento paliativo."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-87456","number":"87456","sourceNumber":"87456","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Todos os eventos abaixo podem ocorrer na acalásia, EXCETO:","options":{"A":"Espasmo patológico do esfíncter esofagiano inferior.","B":"Úlcera esofagiana por refluxo gastroesofágico.","C":"Retenção alimentar e vômitos de alimentos não digeridos.","D":"Megaesôfago.","E":"Imagem de \"bico de pássaro\" à radiografia contrastada de esôfago."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-81111","number":"81111","sourceNumber":"81111","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"<p>Paciente do sexo feminino vem ao consultório do cirurgião portando endoscopia\ndigestiva alta com diagnóstico de processo\nmitótico ulceroinfiltrativo em pequena curvatura gástrica,\nsem confirmação histopatológica até o momento. Ao exame físico, apresenta-se emagrecida,\nhipocorada ++/4, anictérica e normotensa. Apresenta linfonodo palpável supraclavicular esquerdo.\nSeu abdome é plano, flácido, indolor à palpação. Não há massa epigástrica palpável, mas\nevidencia-se discreta ascite à palpação. Toque retal normal. Assinale a alternativa\nINCORRETA:</p>","options":{"A":"Espera-se que a biópsia da lesão revele adenocarcinoma gástrico.","B":"Os dados clínicos acima nos permitem afirmar que se trata de neoplasia gástrica incurável,\nporém não há dados suficientes para avaliar\nsua ressecabilidade.","C":"O toque retal normal exclui a possibilidade de tumoração de Krukenberg no caso acima.","D":"A paciente acima pode evoluir com hemorragia digestiva alta ou abdome agudo perfurativo.","E":"O próximo passo para estadiamento adequado deste paciente é a tomografia computadorizada."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-81983","number":"81983","sourceNumber":"81983","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Principal causa de perfuração do esôfago:","options":{"A":"Ingesta de corpo estranho.","B":"Trauma por arma branca.","C":"Instrumentação endoscópica.","D":"Trauma por projetil de arma de fogo.","E":"Lesão inadvertida durante procedimento na traqueia."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-61575","number":"61575","sourceNumber":"61575","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Desde que foi isolado e identificado em 1983, por Marshall e seu então residente\nWarren, o Helicobacter pylori tem sido\nassociado a várias doenças gastrointestinais. Tal descoberta\nfoi de tamanha importância que mereceu o prêmio Nobel de Medicina de 2005. Até o momento, faz\nparte do consenso brasileiro a pesquisa e erradicação do H. Pylori nas seguintes situações:","options":{"A":"Úlcera gastroduodenal, Linfoma MALT de baixo grau, pós-ressecção de câncer gástrico precoce,\nfamiliar de 1º grau com câncer gástrico.","B":"Úlcera gastroduodenal, Linfoma MALT de baixo grau, pós-ressecção de câncer gástrico precoce,\nfamiliar de 1º grau com câncer gástrico. Doença do refluxo gastroesofágico.","C":"Pacientes de risco para úlcera ou complicações que deverão usar cronicamente AAS em doses\nbaixas. Doença do refluxo gastroesofágico, úlcera gastroduodenal, Linfoma MALT de baixo grau.","D":"Úlcera gastroduodenal, Linfoma MALT de baixo grau, pós-ressecção de câncer gástrico precoce,\ndispepsia funcional, pacientes de risco para úlcera ou complicações que deverão usar\ncronicamente AAS em doses baixas.","E":"Pacientes de risco para úlcera ou complicações que deverão usar cronicamente AAS em doses\nbaixas, uso crônico de anticoagulantes como o marevan, úlcera gastroduodenal, Linfoma MALT de\nbaixo grau, pós-ressecção de câncer gástrico precoce."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-60870","number":"60870","sourceNumber":"60870","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre a doença ulcerosa péptica complicada com hemorragia digestiva, é CORRETO\nafirmar que:","options":{"A":"A endoscopia digestiva alta não é o melhor método para controlar o sangramento","B":"Pode-se estimar a perda volêmica pelo exame físico num sangramento agudo","C":"O tratamento para Helicobacter pylori não diminuiu significativamente no número de cirurgias","D":"Pacientes em uso de anti-inflamatórios não hormonais por via oral devem mudar para via\nparenteral","E":"Os antagonistas de receptores H2 (histamina) são tão efetivos quanto os inibidores de bomba de\nprótons no tratamento e prevenção de recidiva"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-60882","number":"60882","sourceNumber":"60882","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente após queimadura térmica envolvendo mais de 50% da superfície corporal, foi\ninternado em estado grave em unidade de terapia intensiva. Após todos os cuidados referentes à\nqueimadura e hidratação, paciente evolui com hemorragia digestiva alta. Qual a principal hipótese\ndiagnóstica?","options":{"A":"Úlcera de Curling","B":"Distúrbio de coagulação","C":"Lesão gástrica de Dieulafoy","D":"Laceração de Mallory-Weiss","E":"Doença de Ménétrier, devido à gastrite hipertrófica"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-60889","number":"60889","sourceNumber":"60889","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre câncer gástrico, o tipo histológico adenocarcinoma tipo difuso de Lauren, está\nmais frequentemente associado às condições abaixo, EXCETO:","options":{"A":"Pacientes jovens.","B":"Tipo sanguíneo A.","C":"Células em anel de sinete.","D":"Disseminação transmural/linfática.","E":"Associado a H. Pylori, atrofia gástrica e metaplasia intestinal."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-60898","number":"60898","sourceNumber":"60898","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Qual a localização mais comum do linfoma no sistema gastrointestinal?","options":{"A":"Pâncreas.","B":"Estômago.","C":"Intestino delgado.","D":"Apêndice vermiforme.","E":"Canal anal e reto baixo."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-46638","number":"46638","sourceNumber":"46638","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Disfagia com perda da peristalse esofagiana, ocasionado por perda ou diminuição de\ncélulas ganglionares no plexo mioentérico, o que ocasiona relaxamento ineficaz do esfíncter\nesofagiano inferior:","options":{"A":"Megaesôfago Chagásico","B":"Esôfago em Quebra Nozes","C":"Divertículo de Zenker","D":"Acalasia","E":"Esôfago de Barret"},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-49802","number":"49802","sourceNumber":"49802","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A Síndrome de Mallory-Weis geralmente é associada a:","options":{"A":"Doença ulcerosa péptica;","B":"Alcoolismo;","C":"Carcinoma;","D":"Hérnia hiatal;","E":"Monilíase."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-46670","number":"46670","sourceNumber":"46670","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Tumores de interesse clínico e experimental recente, devido identificação da ativação\ndo receptor c-Kit (mutação oncogênica), e o\ndesenvolvimento de um agente terapêutico que\nsuprime o crescimento tumoral (mesilato de imatinibe):","options":{"A":"Adenocarcinoma Gástrico","B":"Tumores Estromais Gástricos","C":"Tumor Carcinoide","D":"Linfoma não Hodgkin","E":"Cistoadenocarcinoma mucinoso do apêndice"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-34173","number":"34173","sourceNumber":"34173","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre adenocarcinoma gástrico tipo intestinal de Lauren, qual das alternativas abaixo é\nverdadeira?","options":{"A":"Apresenta forte fator familiar e está relacionado ao tipo sanguíneo A.","B":"Apresenta atrofia gástrica ou metaplasia intestinal como condição pré-neoplásica.","C":"Apresenta células em anel de sinete.","D":"Apresenta maior disseminação transmural e por via linfática.","E":"Afeta grupo de pacientes mais jovens."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-34103","number":"34103","sourceNumber":"34103","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O distúrbio metabólico mais comum após gastrectomia é:","options":{"A":"Anemia megaloblástica.","B":"Hipoglicemia.","C":"Absorção prejudicada de gordura.","D":"Deficiência de cálcio.","E":"Anemia ferropriva."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-34105","number":"34105","sourceNumber":"34105","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Qual a localização mais comum no trato digestivo do GIST (tumor estromal\ngastrointestinal)?","options":{"A":"Intestino delgado.","B":"Estômago.","C":"Intestino grosso.","D":"Esôfago.","E":"Pâncreas."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-34133","number":"34133","sourceNumber":"34133","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O gastrinoma é o tumor endócrino pancreático mais sintomático. Que outros tumores\npodem, também, processar a progastrina até\ngastrina, produzindo a Síndrome de Zollinger-Ellison?","options":{"A":"Tumor de Ovário.","B":"Tumor de Pulmão.","C":"Neuroma Acústico.","D":"Tumor de Cólon.","E":"Tumor de Hipófise."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-26460","number":"26460","sourceNumber":"26460","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A dor epigástrica em queimação noturna está mais relacionada a:","options":{"A":"Úlcera gástrica","B":"Úlcera duodenal","C":"Úlcera de estresse","D":"Esofagite","E":"Gastrinoma"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-26462","number":"26462","sourceNumber":"26462","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em relação ao câncer gástrico qual afirmativa é verdadeira?","options":{"A":"O adenocarcinoma difuso é mais agressivo tem metástase salteada e geralmente tem\nassociação com gastrite","B":"O tratamento do H.pylori tem reduzido a incidência de neoplasia gástrica proximal","C":"O linfoma MALT tem condições de ser tratado clinicamente com antibioticoterapia e bloqueador\nde bomba de Próton sem indicação de ressecção\ncirúrgica","D":"O adenocarcinoma tipo intestinal tem que ser tratado cirurgicamente com ressecção total do\nórgão","E":"Não existe afirmação correta acima"},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-26463","number":"26463","sourceNumber":"26463","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Uma mulher, 55 anos, com história de acalasia há 20 anos sem tratamento, chega ao\nseu consultório relatando disfagia de início\ninsidioso que progressivamente piorou para alimentos\nsólidos há 8 meses, associada a regurgitações frequentes de alimentos não digeridos, dor torácica\ne perda de peso de 10 kg. Diante de tal quadro qual seria sua principal hipótese diagnóstica?","options":{"A":"DRGE","B":"Adenocarcinoma de esôfago","C":"Câncer epidermoide de esôfago","D":"Espasmo esofagiano difuso","E":"Mega esôfago"},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-26464","number":"26464","sourceNumber":"26464","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Uma mulher, 55 anos, com história de acalasia há 20 anos sem tratamento, chega ao\nseu consultório relatando disfagia de início\ninsidioso que progressivamente piorou para alimentos\nsólidos há 8 meses, associada a regurgitações freqüentes de alimentos não digeridos, dor torácica\ne perda de peso de 10 kg. O teste mais específico para predizer o potencial curativo da ressecção\ncirúrgica da doença esofágica deste paciente seria:","options":{"A":"Broncoscopia","B":"Ressonância Magnética","C":"Ultrassonografia endoscópica","D":"Peritonioscopia","E":"Ultrassonografia transabdominal do fígado"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-26687","number":"26687","sourceNumber":"26687","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem de 50 anos de idade, com história de lombalgia crônica usuário de diclofenaco\ndá entrada no Pronto-Socorro com quadro de\nHematêmese e melena. Ao exame clínico de\nadmissão apresenta-se descolorado com FC=120bpm e PA= 90x60 mmHg. Considerando o\ntratamento inicial e a avaliação diagnóstica realizados neste caso é correto afirmar que:","options":{"A":"Deve-se realizar a endoscopia digestiva alta mesmo com instabilidade hemodinâmica na\ntentativa do controle hemostáticos do foco hemorrágico","B":"Deve-se realizar a endoscopia digestiva alta após radiografia de abdome para descartar\nabdome agudo perfurado","C":"A avaliação clínica permite excluir sangramento ativo, e o doente deve ser mantido em\nobservação, com prescrição de omeprazol endovenoso e pedido de endoscopia eletiva","D":"A endoscopia digestiva alta deve ser realizada somente após a reposição volêmica e\nestabilização hemodinâmica","E":"A avaliação clínica permite excluir sangramento ativo e o paciente pode receber alta com\npresecrição de omeprazol"},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-26688","number":"26688","sourceNumber":"26688","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente com história de epigastralgia e emagrecimento submete-se a endoscopia\ndigestiva alta que acusa a presença de uma lesão infiltrante de margens mal definidas no antro\ngástrico. O exame histopatológico sugere a diagnóstico de linfoma de MALT. O principal fator de\nrisco para esta neoplasia é a presença de:","options":{"A":"Gastrite hipertrófica","B":"Úlcera péptica","C":"Hipoclordria","D":"Pólipo gástrico adenomatoso","E":"Gastrite pelo H.pylori"},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-26671","number":"26671","sourceNumber":"26671","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"São fatores ambientais de risco para câncer gástrico, exceto:","options":{"A":"Infecção por H. pylori","B":"Hábito de fumar","C":"Baixo nível sócio-econômico","D":"Grupo sanguíneo tipo A","E":"Consumo de alimentos defumados"},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-26679","number":"26679","sourceNumber":"26679","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O divertículo epifrênico é uma afecção rara que compromete o :","options":{"A":"Esôfago","B":"Cólon direito","C":"Cólon esquerdo","D":"Ílio terminal","E":"Jejuno"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-9995","number":"9995","sourceNumber":"9995","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Qual a patologia cirúrgica que em geral apresenta de início: vômitos não-biliosos se\niniciados após 3 semanas de vida, podendo surgir na 1ª semana de vida ou somente no 5º mês de\nvida?","options":{"A":"Estenose hipertrófica do piloro.","B":"Doença do refluxo gastro-esofágico.","C":"Hérnia de hiato.","D":"Estenose duodenal.","E":"Erros inatos do metabolismo."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-9960","number":"9960","sourceNumber":"9960","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale a alternartiva incorreta:","options":{"A":"A úlcera péptica de parede posterior tem maior potencial de perfuração.","B":"A úlcera duodenal de parede anterior apresenta maior potencial de perfuração.","C":"A causa mais comum da pancreatite aguda é de origem biliar.","D":"O abdômen agudo isquêmico tem como fator desencadeante mais frequente as arritmias\ncardíacas.","E":"A complicação precoce mais frequente pós-apendicectomia é o abscesso da parede."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-7487","number":"7487","sourceNumber":"7487","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O tabagismo está presente na carcinogênese de vários tumores. Nas sequências\nabaixo qual a que contém apenas órgão/sedes em\nque o fumo é fator determinante no\naparecimento de canceres?","options":{"A":"Colo do útero, vesícula, pâncreas, pulmão, rins e bexiga.","B":"Boca, endométrio, pulmão, mama, estômago e intestino.","C":"Boca, esôfago, pâncreas, pulmão, rins e bexiga.","D":"Colo do útero, endométrio, fígado, vesícula biliar, faringe e pulmão.","E":"Todos os acima têm relação com o tabagismo."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-10024","number":"10024","sourceNumber":"10024","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente procura o ambulatório de clínica médica com resultado de endoscopia com\ngastrite enantemática leve e Helicobacter pylori positivo. Qual é afirmação correta:","options":{"A":"Todo paciente deve ser tratado para o Helicobacter pylori, independente da lesão encontrada na\nendoscopia.","B":"Paciente com gastrite enantemática não deve ser tratado, mesmo que este solicite o tratamento\nao médico.","C":"O controle do tratamento (nova pesquisa do H. pylori) deve ser verificado em pacientes com\núlcera péptica e no linfoma MALT de baixo grau.","D":"Após o tratamento do H.pylori deve solicitar endoscopia anual para investigação de neoplasia\ngástrica.","E":"O melhor esquema para o tratamento é claritromicina, amoxicilina e ranitidina ou cimetidina por\n14 dias."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-10025","number":"10025","sourceNumber":"10025","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 30 anos relata pirose, duas vezes por semana, há dois meses e que piora\ncom alimentos gordurosos e cafeinados. Correlacione à afirmação correta.","options":{"A":"O diagnóstico da patologia acima deve ser firmado com endoscopia digestiva.","B":"A Phmetria é o melhor exame para este paciente.","C":"Iniciar o tratamento clínico com inibidor de bomba de prótons por quatro semanas.","D":"Deve avaliar o tratamento cirúrgico com fundoplicatura para diminuir as chances de\ncomplicações.","E":"Solicitar a Endoscopia para avaliar a presença de hérnia de hiato que é principal causa da\ndoença do refluxo gastro-esofágica."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-354415","number":"354415","sourceNumber":"354415","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Mulher, 65 anos de idade, procura o ambulatório de cirurgia geral com queixa de azia e\nempachamento há cinco meses, com piora nas últimas semanas e perda ponderal. Refere dor em\nepigástrio após a alimentação. Nega náusea, vômitos ou hematêmese. Ao exame físico, bom\nestado geral, descorada +1/+4, FC: 68bpm, PA: 124x72mmHg; abdome plano, flácido, com dor à\npalpação profunda de epigástrio e com descompressão brusca negativa; toque retal sem\nalterações. A paciente foi submetida à endoscopia digestiva alta (imagem da endoscopia). Diante\ndesse caso clínico, indique a principal suspeita diagnóstica para a paciente:","options":{"A":"Úlcera péptica.","B":"Neoplasia maligna de estômago.","C":"Gastrite erosiva intensa.","D":"Tumor estromal (GIST) ulcerado."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/354415.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-354416","number":"354416","sourceNumber":"354416","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Mulher, 65 anos de idade, procura o ambulatório de cirurgia geral com queixa de azia e\nempachamento há cinco meses, com piora nas últimas semanas e perda ponderal. Refere dor em\nepigástrio após a alimentação. Nega náusea, vômitos ou hematêmese. Ao exame físico, bom\nestado geral, descorada +1/+4, FC: 68bpm, PA: 124x72mmHg; abdome plano, flácido, com dor à\npalpação profunda de epigástrio e com descompressão brusca negativa; toque retal sem\nalterações. A paciente foi submetida à endoscopia digestiva alta (imagem da endoscopia). Indique\no exame complementar que deve ser realizado em associação com a endoscopia digestiva alta:","options":{"A":"Tomografia computadorizada do abdome com contraste","B":"Ultrassonografia endoscópica.","C":"Biópsia da lesão.","D":"Pesquisa de H. Pylori"},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/354416.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-354417","number":"354417","sourceNumber":"354417","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Mulher, 65 anos de idade, procura o ambulatório de cirurgia geral com queixa de azia e\nempachamento há cinco meses, com piora nas últimas semanas e perda ponderal. Refere dor em\nepigástrio após a alimentação. Nega náusea, vômitos ou hematêmese. Ao exame físico, bom\nestado geral, descorada +1/+4, FC: 68bpm, PA: 124x72mmHg; abdome plano, flácido, com dor à\npalpação profunda de epigástrio e com descompressão brusca negativa; toque retal sem\nalterações. A paciente foi submetida à endoscopia digestiva alta (imagem da endoscopia).\n\nIdentifique a conduta mais adequada, caso a suspeita diagnóstica seja confirmada.","options":{"A":"Orientação nutricional e prescrever inibidor de bomba de próton.","B":"Prescrever inibidor de bomba de próton, amoxicilina e claritromicina.","C":"Realizar arteriografia com embolização.","D":"Realizar estadiamento com tomografia computadorizada de tórax e abdome."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/354417.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-62866","number":"62866","sourceNumber":"62866","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O estômago é diretamente irrigado pelas artérias:","options":{"A":"gástrica direita, gástrica esquerda, gastroepiploica direita e gastroepiploica esquerda.","B":"gástrica esquerda, gastroepiploica direita, gastroepiploica esquerda e gastroduodenal.","C":"hepática, gástrica esquerda e esplênica.","D":"hepática, gástrica esquerda, esplênica e mesentérica superior.","E":"gástrica direita, esplênica, hepática própria e gastroduodenal."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-49436","number":"49436","sourceNumber":"49436","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente, 36 anos de idade, sexo masculino, sem comorbidades maiores, nega etilismo\ne tabagismo, refere tosse noturna, rouquidão e\nepisódios de dor torácica tipo queimor retroesternal,\nprincipalmente após deitar-se. Tem histórico prévio de internação hospitalar recente por\npneumonia. Endoscopia digestiva alta e ecocardiograma normais. O exame padrão-ouro para\ndiagnóstico da afecção em questão é:","options":{"A":"tomografia axial computadorizada de tórax.","B":"pHmetria esofágica.","C":"manometria esofágica.","D":"faringoscopia direta.","E":"angiorressonância do tórax e da região cervical."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-35004","number":"35004","sourceNumber":"35004","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A artéria gastroduodenal é, comumente, ramo direto da artéria:","options":{"A":"pancreatoduodenal anterossuperior.","B":"hepática.","C":"esplênica.","D":"gástrica esquerda.","E":"aorta."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-34999","number":"34999","sourceNumber":"34999","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre o GIST, é correto afirmar:","options":{"A":"A expressão da proteína S100 é uma alteração clássica.","B":"Dentre os tumores mesenquimais do trato gastrointestinal, ocupa o segundo lugar em\nfrequência.","C":"Sua alteração molecular clássica é a expressão do CD117.","D":"Deriva-se das células musculares lisas da parede intestinal.","E":"É uma neoplasia típica de crianças e adultos jovens."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-27506","number":"27506","sourceNumber":"27506","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente, sexo feminino, 61 anos de idade, com história de epigastralgia e perda\nponderal de 7 kg há 3 meses, tratada desde\nentão com inibidor de bomba de prótons, sem\nsucesso. Submetida à endoscopia digestiva alta, que evidenciou lesão ulceroinfiltrativa em corpo\ngástrico distal, na grande curvatura, distando nove centímetros da junção esofagogástrica e cuja\nbiópsia endoscópica revelou se tratar de adenocarcinoma grau II de Broders. O caso exposto\nconduz a provável diagnóstico de:","options":{"A":"neoplasia maligna originada no tecido estromal gástrico.","B":"lesão Bormann III.","C":"lesão de alto grau histológico.","D":"tipo difuso de Lauren.","E":"câncer gástrico precoce."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-27508","number":"27508","sourceNumber":"27508","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente, sexo feminino, 61 anos de idade, com história de epigastralgia e perda\nponderal de 7kg há 3 meses, tratada desde\nentão com inibidor de bomba de prótons, sem sucesso.\nSubmetida à endoscopia digestiva alta, que evidenciou lesão ulceroinfiltrativa em corpo gástrico\ndistal, na grande curvatura, distando nove centímetros da junção esofagogástrica e cuja biópsia\nendoscópica revelou se tratar de adenocarcinoma grau II de Broders. Exames de estadiamento\nsuficientes são:","options":{"A":"radiografia torácica, ultrassonografia abdominal e cintilografia óssea.","B":"radiografia torácica, ultrassonografia abdominal e antígeno CA 19-9.","C":"radiografia torácica e ultrassonografia abdominal.","D":"tomografia computadorizada de tórax, abdome e pescoço.","E":"tomografia computadorizada do tórax e abdome e broncoscopia."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-27510","number":"27510","sourceNumber":"27510","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente, sexo feminino, 61 anos de idade, com história de epigastralgia e perda\nponderal de 7kg há 3 meses, tratada desde\nentão com inibidor de bomba de prótons, sem sucesso.\nSubmetida à endoscopia digestiva alta, que evidenciou lesão úlcero-infiltrativa em corpo gástrico\ndistal, na grande curvatura, distando nove centímetros da junção esôfaqo-gástrica e cuja biópsia\nendoscópica revelou se tratar de adenocarcinoma grau II de Broders. O paciente foi levado à\nlaparotomia exploradora, não se evidenciando implantes peritoneais, invasão a órgãos vizinhos\nadjacentes ou metástases hepáticas. Observou-se um Iinfonodo aumentado na grande curvatura\ngástrica, cujo exame de congelação revelou matástase de adenocarcinoma. O lavado peritoneal foi\nnegativo para malignidade (amostra processada no intraoperatório) e amostragem linfonodal do\nnível 16, também negativo por exame intraoperatório de congelação. A conduta cirúrgica mais\ncorreta, conforme as diretrizes brasileiras, é realizar gastrectomia:","options":{"A":"total com linfadenectomia à D2.","B":"total com linfadenectomia à D3.","C":"subtotal 4/5 com linfadenectomia à D3, se margens negativas à congelação.","D":"subtotal 4/5 com linfadenectomia à D2, se margens negativas à congelação.","E":"total com linfadenectomia à D4."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-27512","number":"27512","sourceNumber":"27512","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente, sexo feminino, 61 anos de idade, com história de epigastralgia e perda\nponderal de 7kg há 3 meses, tratada desde\nentão com inibidor de bomba de prótons, sem sucesso.\nSubmetida à endoscopia digestiva alta, que evidenciou lesão úlcero-infiltrativa em corpo gástrico\ndistal, na grande curvatura, distando nove centímetros da junção esôfaqo-gástrica e cuja biópsia\nendoscópica revelou se tratar de adenocarcinoma grau II de Broders. Caso o linfonodo do nível 16\napresentasse positividade para adenocarcinoma no exame de congelação, a conduta a ser adotada\nseria realizar:","options":{"A":"gastrectomia subtotal com linfadenectomia à D1.","B":"gastrectomia subtotal com linfadenectomia à D2.","C":"gastrectomia total com linfadenectomia à D2.","D":"gastrectomia total com linfadenectomia à D3.","E":"gastroenteroanastomose."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-27514","number":"27514","sourceNumber":"27514","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente, sexo feminino, 61 anos de idade, com história de epigastralgia e perda\nponderal de 7 kg há 3 meses, tratada desde\nentão com inibidor de bomba de prótons, sem\nsucesso. Submetida à endoscopia digestiva alta, que evidenciou lesão ulceroinfiltrativa em corpo\ngástrico distal, na grande curvatura, distando nove centímetros da junção esofagogástrica e cuja\nbiópsia endoscópica revelou se tratar de adenocarcinoma grau II de Broders. O exame\nanatomopatológico evidenciou adenocarcinoma gástrico grau III de Broders, invadindo a serosa\ngástrica e com 3 linfonodos positivos para adenocarcinoma (1 na pequena curvatura, 1 do hilo\nhepático e 1 paracadíaco direito). De acordo com a classificação TNM, trata-se de:","options":{"A":"T2N1M0.","B":"T3N1M0.","C":"T4N2M0.","D":"T2N2M0.","E":"T3N2M0."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-11135","number":"11135","sourceNumber":"11135","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Mulher, 25 anos de idade, residente em zona urbana, vem se queixando de dor\nepigástrica e pirose, que ocorreram em dois\nepisódios de moderada intensidade, durando 1 hora e\nmeia, nos últimos quinze dias. Nega episódios similares antes, bem como vômitos, febre, perda\nponderal ou alteração do ritmo intestinal. Menstruações regulares. Ao exame físico, apresenta bom\nestado geral, IMC igual a 23, mucosas coradas e anictéricas. Sem achado cardiorrespiratório.\n\nAbdome com fígado palpável sob RCD e a 4 cm do Ax, hepatimetria de 12 cm. Baço impalpável. A\nmelhor abordagem nesse caso é:","options":{"A":"realizar ultrassonografia de abdome superior.","B":"fazer teste terapêutico com inibidor de bomba de próton.","C":"medicar com sintomáticos e observar, marcar retorno com 15 dias.","D":"realizar endoscopia digestiva alta.","E":"dosar enzimas hepáticas canaliculares e aminotransferases."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-332615","number":"332615","sourceNumber":"332615","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Isabela, 29 anos, e Carlos, 32 anos, vêm a consulta de puericultura com sua filha\nAmanda, de 2 meses e 15 dias. É sua\nprimeira filha e a gestação foi planejada. Gravidez e parto\nocorreram sem intercorrências. Amanda está em amamentação exclusiva. Entretanto, na última\nconsulta há duas semanas, estava com ganho de peso insuficiente, regurgitação e vômitos. Os pais\nforam tranquilizados quanto a evolução e caráter autolimitado na maioria das crianças e orientados\na diminuir o tempo de oferta, mas aumentar a frequência da amamentação, evitar a manipulação\nexcessiva da filha e ambientes agitados durante e após a alimentação e deixá-la em pé para arrotar\ndepois de comer. Os pais relataram que estavam seguindo as orientações, mas Amanda persistia\ncom vômitos e passou a ficar mais irritada e chorosa. A avaliação da pega e sucção estava\nadequada. O ganho de peso continuou insuficiente e o restante do exame físico estava normal,\nsem febre. Assinale a alternativa que apresenta a conduta para esse caso:","options":{"A":"Deve-se iniciar tratamento empírico com ranitidina ou omeprazol e agendar retorno em 15 dias\npara reavaliação.","B":"Pode-se encaminhar para especialista para descartar doença do refluxo gastroesofágico por\nmeio de exame de pHmetria e/ou endoscopia digestiva alta.","C":"Entre possíveis exames complementares, pode-se solicitar radiografia de esôfago, estômago e\nduodeno com bário para diagnóstico de doença\ndo refluxo gastroesofágico.","D":"Realizar tratamento empírico para infecção urinária, já que é a causa infecciosa mais comum","E":"Solicitar internamento imediato da menor pelo alto risco de desnutrição."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-283846","number":"283846","sourceNumber":"283846","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O tipo histológico de neoplasia maligna do estômago mais frequente no Brasil é:","options":{"A":"Linfoma.","B":"Sarcoma.","C":"Adenocarcinoma.","D":"Carcinoma escamocelular.","E":"Tumor estromal (GIST maligno)."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-281873","number":"281873","sourceNumber":"281873","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Pela classificação de Forrest, um paciente com hemorragia digestiva, que apresente um\ncoágulo recente, sem sangramento ativo, sem visualização do coto vascular é classificado em:","options":{"A":"Forrest IB","B":"Forrest IIA","C":"Forrest IIB","D":"Forrest III"},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-249717","number":"249717","sourceNumber":"249717","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre as neoplasias gástricas, é correto afirmar que","options":{"A":"o adenocarcinoma corresponde a 50% dos tumores malignos do estômago.","B":"os tumores gástricos no antro devem ser sistematicamente tratados com gastrectomia total.","C":"o subtipo intestinal, na classificação de Lauren, tem disseminação predominantemente linfática.","D":"a esplenectomia associada à gastrectomia não está associada ao aumento de morbimortalidade\ne deve ser feita com objetivo de aumentar a\nchance de cirurgia R0.","E":"o consumo aumentado de nitratos, a infecção pelo Helicobacter Pylori, a cirurgia gástrica prévia,\no tabagismo e o gênero masculino são fatores\nassociados ao risco aumentado de desenvolvimento\nde câncer gástrico."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-249723","number":"249723","sourceNumber":"249723","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Mulher, 58 anos, oriunda de zona rural do estado da Bahia, apresenta disfagia há 15\nanos, que teve início com alimentos\nlíquidos, evoluindo há um ano para sólidos, associada à perda\nde 8kg, além de regurgitação de alimento para cavidade oral após alimentação. Considerando esse\ncaso clínico, a principal suspeita diagnóstica é , e os exames mais adequados\npara investigação são . A alternativa que preenche, correta e\nsequencialmente, as lacunas do trecho acima é","options":{"A":"Esofagite de refluxo / endoscopia digestiva alta, pHmetria e manometria esofágica","B":"Doença do refluxo gastroesofágico / endoscopia digestiva alta e manometria esofágica","C":"Neoplasia de esófago / endoscopia digestiva alta com biopsia e tomografia computadorizada","D":"Megaesôfago Chagásico / endoscopia digestiva alta, esofagograma e manometria esofágica","E":"Megaesôfago Chagásico / tomografia computadorizada, esofagograma e endoscopia digestiva\nalta"},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-181188","number":"181188","sourceNumber":"181188","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"São alterações manométricas encontradas na Acalasia, EXCETO:","options":{"A":"Pressão do Esfíncter esofágico inferior > 26 mmHg.","B":"Relaxamento do Esfíncter esofágico inferior incompleto.","C":"Amplitude pressórica diminuída.","D":"Peristalse Hipertensa."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-157618","number":"157618","sourceNumber":"157618","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre a vascularização do estômago, indique a alternativa INCORRETA.","options":{"A":"Os ramos da A. Esplênicas são A. Gastro-omental esquerda e A. Hepática.","B":"A. Gastro-omental esquerda pode originar-se da A. Esplênica ou de seus ramos.","C":"A. Gástrica direita em geral se origina no tronco da A. Hepática própria.","D":"A. Gastro-omental direita origina-se na bifurcação da A. Gastroduodenal, que por sua vez é\nramo da A. Hepática Comum."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-157726","number":"157726","sourceNumber":"157726","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Quais são os critérios histológicos para malignidade e marcadores tumorais\nrelacionados ao GIST, RESPECTIVAMENTE?","options":{"A":"Aumento da relação núcleo citoplasma e CD54.","B":"Índice Mitótico > 2 por 10 CGA e CD34.","C":"Infiltração da mucosa pelo tumor e Proteína S100.","D":"Aumento da relação núcleo membrana e C-kit."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-157718","number":"157718","sourceNumber":"157718","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre os divertículos gastrointestinais, marque a alternativa CORRETA.","options":{"A":"O melhor exame para a confirmação diagnóstica do divertículo de Zenker é a Endoscopia\nDigestiva alta.","B":"O duodeno é o segundo sítio mais comum de divertículos no aparelho digestivo, perdendo\napenas para o esôfago.","C":"O divertículo de Meckel é um divertículo verdadeiro, e está localizado na maioria dos casos no\njejuno.","D":"Mucosa ectópica pode ser encontrada em até 60% dos casos de divertículo de Meckel, e o\ntecido ectópico mais comum é o gástrico."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-139746","number":"139746","sourceNumber":"139746","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O principal sintoma relacionado à Doença do Refluxo Gastroesofágico é a pirose ou\nqueimação retroesternal. O segundo sintoma mais prevalente é:","options":{"A":"Tosse.","B":"Disfonia.","C":"Vômitos.","D":"Regurgitação."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-139749","number":"139749","sourceNumber":"139749","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A acalasia é um distúrbio da motilidade primária do esôfago que se caracteriza por falha\nno relaxamentodo esfíncter:","options":{"A":"superior do esôfago nas deglutições e ausência de peristalse no corpo esofágico.","B":"inferior do esôfago nas deglutições e presença de peristalse no corpo esofágico.","C":"inferior do esôfago nas deglutições e ausência de peristalse no corpo esofágico.","D":"superior do esôfago nas deglutições e presença de peristalse no corpo esofágico."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-139768","number":"139768","sourceNumber":"139768","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Bento, 69 anos, tabagista e etilista crônico, apresenta disfagia progressiva. Endoscopia\ndigestiva alta: lesão infiltrante e ulcerada em 1/3 médio do esôfago. Indique a alternativa que\napresenta o diagnóstico PROVÁVEL para esse caso.","options":{"A":"Carcinoma escamoso.","B":"Adenocarcinoma.","C":"Carcinosarcoma.","D":"Tumor carcinoide."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134679","number":"134679","sourceNumber":"134679","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A acalasia é um distúrbio da motilidade primária do esôfago, que se caracteriza por\nfalha no relaxamento do esfíncter:","options":{"A":"superior do esôfago nas deglutições e ausência de peristalse no corpo esofágico.","B":"inferior do esôfago nas deglutições e presença de peristalse no corpo esofágico.","C":"inferior do esôfago nas deglutições e ausência de peristalse no corpo esofágico.","D":"superior do esôfago nas deglutições e presença de peristalse no corpo esofágico."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134704","number":"134704","sourceNumber":"134704","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Termina-se uma gastrectomia total com uma:","options":{"A":"Jejunostomia, para alimentar o paciente, protegendo a esôfago-êntero anastomose.","B":"Jejunostomia, para alimentar o paciente, utilizando a esôfago-êntero anastomose.","C":"Ileostomia, para alimentar o paciente, protegendo a esôfago-êntero anastomose.","D":"Todas as anteriores estão erradas."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134745","number":"134745","sourceNumber":"134745","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação à úlcera péptica hemorrágica, é CORRETO afirmar que:","options":{"A":"É uma das causas mais frequentes de internação hospitalar.","B":"A úlcera duodenal é responsável por 25 a 30% das hemorragias digestivas altas.","C":"A úlcera gástrica é responsável por cerca de 20% das hemorragias digestivas altas.","D":"Todas anteriores estão corretas."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134754","number":"134754","sourceNumber":"134754","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Quanto à secreção gástrica de ácido, indique a CORRETA:","options":{"A":"São três os receptores: de histamina, de acetilcolina e gastrina.","B":"Na mucosa gástrica, existe metaplasia para a proteção do ácido.","C":"O HCl é produzido pelas células que irão formar a barreira mucosa.","D":"O bicarbonato é produzido pelas células parietais."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134767","number":"134767","sourceNumber":"134767","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Dentre as alternativas abaixo, apenas uma NÃO é causadora de hipotensão do\nesfíncter esofágico inferior, aponte-a.","options":{"A":"Nicotina.","B":"Gorduras.","C":"Proteínas.","D":"Chocolate."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134770","number":"134770","sourceNumber":"134770","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Qual é a maneira CORRETA da utilização do balão de Sangstaken Blakemore?","options":{"A":"200 ml no Estômago e 40 mmHg no Esôfago.","B":"400 ml no Estômago e 40 mmHg no Esôfago.","C":"150 ml no Estômago e 30 mmHg no Esôfago.","D":"200 ml no Estômago e 20 mmHg no Esôfago."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134786","number":"134786","sourceNumber":"134786","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O principal sintoma relacionado à Doença do Refluxo Gastroesofágico é a pirose ou\nqueimação retroesternal. O segundo sintoma MAIS prevalente é:","options":{"A":"Tosse.","B":"Disfonia.","C":"Vômitos.","D":"Regurgitação."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-111839","number":"111839","sourceNumber":"111839","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Divertículos são formações saculares em fundo cego que podem estar localizados em\nvárias partes do corpo humano. Os divertículos de Zenker localizam-se no:","options":{"A":"esôfago superior.","B":"intestino grosso.","C":"intestino delgado.","D":"esôfago inferior."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-111913","number":"111913","sourceNumber":"111913","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem de 48 anos com dor epigástrica e subesternal em queimação crônica (há 4\nmeses). Relata que os sintomas pioram ao\ndeitar-se e após refeições. Nega dificuldade para engolir\nou perda de peso. Usou inibidor da bomba de prótons regularmente nas últimas 6 semanas com\nmelhora parcial dos sintomas. Relata ainda sibilância e rouquidão pela manhã. O resto da história e\nexame clínico é normal. Em se tratando de refluxo gastroesofágico dos mecanismos a seguir,\nsempre contribuem para esse processo patológico, EXCETO:","options":{"A":"anormalidades do esfíncter esofágico inferior.","B":"esvaziamento prejudicado do esôfago.","C":"barreiras esofágicas anormais à exposição ao ácido.","D":"hérnia hiatal."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-111828","number":"111828","sourceNumber":"111828","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A Acalasia é um distúrbio da motilidade primária do esôfago que se caracteriza por\nfalha no relaxamento do esfíncter:","options":{"A":"superior do esôfago nas deglutições e ausência de peristalse no corpo esofágico.","B":"inferior do esôfago nas deglutições e presença de peristalse no corpo esofágico.","C":"inferior do esôfago nas deglutições e ausência de peristalse no corpo esofágico.","D":"superior do esôfago nas deglutições e presença de peristalse no corpo esofágico."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-350870","number":"350870","sourceNumber":"350870","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Mulher de 27 anos comparece ao consultório do cirurgião com queixa de dificuldade de\ndeglutição intensa. Refere não conseguir ingerir sólidos há cerca de 1 semana. Desde então, vinha\nem dieta pastosa, porém refere ainda sensação de entalo e dor retroesternal. Paciente refere\nardência retroesternal desde a adolescência que piorava após tomar refrigerantes e comidas\ncondimentadas. A paciente realizou endoscopia com biopsia que foi compatível com estenose\npéptica esofágica. Qual deve ser a conduta para essa paciente, nesse momento?","options":{"A":"Cirurgia de Nissen antirrefluxo videolaparoscópica.","B":"Inibidores de bomba de prótons e sonda nasoenteral.","C":"Dilatação endoscópica e inibidores de bomba de prótons.","D":"Passagem de \"stent\" endoscópico e investigação com tomografia."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-350869","number":"350869","sourceNumber":"350869","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 53 anos realizou uma endoscopia que identificou uma lesão gástrica,\nelevada de 2 cm, na grande curvatura,\nregião do corpo alto. A biopsia foi compatível com\nadenocarcinoma bem diferenciado. A tomografia de tórax e abdome com contraste não mostrou\nlíquido livre, blocos linfonodais suspeitos ou nódulos hepáticos. Suspeitando de um câncer gástrico\nprecoce, qual dos seguintes métodos deve contribuir mais para o planejamento do tratamento\ndesse paciente?","options":{"A":"Ultrassonografia endoscópica.","B":"Biopsia excisional endoscópica com alça.","C":"Anatomopatológico da gastrectomia parcial.","D":"Tomografia por emissão de pósitrons de corpo inteiro."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-321281","number":"321281","sourceNumber":"321281","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Mulher de 55 anos, IMC 27, é submetida a cirurgia para correção de hérnia hiatal\nassociada a doença antirrefluxo. A indicação\nda cirurgia foi sintomas recorrentes após suspensão\nda terapia clínica por diversas tentativas ao longo de 4 anos. Os exames pré-operatórios\ndemonstravam: endoscopia com esofagite grau B de Los Angeles, pHmetria refluxo ácido anormal\ncom indice DeMeester elevado e manometria com esficter esofageano com baixa pressão, sem\nalterações de motilidade do corpo esofágico. A cirurgia realizada há 10 dias foi uma válvula\nantirreflexo do tipo Nissen, por videolaparoscopia. Atualmente, a paciente queixa-se de dificuldade\npara deglutir dieta espessa e sólidos. Tolera dieta líquida e semipastosa. A paciente está bastante\nangustiada pois não consegue progredir a dieta devido a disfagia e sensação de \"bolus\"\nretroesternal durante essas refeições. Qual deve ser a conduta para essa paciente nesse\nmomento?","options":{"A":"Regredir à dieta para líquida, aguardar nova tentativa de evolução da dieta, após alguns dias.","B":"Realizar uma revisão cirúrgica por videolaparoscopia e retirar pontos do fechamento dos pilares.","C":"Indicar dilatação pneumática endoscópica para alívio da tonicidade do esfíncter esofágico\ninferior.","D":"Solicitar um manometria para estudo da causa da disfagia, motilidade esofágica e competência\nvalvar."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-321282","number":"321282","sourceNumber":"321282","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A incidência de adenocarcinoma esofágico vem aumentando nas últimas 4 décadas em\nvários países, como Estados Unidos. Qual a principal explicação para esse fato?","options":{"A":"Aumento da incidência de obesidade.","B":"Aumento no consumo de cigarro e álcool.","C":"Aumento da qualidade de notificação dos casos.","D":"Aumento do consumo de café e bebidas quentes."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-321296","number":"321296","sourceNumber":"321296","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No ambulatório de cirurgia oncológica, uma paciente de 54 anos com história de perda\nde peso recente, traz uma endoscopia com\nachados de lesão gástrica de 1 cm ulcerada. O exame\nhistopatológico da biópsia endoscópica é compatível com adenocarcinoma moderadamente\ndiferenciado. Qual exame complementar para estadiamento é mais acurado para detectar\nprogressão locorregional da neoplasia?","options":{"A":"Tomografia por emissão de prótons (PET - CT).","B":"Tomografia abdominal com contraste.","C":"Laparoscopia diagnóstica.","D":"US endoscópico."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-292792","number":"292792","sourceNumber":"292792","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Após tratamento neoadjuvante, uma paciente de 54 anos, com diagnóstico de\nadenocarcinoma tipo intestinal de 2 cm no antro gástrico, realiza tomografia que demonstra\nadenopatias em tronco celíaco, ausência de metástases hepáticas ou ascite. Atualmente,\napresenta-se com bom estado geral e sem outras comorbidades. Para essa paciente, qual o\npróximo passo para o seu tratamento?","options":{"A":"Gastrectomia parcial com linfadenectomia D1 e reconstrução a BII.","B":"Gastrectomia parcial com linfadenectomia D2 e reconstrução a BII.","C":"Gastrectomia total com linfadenectomia D2 e reconstrução em Y de Roux.","D":"Gastrectomia subtotal com linfadenectomia D2 e reconstrução em Y de Roux."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-292807","number":"292807","sourceNumber":"292807","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Na investigação de um paciente com queixa de disfagia, qual exame serve para\norientar condutas clínicas e cirúrgicas, demonstrando pontos de estenose, estase, aspecto da\nmucosa e coleta de fragmentos? Qual dos exames atende a essa necessidade?","options":{"A":"Manometria de alta resolução.","B":"Endoscopia digestiva alta.","C":"Cintilografia esofágica.","D":"Esofagograma digital."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-234014","number":"234014","sourceNumber":"234014","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 38 anos medindo 1,70m e pesando 72 kg, estava em\nacompanhamento cli?nico em unidade ba?sica de\nsau?de e foi referido a um servic?o de cirurgia. O\npaciente relatou que ha? dois anos tem quadro de pirose retroesternal, mesmo em ortostase, com\npiora apo?s as refeic?o?es, associado a? disfonia intermitente, tosse seca e pigarro dia?rio. Ao\nexame fi?sico, apresentava somente leve desconforto a? palpac?a?o profunda no epigastro.\n\nRelatava etilismo social e negava tabagismo. Ao longo desse peri?odo, fez uso de pantoprazol 40\nmg e a endoscopia digestiva alta\ncompati?vel com esofagite grau III de Savary-Miller. Foi solicitada,\nna atenc?a?o especializada, manometria esofa?gica que evidenciou hipotonia acentuada do\nesfi?ncter esofageano inferior e dismotilidade moderada do corpo esofa?gico. A pHmetria\nesofa?gica evidenciou registro na sonda proximal de 10 episo?dios de pH inferior a 4. Qual a\nconduta a ser proposta ao paciente?","options":{"A":"Sugerir a indicac?a?o de tratamento ciru?rgico por meio de fundoplicatura\nvi?deo-laparosco?pica.","B":"Dobrar a dose do pantoprazol, associar medicac?a?o pro?-cine?tica em dose plena e reforc?ar\norientac?o?es diete?ticas-comportamentais.","C":"Manter o tratamento cli?nico, associar medicac?a?o pro?-cine?tica em dose plena e reforc?ar\norientac?o?es diete?ticas-comportamentais.","D":"Manter o tratamento cli?nico, reforc?ar orientac?o?es diete?ticas-comportamentais e associar\ntratamento endosco?pico da dismotilidade."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-199687","number":"199687","sourceNumber":"199687","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 53 anos, portador de neoplasia gástrica distal, foi submetido a uma\ngastrectomia subtotal com reconstrução em y de Roux. Na descrição cirúrgica foi descrito que\n\n?toda a doença macroscópica foi removida e que houve intenção curativa?. Na consulta de retorno,\no anatomopatológico trouxe as seguintes informações:\nproduto de gastrectomia parcial, com tumor\nem antro distal infiltrando até a camada muscular do órgão, margem distal com comprometimento\nmicroscópico e presença de neoplasia metastática em 1 linfonodo entre 20 dissecados. A citologia\ndo líquido peritoneal foi positiva para células neoplásicas. Com base nas informações descritas\npode-se afirmar:","options":{"A":"A amostra linfonodal foi suficiente para o estadiamento.","B":"A ressecção realizada pode ser classificada como D1.","C":"Trata-se de um tumor T4 pela classificação TNM.","D":"Deve-se classificar a ressecção como R0."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-173009","number":"173009","sourceNumber":"173009","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 41 anos tem queixas de rouquidão crônica e queimação retroesternal\nhá 8 anos. Faz uso de bloqueador de bombas de\nprótons há pelo menos 4 anos, continuamente.\nHábitos tabagistas desde 20 anos, meio maço de cigarro nos finais de semana. Apresenta IMC de\n\n26. Refere vida agitada sem horários organizados ou refeições equilibradas. A última endoscopia\ndemonstra esofagite grau A de Los Angeles com área sugestiva de Barret curto. Qual dos\ntratamentos propostos apresenta maior chance de controlar a doença do refluxo desse paciente e\nsuas consequentes complicações?","options":{"A":"Cirurgia antirrefluxo pela técnica de Nissen.","B":"Organização do estilo de vida e mudanças de hábitos alimentares.","C":"Suspensão do uso do cigarro e acompanhamento para perda de peso.","D":"Uso de dose dobrada do bloqueador de bomba de próton e associação de procinéticos."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-172948","number":"172948","sourceNumber":"172948","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O câncer gástrico precoce (T1) apresenta elevadas taxas de cura e pode ser tratado\natravés de ressecção endoscópica. Porém,\npara tal tratamento ser seguro, é necessária a seleção\nde casos que não apresentam infiltração neoplásica na camada submucosa do órgão. Qual o\nmelhor método de estadiamento para realizar essa avaliação específica?","options":{"A":"Ecoendoscopia.","B":"Videolaparoscopia.","C":"Tomografia computadorizada.","D":"Ressonância nuclear magnética."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-172980","number":"172980","sourceNumber":"172980","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 18 anos, feminina, é atendida no ambulatório por queixa de epigastralgia.\nRefere que a dor é \"em ardência\", em\nepigástrio, sem irradiações, sem piora com movimentação,\nporém, melhora com ingesta alimentar (aumento de peso de 3kg no período dos sintomas). Relata\nque o quadro se iniciou há 3 meses, sendo observado com frequência diária. Nega sangramentos\nou melena. Exame físico normal. Não há histórico familiar patológico relevante e a paciente era\npreviamente saudável. Não havia histórico de uso de medicações. Exames laboratoriais\n(hemograma, proteína C reativa, creatinina e tireotropina) estavam normais. Qual a conduta mais\napropriada nesse momento?","options":{"A":"Indicar realização de endoscopia digestiva alta.","B":"Pesquisar antígeno fecal para Helicobacter pylori.","C":"Realizar tratamento para Helicobacter pylori.","D":"Prescrever bloqueador de bomba de prótons."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-150840","number":"150840","sourceNumber":"150840","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem de 24 anos procurou atendimento médico com queixa de há 01 ano ter iniciado\nquadro de pirose retroesternal, associado à regurgitação de alimentos digeridos. Recentemente,\napresenta certa disfagia a alimentos sólidos. Faz uso de inibidores de bomba de prótons, os quais\nmelhoram a pirose, mas após a interrupção dos mesmos há recorrência dos sintomas em poucos\ndias. Exames: endoscopia digestiva alta ? esofagite de refluxo com ulcerações convergentes (grau\n3 de Savary-Miller), gastrite enantematosa leve e uma hérnia de hiato por deslizamento de 3 cm;\nmanometria esofágica ? hipocontratilidade do esfíncter esofagiano inferior e aumento da duração\ndas ondas em esôfago distal; pHmetria esofágica ? refluxo gastroesofágico patológico em decúbito\ndorsal e em ortostase. Hábitos: tabagista há 6 anos, de 1 maço de cigarros/dia. IMC: 28 kg/m². Para\no tratamento das queixas atuais desse paciente, qual a melhor conduta?","options":{"A":"Indicar cirurgia com realização de válvula antirrefluxo de 360 graus.","B":"Substituir por bloqueadores H2, dose alta, e promover a perda de peso.","C":"Dobrar a dose do inibidor de bomba de prótons e associar agentes procinéticos.","D":"Promover modificações dietéticas e nos hábitos de vida (cessar o tabagismo, fracionar dieta\netc.)."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-126964","number":"126964","sourceNumber":"126964","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem, de 42 anos, entrou no consultório com queixa de disfagia, que se iniciou há 1\nano. Evoluiu com piora passando a comer vagarosamente e ingerindo grandes volumes de água.\nRelata uma sensação de obstrução ao nível do xifoide, após a ingesta de líquidos, especialmente\nos gelados. Há 3 meses, vem apresentando piora dos sintomas passando a melhorar somente\nquando apresenta algum grau de regurgitação. Perdeu neste último período 10 Kg, dos 80 Kg\nhabituais. Ao exame físico, encontra-se pouco distrófico, levemente hipocorado, com ausculta\npulmonar sem ruídos adventícios e abdome discretamente escavado, indolor, sem massas ou\nvisceromegalias palpáveis. Qual exame esclareceria melhor a natureza dessa obstrução?","options":{"A":"Esofagograma.","B":"Manometria esofágica.","C":"Endoscopia digestiva alta.","D":"Tomografia com contraste."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-126983","number":"126983","sourceNumber":"126983","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente, 63 anos, masculino, tabagista importante há 40 anos, procurou o ambulatório\ncom queixa de disfagia progressiva e perda de\npeso. Há 3 meses começou a sentir dificuldade para\naceitação de dieta sólida e, atualmente, só consegue aceitar dieta líquida sem resíduo. No período\nperdeu 18 Kg (peso habitual 72 Kg). No momento encontra-se emagrecido, pálido (++/4+); abdome\nescavado, flácido e indolor; extremidades com edema de membros inferiores com cacifo positivo.\n\nApresenta ainda Hb 9,1g/dl, Ht 30%, leucócitos de 11.200 mm³ com 930 mm³ linfócitos, transferrina\nde 153 mg/dl (VR 215 a 365 mg/dl) e albumina\nsérica de 2,8g/dl. Realizou EDA que evidenciou\nlesão ulcerada e friável a 32 cm da arcada dentária superior com câmara gástrica sem alterações.\nA lesão foi biopsiada e o resultado histopatológico conclui por malignidade na amostra. TC de tórax\nsem alterações em parênquima pulmonar. TC de abdome e broncoscopia normais. Em relação ao\ncaso, a melhor conduta pré-operatória seria:","options":{"A":"Ofertar, por sonda nasoenteral, dieta de cerca de 2.000 calorias/dia.","B":"Realizar hiperalimentação endovenosa com nutrição parenteral total.","C":"Administrar por via parenteral reposição de vitamina K por 3 dias.","D":"Indicar hemotransfusão de 3 concentrados de hemáceas."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-126998","number":"126998","sourceNumber":"126998","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 40 anos realizou endoscopia digestiva alta para investigação de dispepsia\nrefratária com achado de lesão ulcerada em\npequena curvatura do corpo gástrico distando 5 cm da\njunção esôfago-gástrica. A biópsia revelou adenocarcinoma gástrico do tipo difuso pela\nclassificação de Lauren. Os exames de estadiamento demonstraram pequeno espessamento da\nparede gástrica mas sem evidências de doença linfonodal ou a distância (estadiamento cT2 cN0\ncM0). Qual o melhor tratamento para esse caso?","options":{"A":"Ressecção endoscópica.","B":"Gastrectomia parcial com linfadenectomia D2.","C":"Gastrectomia total com linfadenectomia D2.","D":"Gastrectomia proximal com linfadenectomia D1."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-126992","number":"126992","sourceNumber":"126992","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 40 anos, sexo masculino, é avaliado em consultório por queixa de pirose\nretroesternal principalmente após refeições, piorando com ingesta de alguns alimentos\ncondimentados. Refere que o quadro iniciou-se há cerca de 5 anos e coincidiu com ganho de peso\napós abandonar atividades esportivas. Não fuma e, raramente ingere bebidas alcoólicas. Nega\npatologias associadas. Exame físico evidencia somente sobrepeso. Já traz endoscopia digestiva\nalta com esofagite leve, sem outras alterações. Relata ter feito as modificações de estilo de vida\ncabíveis (corrigindo refeições e hábitos) conforme orientações médicas prévias. Está, ainda, em\nuso diário de pantoprazol 40 mg antes do café da manhã há 4 semanas, mas nega melhora do\nquadro clínico apesar de tudo. Qual conduta deve ser tomada da condução desse caso, no\nmomento?","options":{"A":"Associar antagonista do receptor H2.","B":"Mudar prescrição para 40 mg 2x/dia.","C":"Aumentar dose para 80 mg pela manhã.","D":"Trocar por outro bloqueador de bomba."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-126939","number":"126939","sourceNumber":"126939","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente feminina de 58 anos comparece à consulta de seguimento por hipertensão,\ndiabetes e hipotiroidismo. Faz uso das\nseguintes medicações: captopril 125 mg/dia,\nhidroclorotiazida 25 mg/dia, anlodipino 10 mg/dia, metformina 1500 mg/dia, levotiroxina 75 mcg/dia\ne AAS 100 mg/dia. Iniciou o uso de omeprazol 40 mg pela manhã, há cerca de 8 anos ?para\nproteger o estômago das medicações?. Nunca apresentou úlceras gástricas, sangramentos ou\nsintomas de refluxo. Não faz uso de bebida alcoólica e não utiliza outras medicações sem\nprescrição médica. Trouxe raio X com moderada cifose e colapsamento parcial anterior de algumas\nvértebras torácicas que tem aparência osteopênica. Qual conduta deve ser instituída em relação à\nterapia antissecretora?","options":{"A":"Suspender omeprazol independentemente do uso de aspirina.","B":"Reduzir a dose para 10 a 20 mg de omeprazol por conta do uso de aspirina.","C":"Fracionar a dose de omeprazol para 20 mg duas vezes ao dia por conta do uso de aspirina.","D":"Substituir omeprazol por inibidor de bomba de prótons mais potente como esomeprazol 20\nmg/dia."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-102133","number":"102133","sourceNumber":"102133","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sr. João, 65 anos, é diagnosticado com carcinoma epidermoide de esôfago médio,\natingindo a submucosa e, por essa razão, é indicada para esofagectomia. Na avaliação\n\npré-operatória, é submetido a um cateterismo coronariano que demonstra obstrução de 50% de\nartéria descendente anterior. Outros exames pré-operatórios normais. Nega outras comorbidades,\npaciente é ex- tabagista, não apresenta sintomas cardiovasculares, faz caminhada acelerada de 4\nkm cinco vezes por semana. Diante do quadro, qual deve ser a conduta em relação a esse\npaciente?","options":{"A":"Encaminhar para realização da esofagectomia.","B":"Realizar angioplastia de coronária, antes da esofagectomia.","C":"Realizar revascularização do miocárdio, antes da esofagectomia.","D":"Contraindicar esofagectomia, devido ao alto risco cardiovascular."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-102106","number":"102106","sourceNumber":"102106","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem de 60 anos, com história de disfagia progressiva de sólidos para líquidos\nassociada a perda de peso de 10 kg em três\nmeses. Alimenta-se com dificuldade, apenas com\nlíquidos, refere regurgitação ocasional e tosse. Hábitos: tabagismo 30 maços/ano. Ao exame:\nemagrecido (++/4+). TC toracoabdominal mostra estreitamento de esôfago médio de aspecto\nneoplásico com plano de clivagem com vias aéreas com passagem de contraste para o estômago,\nsem adenomegalias detectáveis, pulmões de aspecto normal e demais órgãos sem alterações.\n\nAguarda endoscopia para realizar biópsia. HPP: sem intercorrências clínicas. Qual a melhor via de\nacesso para terapia nutricional para esse\npaciente?","options":{"A":"Dieta por sonda nasogástrica/enteral.","B":"Dieta por gastrostomia.","C":"Dieta por jejunostomia.","D":"Dieta parenteral."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-102121","number":"102121","sourceNumber":"102121","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 38 anos, sexo masculino, é encaminhado ao ambulatório de cirurgia para\ninvestigação de disfagia há mais de dois anos. A endoscopia digestiva alta mostra esôfago dilatado,\no esofagograma mostra esôfago com 11 cm de diâmetro de aspecto sinuoso e a manometria\nesofágica apresenta esfíncter esofagiano inferior com pressão de 45 mmHg, falha no relaxamento\ndeste e ondas esofágicas de baixa amplitude. Qual a melhor conduta para esse caso?","options":{"A":"Dilatação pneumática do EEI.","B":"Esofagectomia laparoscópica.","C":"Esofagocardiomiotomia à Heller por vídeo.","D":"Injeções de toxina botulínica diretamente no EEI."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-102155","number":"102155","sourceNumber":"102155","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente masculino, 58 anos, apresentando dor em hipocôndrio direito, sensação de\nqueimação epigástrica e retroesternal e regurgitação recorrentes, há 60 dias. Apresenta também\ndiarreia aquosa, sem muco ou pus, intermitente, há 90 dias. Nega tabagismo e etilismo. Refere\nperda de 5 kg no período. Endoscopia digestiva evidenciou três úlceras duodenais, tratadas com\nomeprazol, com persistência dos sintomas. Com base nos achados clínicos e considerando a\nprincipal hipótese diagnóstica, qual dosagem laboratorial deve ser solicitada na investigação\ndiagnóstica?","options":{"A":"Gastrina.","B":"Calcitonina.","C":"Somatostatina.","D":"Peptídeo intestinal vasoativo."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-102171","number":"102171","sourceNumber":"102171","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Ao atender uma criança de três dias de vida, com conjuntivite por provável Clamídia, o\nmédico prescreve eritromicina oral. Após duas semanas, a criança necessita fazer uma cirurgia por\num possível efeito adverso desse antibiótico nessa faixa de idade. Assinale a alternativa que\ncontém a condição sugerida nesse caso?","options":{"A":"Estenose hipertrófica do piloro.","B":"Intussuscepção intestinal.","C":"Divertículo de Meckel.","D":"Má rotação intestinal."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-81279","number":"81279","sourceNumber":"81279","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 48 anos, sexo feminino, é submetida a uma endoscopia digestiva alta para\ninvestigação de queixas digestivas inespecíficas. O exame descobre pequena lesão elevada e não\nulcerada no esôfago, distante 25 cm da arcada dentária superior. O resultado do exame\nhistopatológico obtido por biópsia demonstra tratar-se de um carcinoma epidermoide que atinge a\ncamada muscular própria. Qual das opções abaixo apresenta: o estadiamento quanto à extensão\ndo tumor, o exame complementar de melhor acurácia para avaliação locorregional da doença e a\nopção terapêutica mais adequada?","options":{"A":"T2, ultrassonografia endoscópica e esofagectomia.","B":"T1, RM (Ressonância Magnética) e ressecção endoscópica.","C":"T2, TC (Tomografia Computadorizada) e radio/quimioterapia.","D":"T1, PET-TC (Tomografia por Emissão de Pósitrons) e esofagectomia."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-81228","number":"81228","sourceNumber":"81228","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 38 anos, sexo masculino, procura assistência médica com queixas de\nempachamento pós-prandial, motivo pelo qual é solicitada uma endoscopia digestiva alta, onde se\nobserva um abaulamento de aspecto tumoral, sem comprometimento da mucosa, de\naproximadamente 6 cm, na grande curvatura, transição corpo-antro. À ecoendoscopia, a lesão é\nbem delimitada na parede gástrica, sem comprometer serosa e mucosa, sugerindo tratar-se de\nTumor de Células Estromais (GIST). Qual das opções abaixo apresenta o tratamento mais\nadequado para esse caso e qual o critério diagnóstico mais específico para que o tumor seja\nrealmente um GIST?","options":{"A":"Gastrectomia subtotal e expressão imuno-histoquímica do oncogene HER2.","B":"Gastrectomia subtotal e expressão imuno-histoquímica do oncogene CD117.","C":"Gastrectomia em cunha e expressão imuno-histoquímica do oncogene c-KIT.","D":"Gastrectomia em cunha e expressão imuno-histoquímica do oncogene PDGFR- alpha."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-65759","number":"65759","sourceNumber":"65759","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 55 anos, masculino, obeso, refere dor em queimação retroesternal após a\nalimentação, desde os 30 anos de idade. Fez endoscopia digestiva alta, que mostrou área de\nmucosa cor salmão nos 4 cm distais do esôfago. A histologia dos 2 cm proximais desta área\ndescreveu metaplasia intestinal, com área de displasia de baixo grau. Qual a melhor recomendação\nde conduta para este paciente?","options":{"A":"Nova endoscopia com biópsia em 6 meses.","B":"Nova endoscopia com biópsia imediatamente.","C":"Ressecção endoscópica da mucosa lesada.","D":"Terapia fotodinâmica endoscópica.","E":"Esofagectomia distal."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-51210","number":"51210","sourceNumber":"51210","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Os linfomas representam 1% a 4% das neoplasias gastrointestinais, sendo o aparelho\ndigestivo o local mais comum de ocorrência extranodal. No que diz respeito ao acometimento do\naparelho digestivo, qual o órgão mais comumente afetado?","options":{"A":"Cólon.","B":"Esôfago.","C":"Estômago.","D":"Intestino delgado."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-51215","number":"51215","sourceNumber":"51215","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação à extensão do tumor primário (T) na classificação TNM para o carcinoma\ngástrico, qual das alternativas abaixo corresponde ao T3?","options":{"A":"Tumor invade serosa.","B":"Tumor invade subserosa.","C":"Tumor invade a muscular própria.","D":"Tumor invade estruturas adjacentes."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-36950","number":"36950","sourceNumber":"36950","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem de 54 anos é atendido na emergência com queixa de dor de início súbito em\nabdome superior, seguido de dor em todo o\nabdome há 5 horas. Apresenta-se sudoreico e agitado.\nNo exame, o abdome é tenso e doloroso, a PA é de 160 X 90 mmHg e pulso de 115 bpm. Durante\na laparotomia, o cirurgião detecta uma úlcera gástrica perfurada tipo I. Qual o procedimento mais\nindicado nesse caso?","options":{"A":"Gastrectomia subtotal sem vagotomia.","B":"Gastrectomia parcial com reconstrução a BII.","C":"Antrectomia com reconstrução a BI.","D":"Rafia da úlcera com proteção de omento."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-36960","number":"36960","sourceNumber":"36960","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Mulher de 43 anos é tratada por ter úlceras há 1 ano. Já apresentou úlceras esofágicas,\ngástricas, duodenais e, atualmente, apresenta\nmúltiplas úlceras de 1 a 1,5 cm no estômago, 1ª e 2ª\nporção do duodeno. Qual a principal suspeita diagnóstica?","options":{"A":"Úlcera refratária por contaminação por Helicobacter pylori.","B":"Síndrome de Turcot com úlceras de estresse.","C":"Síndrome de Zollinger-Ellison por neoplasia\nneuroendócrina.","D":"Doença de Ménétrier gástrica."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-32535","number":"32535","sourceNumber":"32535","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 65 anos, em terceira linha de quimioterapia para tumor esofágico é\nadmitido por síndrome confusional aguda com\nrebaixamento do nível de consciência. Após\navaliação sumária, são administrados 25 g de glicose e hidratação isotônica endovenosos. Cerca\nde uma hora depois o paciente está bem acordado, porém agitado e desorientado em tempo e\nespaço. Nova avaliação evidencia ataxia importante e oftalmoplegia com nistagmo bilaterais. Qual a\nmelhor conduta neste momento?","options":{"A":"Tiamina 50 mg EV.","B":"Nova dose de glicose EV.","C":"Cianocobalamina (B12) 1000 u EV.","D":"Insulina regular 10 u EV.","E":"Flumazenil 0,5 mg EV."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-32525","number":"32525","sourceNumber":"32525","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem de 46 anos portador de câncer de estômago há dois meses. Evolui há 15 dias\ncom quadro de anasarca. Exames complementares revelam: creatinina sérica = 1,0 mg/dl,\nalbumina sérica = 2,3 g/dl, C3 e C4 em níveis normais, sumário de urina com proteínas 4+, sem\nhemácias e proteinúria de 24h = 12 g. Qual o melhor diagnóstico?","options":{"A":"Amiloidose AA.","B":"Nefropatia membranosa.","C":"Nefrite tubulointersticial.","D":"Glomeruloesclerose segmentar e focal.","E":"Glomerulonefrite membranoproliferativa tipo II."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-32534","number":"32534","sourceNumber":"32534","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre a úlcera péptica, marque a alternativa INCORRETA.","options":{"A":"Resulta do desequilíbrio entre fatores protetores e agressores da mucosa.","B":"Mais de 50 % dos portadores de úlcera gástrica e mais de 90% dos portadores de úlcera\nduodenal têm associação com infecção por H. pylori.","C":"O uso de AINE (anti-inflamatórios não esteroidais) está associado a muitos casos de úlcera\ngástrica.","D":"Cerca de 75% dos pacientes com infecção por H. pylori terão, em algum momento da vida, o\ndiagnóstico de úlcera péptica.","E":"O tratamento cirúrgico da doença ulcerosa péptica foi substituído nos últimos anos pela\nabordagem clínica e medicamentosa."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-36983","number":"36983","sourceNumber":"36983","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente em investigação de dispepsia ulcerosa comparece com resultado de\nendoscopia digestiva, alta, revelando duas pequenas úlceras no fundo gástrico. Não apresenta\noutras comorbidades. Qual o fator etiológico mais provável?","options":{"A":"H pylori.","B":"Tabagismo.","C":"Uso de anti-inflamatório.","D":"Infecção por citomegalovírus."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-37412","number":"37412","sourceNumber":"37412","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Você está trabalhando em um serviço de saúde da atenção primária e atendeu a\nCRSF, masculino, 58 anos, com queixas gástricas\nvagas e sem qualquer história de doenças\ngástricas na família. Você solicitou uma endoscopia digestiva alta. Diante do resultado, você deve\norientar o paciente. Assinale a associação mais correta.","options":{"A":"Diante do achado de um adenocarcinoma gástrico, além de encaminhá-lo ao cirurgião, deve\norientar para que os filhos façam endoscopia digestiva alta regularmente de 5 em 5 anos a partir\ndos 40 anos.","B":"Diante do achado de pólipos hiperplásicos, você deve alertá-lo para a possibilidade de\nassociação futura com carcinoma gástrico.","C":"Diante do achado de uma pequena lesão gástrica decorrente de um linfoma MALT, deve-se\nencaminhá-lo imediatamente a um cirurgião devido à chance de cura de um tumor em estágio\ninicial.","D":"O achado de uma lesão de Dieulafoy deve indicar a orientação do paciente quanto ao risco de\nperfuração gástrica.","E":"O achado de uma lesão ulcerosa isolada, com cerca de 0,6 cm no bulbo duodenal,\nprovavelmente é relacionada com o uso de\nanti-inflamatórios não esteroidais e você deve alertá-lo\npara interrupção do uso dessas medicações."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-37438","number":"37438","sourceNumber":"37438","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A prevalência de obesidade na infância e adolescência vem aumentando a nível\nmundial constituindo um problema de saúde pública\natual pelas consequências que pode acarretar,\nEXCETO:","options":{"A":"Hipertensão.","B":"Diabetes.","C":"Distúrbios do sono.","D":"Refluxo gastroesofágico.","E":"Nenhuma das alternativas anteriores."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-30899","number":"30899","sourceNumber":"30899","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A melhor indicação para esplenectomia durante uma gastrectomia é:","options":{"A":"Para evitar sangramento na ligadura dos vasos gástricos curtos.","B":"Juntamente com pancreatectomia parcial para realizar a linfadenectomia a DII.","C":"Para ressecar os gânglios da cadeia 10 nos tumores proximais.","D":"Por invasão direta do baço nos tumores localmente avançados.","E":"Para evitar metástase esplênica nos tumores T3 e T4."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-30906","number":"30906","sourceNumber":"30906","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem de 68 anos com quadro de disfagia progressiva há 3 meses, atualmente\napresenta dificuldade para deglutir líquidos e\nacessos de tosse à deglutição com expectoração\namarelada e restos alimentares. A TC abdominal mostra neoplasia de 1/3 médio de esôfago, sem\nplano de clivagem com estruturas adjacentes, derrame pleural e pneumonia de base direita. Qual o\nmelhor tratamento para este paciente?","options":{"A":"Radioterapia e quimioterapia exclusiva.","B":"Esofagectomia.","C":"Tubo gástrico retroesternal.","D":"Prótese autoexpansível.","E":"Gastrostomia."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-24318","number":"24318","sourceNumber":"24318","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação à fisiopatologia da acalasia esofágica, assinale a alternativa ERRADA:","options":{"A":"Dentre as alterações encontradas observa-se destruição do plexo nervoso intramural de\nAuerbach.","B":"Perda do caráter peristáltico, principalmente no 1/3 superior do esôfago.","C":"Alterações do núcleo dorsal do nervo vago.","D":"Ectasia do esôfago na fase tardia."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-24322","number":"24322","sourceNumber":"24322","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A classificação de Borrmann divide o carcinoma gástrico em 5 tipos. Qual das\nalternativas abaixo corresponde à lesão classificada como Borrmann tipo IV?","options":{"A":"Lesão fungiforme.","B":"Lesão ulcerada com bordos elevados.","C":"Lesão ulcerada com infiltração da parede gástrica.","D":"Linite plástica."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-24330","number":"24330","sourceNumber":"24330","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo masculino, 39 anos, dá entrada pela manhã na emergêcia do IJF com\nquadro de forte dor abdominal iniciada naquela madrugada. Além da dor, o paciente refere\nnáuseas, vômitos e sudorese. Ao exame apresenta fácies de sofrimento, normocorado, desidratado\n(++/4+), taquicárdico (120 ppm), sudorêico e levemente taquipnéico. Ausculta cardiopulmonar\nnormal e o abdome tenso, bastante doloroso à palpação, com sinais difusos de irritação peritoneal.\nOs exames de laboratório mostram uma discreta leucocitose e demais exames normais, incluindo\namilase. Rx de tórax e abdômen e ultrassonografia abdominal são normais. Qual o diagnóstico\nmais provável para esse caso?","options":{"A":"Úlcera péptica perfurada.","B":"Pancreatite aguda.","C":"Apendicite aguda.","D":"Trombose mesentérica."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-22946","number":"22946","sourceNumber":"22946","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre a relação entre H. pylori e doença ulcerosa péptica, assinale o item correto.","options":{"A":"A recorrência da doença ulcerosa péptica é frequente mesmo após a erradicação da bactéria","B":"75% das úlceras duodenais e > 90% das úlceras gástricas estão relacionadas com a infecção\npelo H. pylori","C":"O H. pylori um fraco produtor de urease, enzima conversora de ureia em bicarbonato e amônia","D":"A fisiopatologia da úlcera deve-se ao fato do H. pylori destruir as células D gástricas,\ninibindo o\nfeedback negativo da produção de gastrina","E":"As cepas virulentas do H. pylori"},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-24347","number":"24347","sourceNumber":"24347","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Mulher de 35 anos internada na enfermaria do IJF com diagnóstico de esofagite\ncaústica grave pós-ingestão de soda caústica.\nNo 4º dia de internação, evolui com dor torácica e\ndispnéia. O raio X de tórax da ocasião evidencia volumoso derrame pleural à esquerda e sinais de\npneumomediatino. A bioquímica do líquido pleural colhido por toracocentese revelou níveis de\namilase elevados. Que complicação justificaria os achados acima?","options":{"A":"Pancreatite aguda","B":"Rotura do esôfago","C":"Embolia pulmonar","D":"Abscesso do mediastino"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-22963","number":"22963","sourceNumber":"22963","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A doença do refluxo gastroesofágico (DRGE) é uma patologia relacionada ao déficit de\nfuncionamento do esfíncter esofágico inferior, tanto quando a zona alta de pressão é baixa o\nsuficiente para permitir a passagem do conteúdo gástrico quanto por um relaxamento espontâneo\nde um esfíncter normal não associado a uma onda peristáltica. Baseado nessas afirmativas,\nassinale o item correto.","options":{"A":"A apresentação de pacientes com DRGE inclui uma clínica escassa sem sinais indicativos da\ndoença, além de uma ausência de sintomas de progressão","B":"A endoscopia é um exame dispensável no diagnóstico de DRGE por não poder demonstrar\nclaramente sinais da doença","C":"O tratamento farmacológico da DRGE foi revolucionado pelos inibidores de bomba de prótons,\nque se mostraram mais efetivos nas\ncicatrizações de úlceras esofágicas ácidas que os\nbloqueadores H2","D":"Pacientes com sintomas de longa duração ou aqueles nos quais os sintomas persistem numa\nidade precoce não devem ser considerados para tratamento cirúrgico de princípio","E":"Pacientes que não possuem nenhuma resposta dos seus sintomas com o uso de inibidores de\nbomba de prótons, devem ser encaminhados, em\nseguida, para um tratamento cirúrgico"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-24363","number":"24363","sourceNumber":"24363","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em relação à lesão aguda da mucosa gástrica (LAMG) induzida por antiinflamatórios\nnão esteróides (AINES), é CORRETO afirmar:","options":{"A":"A maioria dos pacientes que apresenta hemorragia digestiva grave secundária a LAMG\napresentava sintomas dispépticos prévios ao uso de AINES.","B":"Doses menores que 100 mg de AAS são seguras, não apresentando risco para o aparecimento\nde LAMG.","C":"A Infecção por H. pylori, possivelmente, é um fator de risco para o desenvolvimento da LAMG\nsecundária a AINES.","D":"As preparações de AINES com revestimento entérico não apresentam risco para o aparecimento\nde ulcerações pépticas na LAMG."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-24302","number":"24302","sourceNumber":"24302","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Quanto à doença acidopéptica, marque a opção verdadeira:","options":{"A":"A infecção pelo Helicobacter pylori tem relação direta e bem definida com a doença do refluxo.","B":"A úlcera duodenal merece controle endoscópico seriado pelo risco de evolução para\nadenocarcinoma.","C":"O uso prolongado dos inibidores de bomba de prótons está proscrito em todas as situações pelo\nrisco de atrofia gástrica.","D":"A dispepsia não ulcerosa demanda, por vezes, erradicação do Helicobacter pylori para controle\nsintomático."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-27746","number":"27746","sourceNumber":"27746","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre as doenças que acometem o esôfago podemos afirmar que:","options":{"A":"os GIST (tumores do estroma gastrintestinais) do esôfago são mais comuns no esôfago cervical.","B":"os divertículos epifrênicos estão localizados no terço proximal do esôfago e à direita.","C":"o divertículo de Zenker é o mais comum divertículo esofágico e está relacionado com hipertonia\ncricofaríngea.","D":"as membranas esofágicas inferiores (anel de Schatzki) predispõem a esofagite e ao refluxo\ngastresofágico.","E":"as membranas esofágicas superiores (síndrome de Plummer-Vinson) se desenvolvem em\npacientes com deficiência crônica de vitamina B12."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-27712","number":"27712","sourceNumber":"27712","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre a DRGE (doença do refluxo gastresofágico) podemos afirmar:","options":{"A":"a dor retroesternal tipo compressão é típica na DRGE.","B":"o padrão-ouro para o diagnóstico da DRGE é a manometria do esôfago associada com a\nendoscopia.","C":"o tratamento de escolha da DRGE na presença de ulceração esofágica e/ou mucosa de Barrett\né o com inibidores da bomba de prótons.","D":"A mais comum complicação intra-operatória do tratamento cirúrgico da DRGE é o pneumotórax.","E":"a disfagia pós?operatória ocorre em mais de 80% dos pacientes submetidos a tratamento\ncirúrgico para DRGE."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-27786","number":"27786","sourceNumber":"27786","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um bebê de 2 meses do sexo feminino, recém-diagnosticada com estenose pilórica é\nadmitida na unidade de pediatria do hospital de sua comunidade para administração de fluidos\nintravenosos por causa de vômitos prolongados e incapacidade de manter ingestão oral adequada.\nAssinale a alternativa que mostra o melhor resultado da análise de eletrólitos séricos e gasometria\narterial deste paciente.","options":{"A":"Hipercalemia","B":"Hipernatremia","C":"Hipocloremia","D":"Acidose metabólica","E":"Acidose respiratória"},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-6930","number":"6930","sourceNumber":"6930","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem de 40 anos com queixa de pirose traz uma endoscopia que revelou esôfago de\nBarrett longo. O exame histopatológico confirma esôfago de Barrett sem displasia. A melhor\nconduta a seguir é:","options":{"A":"Observação.","B":"Inibidor de bomba de prótons.","C":"Válvula antirrefluxo.","D":"Ablação a Laser.","E":"Ressecção."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-9027","number":"9027","sourceNumber":"9027","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um dos principais exames para o diagnóstico da acalasia é a manometria esofágica.\nQual das alterações abaixo NÃO corresponde a um\ncritério manométrico comumente encontrado\nnessa situação?","options":{"A":"Aperistalse do corpo esofágico","B":"Pressão do esfíncter esofagiano inferior (EEI) normal ou < 15 mmHg","C":"Ausência ou relaxamento parcial do EEI após a deglutição","D":"Pressão intraesofágica basal maior que a intragástrica"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-9029","number":"9029","sourceNumber":"9029","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"São características do carcinoma espinocelular de esôfago, EXCETO:","options":{"A":"É o tumor mais frequente de esôfago no mundo.","B":"É encontrado, principalmente, na mucosa do terço médio do esôfago.","C":"A grande maioria dos pacientes portadores deste tipo de tumor apresenta como sintoma\nprincipal a disfagia.","D":"Esse tumor surge a partir de glândulas superficiais e profundas da mucosa esofágica."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-9031","number":"9031","sourceNumber":"9031","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação aos divertículos epifrênicos, é correto afirmar, EXCETO:","options":{"A":"São divertículos de pulsão que aparecem no terço distal do esôfago","B":"Na maioria das vezes, acomete pacientes portadores de um distúrbio de motilidade onde estão\npresentes sintomas como disfagia, regurgitação, vômitos, dor torácica, tosse e perda de peso","C":"Embora o exame contrastado defina melhor a presença de divertículos, estudos de motilidade\nsão necessários para a conclusão diagnóstica","D":"O tratamento cirúrgico, quando indicado, inclui sua ressecção e uma miotomia do esfíncter\nesofagiano superior."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-6906","number":"6906","sourceNumber":"6906","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Mulher de 55 anos em uso crônico de anti-inflamatório não esteroidal apresenta quadro\nde hemorragia digestiva alta vultosa. Após a\nestabilização hemodinâmica, realizou endoscopia que\nmostrou úlcera na 1ª porção duodenal, na parede posterior, recoberta por grande coágulo. Neste\nmomento foi tratada com injeção de adrenalina. A paciente permaneceu sob observação rigorosa,\nquando em menos de 24 horas apresentou hipotensão e enterorragia. Qual o procedimento melhor\nindicado para esta paciente?","options":{"A":"Repetir a endoscopia com esclerose.","B":"Vagotomia com piloroplastia e ulcerorrafia.","C":"Vagotomia e gastrojejunostomia.","D":"Vagotomia e gastrectomia parcial.","E":"Gastrectomia subtotal."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-6911","number":"6911","sourceNumber":"6911","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre o câncer gástrico precoce, NÃO é correto:","options":{"A":"Pode apresentar metástase.","B":"Pode invadir a camada muscular.","C":"Corresponde a 30% dos cânceres gástricos do Japão.","D":"Pode ser curado a partir da ressecção endoscópica.","E":"Pode acometer grande extensão da mucosa do órgão."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-7278","number":"7278","sourceNumber":"7278","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O esfíncter esofágico inferior (EEI) é mais precisamente referido como o mecanismo\nEEI ou a zona de alta pressão esofágica distal\n(ZAP). São fatores que diminuem o tônus da ZAP:","options":{"A":"gastrina, colecistocinina.","B":"histamina, neperidina.","C":"atropina, hérnia de hiato.","D":"metoclopromida, ethanol.","E":"nicotina, operação antirrefluxo."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-9023","number":"9023","sourceNumber":"9023","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em relação à DRGE é CORRETO afirmar:","options":{"A":"A maior parte dos portadores de DRGE apresenta erosões esofágicas ao exame endoscópico.","B":"Não há correlação entre piora dos sintomas e aparecimento do esôfago de Barrett.","C":"A prova terapêutica com IBP, por quatro semanas, deve ser utilizada em todos os pacientes com\nsintomas de DRGE.","D":"A pHmetria esofágica é indispensável para o diagnóstico da DRGE."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-8834","number":"8834","sourceNumber":"8834","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em um paciente com síndrome de obstrução pilórica, esperamos encontrar os\nseguintes distúrbios eletrolíticos e acidobásicos:","options":{"A":"Hipocalemia, hipomagnesemia e alcalose metabólica.","B":"Hipocloremia, hipocalemia e alcalose metabólica.","C":"Hiponatremia, hipocalemia e acidose metabólica.","D":"Hipocalemia, hipercloremia e alcalose metabólica.","E":"Hipocloremia, hipomagnesemia e alcalose metabólica."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-8861","number":"8861","sourceNumber":"8861","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale a opção que contém uma correlação INCORRETA de doença esofágica e seu\ntratamento:","options":{"A":"Disfagia cervical esofágica associada à deficiência de ferro - Dilatação esofágica e correção do\ndefeito nutricional.","B":"Disfagia esofágica devido a anel de Schatzki e refluxo - Dilatação esofágica e inibidor de bomba\nde prótons.","C":"Disfagia severa devido a esfíncter superior esofágico anormal - Esofagomiotomia.","D":"Acalasia esofágica discreta (tipo I ou II) - Dilatação do esfíncter inferior e/ou procinéticos.","E":"Espasmo esofágico difuso grave - Esofagectomia trans-hiatal."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-8870","number":"8870","sourceNumber":"8870","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale a opção INCORRETA sobre úlcera péptica.","options":{"A":"A formação de úlcera requer secreção de ácido, pepsina em associação de H. pylori ou ingestão\nde anti-inflamatórios.","B":"O melhor tratamento para um paciente com úlcera duodenal perfurada de poucas horas é rafia\nda úlcera com manchão de omento por laparoscopia.","C":"O melhor tratamento para um paciente com obstrução duodenal por úlcera é, se possível,\nantrectomia e vagotomia.","D":"O tratamento cirúrgico eletivo de úlcera não complicada é raro mesmo com métodos\nminimamente invasivos (vagotomias por laparoscopia).","E":"As úlceras pépticas com complicações como sangramento, perfuração e obstrução diminuíram\nmuito na era dos inibidores de bomba de\npróton."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-17830","number":"17830","sourceNumber":"17830","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação ao câncer gástrico, é correto afirmar.","options":{"A":"Nas áreas de alta incidência predominam os tumores do tipo intestinal ou bem diferenciados","B":"Os tumores do tipo intestinal têm relação genética e os do tipo difuso estão associados ao\nHelicobacter pylori","C":"A linite plástica é a disseminação submucosa do tumor e é classificada como Borrman III","D":"As úlceras gástricas são mais frequentemente neoplásicas quando localizadas na pequena\ncurvatura, sendo pépticas quando se desenvolvem na grande curvatura","E":"A classificação de Borrman é histológica, enquanto a classificação de Lauren refere-se a\nparâmetros macroscópicos do tumor."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-17839","number":"17839","sourceNumber":"17839","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre as hemorragias digestivas, é correto afirmar:","options":{"A":"A maioria é hemorragia digestiva alta","B":"A primeira abordagem é identificar o sítio do sangramento","C":"Hemorragia baixa é aquela após a válvula íleo-cecal","D":"Varizes de esôfago são as principais causas de sangramento alto","E":"Hemorroidas são a principal causa de sangramento baixo, abundante"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-349774","number":"349774","sourceNumber":"349774","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No caso de um paciente que realizou gastrectomia parcial e tem apresentado, 20\nminutos após a ingesta alimentar, sintomas\ncomo náuseas, vômitos, sensação de plenitude\ngástrica, diarreia explosiva, palpitações e taquicardia, qual é o provável diagnóstico e a\norientação\nque o médico deve fornecer para a melhora dos sintomas?","options":{"A":"Dumping tardio / Orientar a evitar hipoglicemia, ingerindo maiores quantidades de alimentos com\naçúcar em um menor intervalo de tempo.","B":"Síndrome da alça aferente / Orientar o paciente a provocar vômitos quando tiver os sintomas de\nplenitude gástrica, pois geralmente gera um alívio imediato dos sintomas.","C":"Gastrite alcalina de refluxo / Orientar o paciente a utilizar inibidor de bomba de prótons a\ncada 12\nhoras e evitar a ingestão de alimentos ácidos.","D":"Atonia gástrica / Utilizar pró-cinéticos como a metoclopramida e fazer a ingestão de várias\nrefeições com menores quantidades de alimentos.","E":"Dumping precoce / Orientar a evitar alimentos que contenham grande quantidade de açúcar,\nrealizar pequenas refeições com proteínas e\ngorduras em menor intervalo de tempo e separar os\nlíquidos dos sólidos durante as refeições."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-305278","number":"305278","sourceNumber":"305278","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente com queixa de pirose, azia e regurgitações procura orientações sobre um\npossível diagnóstico de Doença do Refluxo Gastroesofágico (DRGE) e tratamento. Assinale a\nalternativa que apresenta somente informações CORRETAS que poderão ser fornecidas a esse\npaciente.","options":{"A":"O exame padrão-ouro para o diagnóstico é a endoscopia digestiva alta. A DRGE pode ser\ncausada por hérnia hiatal do tipo I, chamada de hérnia de rolamento.","B":"O melhor exame para o diagnóstico é a manometria. A DRGE pode ser causada por hérnia hiatal\ndo tipo II, chamada de hérnia por\ndeslizamento.","C":"O melhor exame para o diagnóstico é a pHmetria de 24h. A DRGE pode ser causada por hérnia\nhiatal do tipo II, conhecida como hérnia de rolamento.","D":"O melhor exame para o diagnóstico é a esofagografia. A DRGE pode ser causada por hérnia\nhiatal do tipo II, chamada de hérnia por rolamento.","E":"O exame padrão-ouro para diagnóstico é a pHmetria de 24h. A DRGE pode ser causada por\nhérnia hiatal do tipo III, chamada de hérnia por deslizamento."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-305280","number":"305280","sourceNumber":"305280","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre o câncer gástrico, é CORRETO afirmar que:","options":{"A":"Afeta, com maior frequência, as mulheres e a faixa etária entre 40?50 anos, sendo também o\ntipo de câncer mais comum no Japão.","B":"O Helicobacter pylori pode ser considerado um dos fatores contribuintes para o câncer gástrico\npor gerar gastrite hipertrófica.","C":"O câncer gástrico difuso hereditário é uma forma herdada de carcinoma gástrico resultante da\nmutação do gene da E-caderina, com aproximadamente 80% de possibilidade de desenvolvimento\nde câncer gástrico durante a vida.","D":"Alimentos ricos em sal, como carnes defumadas, juntamente com o alto consumo de frutas\ncítricas e vegetais, são associados a um risco aumentado de câncer gástrico.","E":"Os pacientes com anemia perniciosa também têm um aumento no risco de desenvolvimento de\ncâncer gástrico. A hipercloridria é a característica definidora dessa condição."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-298874","number":"298874","sourceNumber":"298874","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 35 anos de idade vem apresentando dor abdominal e disfagia para\nsólidos de forma progressiva. Além disso,\ndemonstra perda de peso, sendo 10% do peso corporal\nem três meses. O paciente fez uso de omeprazol de 40 mg sem melhora. Também há lesões\ndolorosas e descamativas nas mãos e nos pés dele, como mostra a figura a seguir. Observaram-se\nPA = 110 mmHg x 70 mmHg, SatO2 = 98% em ar ambiente e FC = 60 bpm. Endoscopia indicou\numa larga massa na mucosa esofagena. Diante disso, o endoscopista realizou uma biópsia. Acerca\ndesse caso clínico e considerando os conhecimentos médicos correlatos, julgue o item a seguir. A\npresença de disfagia sólida sugere uma perda de, pelo menos, 70% da luz esofágica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/298874.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-298875","number":"298875","sourceNumber":"298875","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 35 anos de idade vem apresentando dor abdominal e disfagia para\nsólidos de forma progressiva. Além disso,\ndemonstra perda de peso, sendo 10% do peso corporal\nem três meses. O paciente fez uso de omeprazol de 40 mg sem melhora. Também há lesões\ndolorosas e descamativas nas mãos e nos pés dele, como mostra a figura a seguir. Observaram-se\nPA = 110 mmHg x 70 mmHg, SatO2 = 98% em ar ambiente e FC = 60 bpm. Endoscopia indicou\numa larga massa na mucosa esofageana. Diante disso, o endoscopista realizou uma biópsia.\n\nAcerca desse caso clínico e considerando os conhecimentos médicos correlatos, julgue o item a\nseguir. Possivelmente, o diagnóstico seja adenocarcinoma de esôfago.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/298875.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-298876","number":"298876","sourceNumber":"298876","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 35 anos de idade vem apresentando dor abdominal e disfagia para\nsólidos de forma progressiva. Além disso,\ndemonstra perda de peso, sendo 10% do peso corporal\nem três meses. O paciente fez uso de omeprazol de 40 mg sem melhora. Também há lesões\ndolorosas e descamativas nas mãos e nos pés dele, como mostra a figura a seguir. Observaram-se\nPA = 110 mmHg x 70 mmHg, SatO2 = 98% em ar ambiente e FC = 60 bpm. Endoscopia indicou\numa larga massa na mucosa esofagena. Diante disso, o endoscopista realizou uma biópsia. Acerca\ndesse caso clínico e considerando os conhecimentos médicos correlatos, julgue o item a seguir. O\npaciente apresenta uma condição genética chamada tilose palmoplantar.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/298876.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-298877","number":"298877","sourceNumber":"298877","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 35 anos de idade vem apresentando dor abdominal e disfagia para\nsólidos de forma progressiva. Além disso,\ndemonstra perda de peso, sendo 10% do peso corporal\nem três meses. O paciente fez uso de omeprazol de 40 mg sem melhora. Também há lesões\ndolorosas e descamativas nas mãos e nos pés dele, como mostra a figura a seguir. Observaram-se\nPA = 110 mmHg x 70 mmHg, SatO2 = 98% em ar ambiente e FC = 60 bpm. Endoscopia indicou\numa larga massa na mucosa esofagena. Diante disso, o endoscopista realizou uma biópsia. Acerca\ndesse caso clínico e considerando os conhecimentos médicos correlatos, julgue o item a seguir.\n\nTomografia de tórax apresenta acurácia maior que ultrassom endoscópico para a identificação de\ndoença localmente avançada.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/298877.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-298878","number":"298878","sourceNumber":"298878","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 35 anos de idade vem apresentando dor abdominal e disfagia para\nsólidos de forma progressiva. Além disso,\ndemonstra perda de peso, sendo 10% do peso corporal\nem três meses. O paciente fez uso de omeprazol de 40 mg sem melhora. Também há lesões\ndolorosas e descamativas nas mãos e nos pés dele, como mostra a figura a seguir. Observaram-se\nPA = 110 mmHg x 70 mmHg, SatO2 = 98% em ar ambiente e FC = 60 bpm. Endoscopia indicou\numa larga massa na mucosa esofagena. Diante disso, o endoscopista realizou uma biópsia. Acerca\ndesse caso clínico e considerando os conhecimentos médicos correlatos, julgue o item a seguir. A\npresença de uma massa grande na mucosa é altamente sugestiva de neoplasia de esôfago.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/298878.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-274347","number":"274347","sourceNumber":"274347","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale a alternativa que corresponde aos 3 locais anatômicos de estreitamento do\nesôfago.","options":{"A":"Constrição pelo músculo milo-hióideo, constrição traqueal e constrição gastroesofágica.","B":"Constrição pelo músculo cricofaríngeo, constrição broncoaórtica e constrição diafragmática.","C":"Constrição pelo músculo omo-hióideo, constrição brônquica e constrição pericárdica.","D":"Constrição pelo músculo cricofaríngeo, constrição traqueal e constrição gastroesofágica.","E":"Constrição pelo músculo tireofaríngeo, constrição broncoaórtica e constrição gastroesofágica."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-274348","number":"274348","sourceNumber":"274348","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale a alternativa que corresponde ao tipo de hérnia mais comum que gera\nsintomas de refluxo gastroesofágico.","options":{"A":"Hérnia hiatal por deslizamento.","B":"Hérnia de Spiegel.","C":"Hérnia de Zenker.","D":"Hérnia epigástrica.","E":"Hérnia hiatal paraesofágica."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-274351","number":"274351","sourceNumber":"274351","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre a hemorragia digestiva alta causada por úlcera péptica, suas características e\nabordagem, assinale a alternativa correta.","options":{"A":"A úlcera péptica representa a 4a maior causa de hemorragia digestiva alta.","B":"Deve-se aguardar 72h após o quadro inicial da hemorragia para ser realizada endoscopia\ndigestiva alta.","C":"A maioria dos casos de hemorragia por úlcera necessita de abordagem cirúrgica.","D":"Hemorragia mais intensa geralmente ocorre quando a úlcera duodenal penetra ramos da artéria\ngastroepiploica esquerda.","E":"Na suspeita ou diagnóstico de úlcera péptica, deve ser iniciada terapia com inibidor de bomba de\nprótons."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-274352","number":"274352","sourceNumber":"274352","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em relação ao câncer gástrico assinale a alternativa correta.","options":{"A":"Há uma maior prevalência geral entre as mulheres.","B":"Pacientes com anemia perniciosa têm risco aumentado de desenvolver câncer gástrico.","C":"A linite plástica é o termo usado para descrever o câncer gástrico tipo 3 de Borrmann.","D":"O sistema de Lauren classifica o câncer gástrico em tipo intestinal e anaplásico.","E":"O câncer gástrico do tipo intestinal de Lauren é mais comum em pacientes jovens."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-274363","number":"274363","sourceNumber":"274363","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 50 anos, masculino, vai à consulta devido a quadro de dispepsia, sensação\nde plenitude pós-prandial, perda ponderal de\ncerca de 10Kg nos últimos 60 dias e dor abdominal\nesporádica. O paciente tem histórico de ser tabagista e hipertenso, atualmente em uso de\nhidroclorotiazida e losartan, e faz uso irregular de inibidor de bomba devido à gastrectomia parcial\ndecorrente de úlcera gástrica há 10 anos. Após investigação, o paciente recebeu diagnóstico de\nneoplasia gástrica. Sobre esse quadro, assinale a alternativa correta.","options":{"A":"O diagnóstico mais provável, nesse caso, é linfoma gástrico.","B":"A presença de massa palpável em fundo gástrico, nódulo axilar e periumbilical é indicação para\ncirurgia de urgência.","C":"No adenocarcinoma, a consanguinidade e o tipo sanguíneo não são fatores de risco para a\ndoença.","D":"A presença de gastrite atrófica e a cirurgia de gastrectomia parcial geralmente atrasam o\nsurgimento de neoplasias gástricas.","E":"Em fases iniciais da doença, o prognóstico de cura é acima de 90%."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262216","number":"262216","sourceNumber":"262216","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação à esofagite eosinofílica, julgue o item a seguir. Um dos sintomas dessa\ndoença é a disfagia de transmissão.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262217","number":"262217","sourceNumber":"262217","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação à esofagite eosinofílica, julgue o item a seguir. É uma doença de maior\nprevalência em homens e não há evidências que a caracterizem como uma condição pré-maligna.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262219","number":"262219","sourceNumber":"262219","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação à esofagite eosinofílica, julgue o item a seguir. Corticoides sistêmicos em\nbaixas doses são o tratamento de escolha para essa condição.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262221","number":"262221","sourceNumber":"262221","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Certo paciente de 18 anos de idade procura gastroenterologista após a realização de\nendoscopia digestiva alta, sem pedido médico, em razão de queixas de queimação retroesternal e\nregurgitação, que se iniciaram há cerca de dois meses. As queixas são geralmente pós-prandiais,\nprincipalmente após ingesta de alimentos gordurosos e de bebidas alcoólicas. Nega náuseas,\nvômitos, disfagia, perda ponderal ou quaisquer outros sintomas. O laudo do exame descreve\npresença de erosões em esôfago distal, algumas maiores que 5 mm, confluentes, acometendo\ncerca de 65% da circunferência do órgão. Acerca desse caso clínico e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. O diagnóstico presuntivo de doença do\nrefluxo gastroesofágico (DRGE) pode ser feito na presença dos sintomas típicos de pirose e\nregurgitação ácida, sendo recomendada a endoscopia digestiva alta nos casos em que há sinais de\nalarme ou risco de complicações.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262223","number":"262223","sourceNumber":"262223","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Certo paciente de 18 anos de idade procura gastroenterologista após a realização de\nendoscopia digestiva alta, sem pedido médico, em razão de queixas de queimação retroesternal e\nregurgitação, que se iniciaram há cerca de dois meses. As queixas são geralmente pós-prandiais,\nprincipalmente após ingesta de alimentos gordurosos e de bebidas alcoólicas. Nega náuseas,\nvômitos, disfagia, perda ponderal ou quaisquer outros sintomas. O laudo do exame descreve\npresença de erosões em esôfago distal, algumas maiores que 5 mm, confluentes, acometendo\ncerca de 65% da circunferência do órgão. Acerca desse caso clínico e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. A pesquisa e o tratamento da bactéria H.\npylori não fazem parte da rotina propedêutica e terapêutica da DRGE.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262225","number":"262225","sourceNumber":"262225","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Certo paciente de 18 anos de idade procura gastroenterologista após a realização de\nendoscopia digestiva alta, sem pedido médico, em razão de queixas de queimação retroesternal e\nregurgitação, que se iniciaram há cerca de dois meses. As queixas são geralmente pós-prandiais,\nprincipalmente após ingesta de alimentos gordurosos e de bebidas alcoólicas. Nega náuseas,\nvômitos, disfagia, perda ponderal ou quaisquer outros sintomas. O laudo do exame descreve\npresença de erosões em esôfago distal, algumas maiores que 5 mm, confluentes, acometendo\ncerca de 65% da circunferência do órgão. Acerca desse caso clínico e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. O exame de manometria esofágica\nsempre deve ser realizado antes do tratamento cirúrgico da DRGE.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262227","number":"262227","sourceNumber":"262227","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Certo paciente de 18 anos de idade procura gastroenterologista após a realização de\nendoscopia digestiva alta, sem pedido médico, em razão de queixas de queimação retroesternal e\nregurgitação, que se iniciaram há cerca de dois meses. As queixas são geralmente pós-prandiais,\nprincipalmente após ingesta de alimentos gordurosos e de bebidas alcoólicas. Nega náuseas,\nvômitos, disfagia, perda ponderal ou quaisquer outros sintomas. O laudo do exame descreve\npresença de erosões em esôfago distal, algumas maiores que 5 mm, confluentes, acometendo\ncerca de 65% da circunferência do órgão. Acerca desse caso clínico e tendo em vista os\nconhecimentos médicos correlatos, julgue o item a seguir. Pela classificação de Los Angeles, o\npaciente apresenta uma esofagite erosiva grau C.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262228","number":"262228","sourceNumber":"262228","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Quanto ao esôfago de Barrett, uma das possíveis complicações da doença do refluxo\ngastroesofágico (DRGE), julgue o item a seguir. Acomete principalmente o esôfago proximal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262229","number":"262229","sourceNumber":"262229","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Quanto ao esôfago de Barrett, uma das possíveis complicações da doença do refluxo\ngastroesofágico (DRGE), julgue o item a seguir. Definido histologicamente como metaplasia\nintestinal, o esôfago de Barrett apresenta-se macroscopicamente como uma área de mucosa\nespessada e esbranquiçada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262230","number":"262230","sourceNumber":"262230","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Quanto ao esôfago de Barrett, uma das possíveis complicações da doença do refluxo\ngastroesofágico (DRGE), julgue o item a seguir. Pacientes com esôfago de Barrett devem fazer\nendoscopia a cada seis meses para rastreio de câncer de esôfago.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262237","number":"262237","sourceNumber":"262237","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A Rome Foundation trouxe uma grande contribuição à gastroenterologia ao padronizar\na definição de um grupo de doenças cujo\ndiagnóstico é muito comum à especialidade, que é o das\ndoenças funcionais. Acerca das doenças funcionais do trato digestivo, julgue o item a seguir. A\ndispepsia funcional pode ser apresentada como plenitude pós-prandial, ou saciedade precoce, ou\ndor epigástrica, ou queimação epigástrica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262238","number":"262238","sourceNumber":"262238","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A Rome Foundation trouxe uma grande contribuição à gastroenterologia ao padronizar\na definição de um grupo de doenças cujo\ndiagnóstico é muito comum à especialidade, que é o das\ndoenças funcionais. Acerca das doenças funcionais do trato digestivo, julgue o item a seguir. Pirose\ntambém é interpretado como um dos sintomas definidores de dispepsia funcional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262239","number":"262239","sourceNumber":"262239","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A Rome Foundation trouxe uma grande contribuição à gastroenterologia ao padronizar\na definição de um grupo de doenças cujo\ndiagnóstico é muito comum à especialidade, que é o das\ndoenças funcionais. Acerca das doenças funcionais do trato digestivo, julgue o item a seguir.\n\nSintomas que se aliviam com evacuação ou flatulência não se enquadram como dispepsia\nfuncional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-262241","number":"262241","sourceNumber":"262241","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A Rome Foundation trouxe uma grande contribuição à gastroenterologia ao padronizar\na definição de um grupo de doenças cujo\ndiagnóstico é muito comum à especialidade, que é o das\ndoenças funcionais. Acerca das doenças funcionais do trato digestivo, julgue o item a seguir.\n\nAntieméticos e antidepressivos fazem parte do arsenal terapêutico da dispepsia funcional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-239276","number":"239276","sourceNumber":"239276","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 75 anos de idade procurou atendimento por diminuição do volume\nurinário e intolerância aos esforços,\nassociada a dor torácica ventilatório-dependente e a dor lombar\nde forte intensidade. Realizou exames de laboratório, que evidenciaram: hemoglobina = 8,6 g/dl,\nhematócrito = 25%, leucócitos = 6.600/mm3, sem particularidades no diferencial, plaquetas = 190\nmil/mm3, creatinina = 4,51 mg/dl, potássio = 6,3 mEq/L, cálcio sérico corrigido = 13 mg/dl, ureia =\n109 mg/dl, reserva alcalina = 12 U/L. Ao exame físico, o paciente encontrava-se em regular estado\ngeral, hipocorado, com presença de sopro sistodiastólico 2+/4+, murmúrio vesicular reduzido em\n1/3 inferior direito, edema em membros inferiores 3+/4+, abdome sem particularidades e\n\npercussão-punho-lombar (PPL) negativo, PA = 180 mmHg X 90 mmHg, FC = 97 bpm, SatO2 = 92%\nem ar ambiente. Considerando esse caso\nclínico e os conhecimentos médicos correlatos, julgue o\nitem a seguir. Pacientes com dor crônica fazem uso frequente de anti-inflamatórios não esteroidais\n(AINES), que são associados a úlceras pépticas, de localização gástrica, mais frequentes que no\nduodeno.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-239277","number":"239277","sourceNumber":"239277","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 75 anos de idade procurou atendimento por diminuição do volume\nurinário e intolerância aos esforços,\nassociada a dor torácica ventilatório-dependente e a dor lombar\nde forte intensidade. Realizou exames de laboratório, que evidenciaram: hemoglobina = 8,6 g/dl,\nhematócrito = 25%, leucócitos = 6.600/mm3, sem particularidades no diferencial, plaquetas = 190\nmil/mm3, creatinina = 4,51 mg/dl, potássio = 6,3 mEq/L, cálcio sérico corrigido = 13 mg/dl, ureia =\n109 mg/dl, reserva alcalina = 12 U/L. Ao exame físico, o paciente encontrava-se em regular estado\ngeral, hipocorado, com presença de sopro sistodiastólico 2+/4+, murmúrio vesicular reduzido em\n1/3 inferior direito, edema em membros inferiores 3+/4+, abdome sem particularidades e\n\npercussão-punho-lombar (PPL) negativo, PA = 180 mmHg X 90 mmHg, FC = 97 bpm, SatO2 = 92%\nem ar ambiente. Considerando esse caso\nclínico e os conhecimentos médicos correlatos, julgue o\nitem a seguir. Úlceras pépticas do tipo Forrest IIC evidenciadas na endoscopia são aquelas com\nfundo hemático.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-196597","number":"196597","sourceNumber":"196597","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Determinado paciente de 60 anos de idade, tabagista e etilista de longa data, vinha\napresentando, há seis meses, disfagia progressiva e perda de peso. Foi então realizada uma\nendoscopia que demonstrou lesão ulcerada em esôfago médio. O paciente foi submetido a\nestadiamento e manifestou doença local, sem sinais de doença linfonodal em tomografia\ncomputadorizada. A biópsia demonstrou carcinoma de células escamosas de esôfago. Em relação\nao caso clínico apresentado e aos conhecimentos médicos correlatos, julgue o item a seguir. O\npaciente deve ser submetido a cirurgia com ressecção de lesão tumoral e linfonodos regionais,\nalém da reconstrução do trânsito gastrointestinal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-196599","number":"196599","sourceNumber":"196599","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Determinado paciente de 60 anos de idade, tabagista e etilista de longa data, vinha\napresentando, há seis meses, disfagia progressiva e perda de peso. Foi então realizada uma\nendoscopia que demonstrou lesão ulcerada em esôfago médio. O paciente foi submetido a\nestadiamento e manifestou doença local, sem sinais de doença linfonodal em tomografia\ncomputadorizada. A biópsia demonstrou carcinoma de células escamosas de esôfago. Em relação\nao caso clínico apresentado e aos conhecimentos médicos correlatos, julgue o item a seguir. A\nultrassonografia endoscópica pode ajudar a avaliar a invasão de parede pelo tumor.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-179186","number":"179186","sourceNumber":"179186","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 42 anos de idade, foi admitido no serviço de emergência com queixa\nde dor epigástrica, fezes escurecidas e\nfraqueza. Relata que os sintomas tiveram início nas últimas\n24 horas. Nega comorbidades prévias, mas informa uso frequente de ibuprofeno, nas últimas\nsemanas, devido a dores musculares relacionadas ao trabalho. Nega tabagismo, etilismo e uso de\ndrogas ilícitas. Ao exame, apresenta temperatura axilar de 37ºC, PA de 80 x 55 mmHg, FC de 119\nbpm, FR de 22 irpm e SpO? de 94% e está hipocorado, com abdome levemente distendido e\nsensível na região epigástrica. O exame da região retal evidencia fezes com melena. Com base\nnesse caso hipotético, assinale a alternativa que apresenta a abordagem inicial mais adequada\npara o paciente.","options":{"A":"endoscopia digestiva alta","B":"reanimação com líquidos intravenosos","C":"inibidores de bomba de prótons","D":"escleroterapia","E":"ligadura elástica"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-179192","number":"179192","sourceNumber":"179192","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 42 anos de idade, foi admitido no serviço de emergência com queixa\nde dor epigástrica, fezes escurecidas e\nfraqueza. Relata que os sintomas tiveram início nas últimas\n24 horas. Nega comorbidades prévias, mas informa uso frequente de ibuprofeno, nas últimas\nsemanas, devido a dores musculares relacionadas ao trabalho. Nega tabagismo, etilismo e uso de\ndrogas ilícitas. Ao exame, apresenta temperatura axilar de 37ºC, PA de 80 x 55 mmHg, FC de 119\nbpm, FR de 22 irpm e SpO? de 94% e está hipocorado, com abdome levemente distendido e\nsensível na região epigástrica. O exame da região retal evidencia fezes com melena. Considere-se\nainda que, à endoscopia digestiva alta, tenha sido evidenciada, nessa situação hipotética, uma\núlcera gástrica com vaso visível não sangrante. Sendo assim, assinale a alternativa que apresenta,\ncorreta e respectivamente, a classificação de Forrest para a úlcera e seu risco de ressangramento.","options":{"A":"Forrest llc e baixo risco","B":"Forrest Ib e risco intermedário","C":"Forrest Ia e alto risco","D":"Forrest lla e alto risco","E":"Forrest lll e alto risco"},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-152130","number":"152130","sourceNumber":"152130","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Considere hipoteticamente que o paciente R. A. S., de 60 anos de idade, agenda\nconsulta ambulatorial de retorno para entregar\nresultados de uma endoscopia digestiva alta e de\numa ultrassonografia de rins e vias urinárias. O paciente trouxe receita do vizinho que teve o\nmesmo problema de saúde, porém melhorou após o uso de determinados medicamentos\nprescritos. R. A. S. apresenta antecedente pessoal de fratura exposta da tíbia com dano extenso às\npartes moles e antecedente familiar de acalasia no pai. Estava ansioso porque, após pesquisa na\ninternet, assemelhou os respectivos sintomas aos de alguns tipos de câncer. Com base nesse caso\nclínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a seguir. Uma\ndas grandes complicações referentes à doença do refluxo gastroesofágico é o esôfago de Barrett,\nem que se infere uma substituição do epitélio pavimentoso estratificado por metaplasia, e não por\ndisplasia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-152140","number":"152140","sourceNumber":"152140","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Considere hipoteticamente que o paciente R. A. S., de 60 anos de idade, agenda\nconsulta ambulatorial de retorno para entregar\nresultados de uma endoscopia digestiva alta e de\numa ultrassonografia de rins e vias urinárias. O paciente trouxe receita do vizinho que teve o\nmesmo problema de saúde, porém melhorou após o uso de determinados medicamentos\nprescritos. R. A. S. apresenta antecedente pessoal de fratura exposta da tíbia com dano extenso às\npartes moles e antecedente familiar de acalasia no pai. Estava ansioso porque, após pesquisa na\ninternet, assemelhou os respectivos sintomas aos de alguns tipos de câncer. Com base nesse caso\nclínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a seguir.\n\nCâncer precoce de esôfago corresponde aos tumores limitados à camada mucosa, sem presença\nde metástases linfonodais, e essa categoria é\ndiferente do câncer superficial de esôfago.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-152078","number":"152078","sourceNumber":"152078","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Considere hipoteticamente que o paciente R. A. S., de 60 anos de idade, agenda\nconsulta ambulatorial de retorno para entregar\nresultados de uma endoscopia digestiva alta e de\numa ultrassonografia de rins e vias urinárias. O paciente trouxe receita do vizinho que teve o\nmesmo problema de saúde, porém melhorou após o uso de determinados medicamentos\nprescritos. R. A. S. apresenta antecedente pessoal de fratura exposta da tíbia com dano extenso às\npartes moles e antecedente familiar de acalasia no pai. Estava ansioso porque, após pesquisa na\ninternet, assemelhou os respectivos sintomas aos de alguns tipos de câncer. Com base nesse caso\nclínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a seguir. Os\nresultados dos procedimentos clínicos, interverncionistas e cirúrgicos indicam o tratamento não\ncirúrgico (incluindo medicamentos e intervenções endoscópicas) como o mais seguro e mais efetivo\nda acalasia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-152092","number":"152092","sourceNumber":"152092","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Considere hipoteticamente que o paciente R. A. S., de 60 anos de idade, agenda\nconsulta ambulatorial de retorno para entregar\nresultados de uma endoscopia digestiva alta e de\numa ultrassonografia de rins e vias urinárias. O paciente trouxe receita do vizinho que teve o\nmesmo problema de saúde, porém melhorou após o uso de determinados medicamentos\nprescritos. R. A. S. apresenta antecedente pessoal de fratura exposta da tíbia com dano extenso às\npartes moles e antecedente familiar de acalasia no pai. Estava ansioso porque, após pesquisa na\ninternet, assemelhou os respectivos sintomas aos de alguns tipos de câncer. Com base nesse caso\nclínico, e considerando os conhecimentos médicos a ele relacionados, julgue o item a seguir.\n\nQualquer plano terapêutico para a doença ulcerosa péptica, tanto clínico quanto cirúrgico, deve\nlevar em conta o H. pylori.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-154359","number":"154359","sourceNumber":"154359","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente com perda ponderal e anorexia, astenia, plenitude pós-prandial, vômitos,\nnáuseas e dispepsia crônica comparece para\ndefinição diagnóstica. Ao exame, há dor à palpação\nepigástrica, massa palpável em epigástrio, hepatomegalia e nódulos de Virchow e de Irmã Maria\nJosé, além de ascite. Paciente relata também episódio isolado de hematêmese e de melena.\n\nAcerca do caso apresentado, é correto afirmar que, no câncer gástrico, entre os sinais\npropedêuticos de doença avançada, o que mais se\ntraduz em carcinomatose peritoneal é o (a):","options":{"A":"Nódulo de Virchow.","B":"Nódulo de Irmã Maria José.","C":"Prateleira de Blummer.","D":"Gânglio de Irish.","E":"Ascite."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-152085","number":"152085","sourceNumber":"152085","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente, 60 anos de idade, com disfagia progressiva há seis meses, com perda de\npeso acentuada, dor torácica atípica, relata que,\nnos últimos meses, vem apresentando disfagia\npara sólidos e agora só consegue engolir alimentos liquidificados. Perdeu 30 kg em um mês.\n\nPaciente é tabagista desde os 15 anos de idade, fumando oito palheiros por dia. Com base nesse\ncaso clínico, julgue o item a seguir. Esôfago\nde Barret tem relação com carcinoma escamoso.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-134981","number":"134981","sourceNumber":"134981","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No que se refere a câncer de esôfago, cirrose e doença de Crohn, hulque o item\nsubsecutivo. O tipo mais frequente de\ncâncer de esôfago em paciente com acalasia é o carcinoma\nepidermoide de esôfago, sendo seu desenvolvimento relacionado com esofagite de estase e\nfermentação dos alimentos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-131805","number":"131805","sourceNumber":"131805","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em relação às moléstias do esôfago, no que se refere à acalásia, assinale a alternativa\nCORRETA:","options":{"A":"A acalásia é definida como uma hipocontratilidade do Esfíncter Esofágico Superior (EES), com\nondas primárias exacerbadas.","B":"O esfíncter esofágico inferior se apresenta hipertensivo em 50% dos casos.","C":"Essa moléstia é o distúrbio motor esofagiano mais raro.","D":"A causa principal é hipertensão arterial sistêmica.","E":"No esofagograma, observa-se a clássica imagem do bico de garrafa."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-135009","number":"135009","sourceNumber":"135009","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente com quarenta anos de idade, natural e procedente de Barreiras (BA),\nprocurou o ambulatório de clínica médica e\ninformou que apresentava quadro de constipação\nintestinal havia seis meses, situação que o obriga a usar laxantes seguidamente. O paciente não\napresenta disfagia e não mostrou alterações dignas de nota no exame físico. Com relação a esse\ncaso clínico, julgue o item seguinte. Em caso de doença de Chagas, a realização do exame\nradiológico contrastado é a melhor forma de diagnosticar o comprometimento intestinal do paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-135015","number":"135015","sourceNumber":"135015","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente com quarenta anos de idade, natural e procedente de Barreiras (BA),\nprocurou o ambulatório de clínica médica e\ninformou que apresentava quadro de constipação\nintestinal havia seis meses, situação que o obriga a usar laxantes seguidamente. O paciente não\napresenta disfagia e não mostrou alterações dignas de nota no exame físico. Com relação a esse\ncaso clínico, julgue o item seguinte. O procedimento de averiguação mais indicado para se\ninvestigar se o referido paciente está acometido por doença de Chagas é pesquisar a presença do\nparasita em sangue periférico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-88675","number":"88675","sourceNumber":"88675","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Julgue o item a seguir, relativo à úlcera péptica. A infecção gástrica pelo Helicobacter\npylori é responsável pela maioria dos casos de\núlcera duodenal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-88670","number":"88670","sourceNumber":"88670","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Julgue o item a seguir, relativo à úlcera péptica. Uma opção apropriada para a\nerradicação do H. pylori e o controle dos sintomas é a associação de um inibidor de bomba\nprotônica com claritromicina e amoxicilina.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-64276","number":"64276","sourceNumber":"64276","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Julgue o item seguinte relativo às neoplasias gástricas: A gastropatia hipertrófica\nhipoproteinêmica, também conhecida como doença\nde Ménétrier, é uma afecção rara, adquirida e\npré-maligna para o câncer gástrico.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-49135","number":"49135","sourceNumber":"49135","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Tendo em vista que o conhecimento da anatomia e fisiologia gástricas é de\nfundamental importância para o entendimento das\ndiversas afecções que acometem o estômago,\njulgue o item a seguir. A gastrina é produzida pelas células G localizadas no antro gástrico.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-45743","number":"45743","sourceNumber":"45743","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A hemorragia digestiva ocorre em aproximadamente um sexto dos pacientes com\ndoença ulcerosa péptica em atividade. A etiologia\nmais frequente das úlceras nesses casos é:","options":{"A":"Anti-inflamatórios não hormonais.","B":"Helicobacter pylori.","C":"Doença de Crohn.","D":"Adenocarcinoma.","E":"Síndrome de Zollinger-Ellison."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-49176","number":"49176","sourceNumber":"49176","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação às queixas ambulatoriais em crianças, julgue o item a seguir. O refluxo\ngastresofágico em lactente pode ser uma manifestação de alergia ao leite de vaca:","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-32191","number":"32191","sourceNumber":"32191","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A respeito da doença do refluxo gastroesofágico (DRGE), assinale a alternativa correta.","options":{"A":"O exame padrão ouro para o diagnóstico dessa doença é a endoscopia digestiva alta.","B":"A DRGE raramente está associada ao gastrinoma.","C":"A DRGE pode causar tosse crônica por reflexo vagal esôfago-pulmonar.","D":"A principal indicação da cirurgia é a constatação de falha do controle da pirose ou dos sinais e\nsintomas extraesofágicos com a medicação.","E":"A estenose péptica é uma complicação da DRGE que ocorre no esôfago proximal."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-32182","number":"32182","sourceNumber":"32182","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O exame padrão-ouro para o diagnóstico de câncer gástrico é a:","options":{"A":"Endoscopia com biópsia.","B":"Radiografia gastrointestinal com duplo contraste.","C":"Ultrassonografia endoscópica.","D":"Tomografia computadorizada com contraste.","E":"Ressonância nuclear magnética."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-32170","number":"32170","sourceNumber":"32170","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação às diversas afecções benignas e malignas que acometem o estômago,\nassinale a alternativa correta.","options":{"A":"A maior parte dos pacientes com lacerações de Mallory-Weiss necessita de tratamento cirúrgico\nde urgência.","B":"Os sarcomas correspondem atualmente a cerca de 40% dos tumores gástricos malignos.","C":"Ao contrário de outras malignidades, os linfomas não têm nenhuma correlação com a infecção\npelo Helicobacter pylori.","D":"A síndrome de Zollinger-Ellison é caracterizada pela hipersecreção gástrica, tumor de células\nbeta do pâncreas e perfuração gástrica.","E":"A doença de Ménétrier, ou gastrite hipertrófica hipoproteinêmica, é uma doença adquirida e\npré-maligna."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-29709","number":"29709","sourceNumber":"29709","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Considerando que o conhecimento da fisiologia e anatomia do estômago é fundamental\npara o entendimento das doenças que o\nacometem, julgue o item que se segue. A fase cefálica da\nsecreção ácida é mediada primariamente pelo nervo vago e responde por 20% a 30% do volume\ntotal do ácido gástrico produzido em resposta a uma refeição.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-27547","number":"27547","sourceNumber":"27547","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale o exame, dentre os abaixo relacionados, que deve ser realizado em um\npaciente com suspeita clínica da síndrome de Zollinger-Ellison","options":{"A":"PHmetria.","B":"Dosagem de ácido vanil-mandélico.","C":"Colonoscopia.","D":"Dosagem de gastrina sérica.","E":"Dosagem de ácido 5-hidróxi-indol-acético."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-13839","number":"13839","sourceNumber":"13839","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Considerando o quadro clínico de um paciente de 35 anos de idade, com sintomas de\npirose há 8 anos e que há 6 meses passou a apresentar regurgitação, assinale a opção correta.","options":{"A":"A pirose é definida como dor do tipo queimação em região epigástrica.","B":"Caso o diagnóstico seja de doença do refluxo gastroesofágico (DRGE), a monitorização do pH\nna junção esofagogástrica é o 1º exame a ser\nsolicitado.","C":"Esse paciente poderá ser submetido à manometria do esôfago, e a conduta terapêutica será\ndefinida em função das informações funcionais dos esfíncteres esofágicos superior e inferior.","D":"Se houver indicação cirúrgica para tratamento de DRGE, a cardiomiotomia seguida de\nfundoplicatura será procedimento cirúrgico de escolha.","E":"Caso a regurgitação desse paciente seja de alimentos não digeridos, ele pode ser portador de\numa divertículo esofágico."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-13842","number":"13842","sourceNumber":"13842","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Considere o caso de um paciente de 52 anos de idade com queixas de dor epigástrica\nem queimação há 6 meses e que apresenta pioras nas\núltimas semanas, tendo sido submetido à\nendoscopia digestiva alta. Com relação a esse caso, assinale a opção correta.","options":{"A":"Caso esse paciente seja etilista, o risco de ele desenvolver adenocarcinoma gástrico é maior.","B":"Se a endoscopia revelar uma lesão ulcerada rodeada por bordas elevadas, ela será considerada\nlesão de Bormann do tipo III.","C":"A dosagem do marcador tumoral CA 19-9 poderá esclarecer se os sintomas são decorrentes de\ndoença gástrica maligna.","D":"Caso esse paciente seja portador de adenocarcinoma gástrico, a presença do sinal de Virchow\nrepresenta metástase para linfonodo supraclavicular.","E":"A endoscopia desse paciente pode revelar linite plástica, que representa o comprometimento\napenas do fundo gástrico por um adenocarcinoma."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-352365","number":"352365","sourceNumber":"352365","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Considerando as imagens apresentadas e os temas que ela suscita bem como seus\nconhecimentos prévios, julgue os itens de 15 a 17. A partir da figura I, é possível observar a\nlocalização anatômica do triângulo de Killian, situado entre as fibras oblíquas do músculo\ntireofaríngeo e as fibras horizontais do músculo cricofaríngeo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/352365.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-352364","number":"352364","sourceNumber":"352364","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Considerando as imagens apresentadas e os temas que ela suscita bem como seus\nconhecimentos prévios, julgue os itens de 15 a 17. A hipótese diagnóstica indicada na figura II é\nconhecida como acalásia cricofaríngea, e geralmente se manifesta em pacientes na sétima década\nde vida. Essa condição é postulada devido a um aumento da elasticidade da mucosa e do tônus\nmuscular associado ao envelhecimento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/352364.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-352363","number":"352363","sourceNumber":"352363","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Considerando as imagens apresentadas e os temas que ela suscita bem como seus\nconhecimentos prévios, julgue os itens de 15 a 17. Os divertículos podem ser considerados de\npulsão como o de Zenker e o epifrênico, sendo este último considerado um divertículo verdadeiro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/352363.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-334872","number":"334872","sourceNumber":"334872","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No tratamento da doença representada nesse exame radiológico contrastado, podem\nser usadas determinadas técnicas cirúrgicas.\nAssinale a alternativa que indica essas técnicas.","options":{"A":"Cardioplastia à Thal-Hatafuku e operação de Duhamel","B":"Operação de Duhamel e esofagectomia","C":"Cardiomiotomia à Heller e operação de Frey","D":"Cardioplastia à Thal-Hatafuku e esofagectomia","E":"Cardiomiotomia à Heller e operação de Whipple"},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/334872.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-334874","number":"334874","sourceNumber":"334874","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Uma paciente de 40 anos de idade procura serviço de emergência queixando-se de dor\nem queimação localizada na região anterior do tórax, que se irradia para o pescoço e tem a\nalimentação e a posição supina como fatores de precipitação. A paciente negou que o esforço\ndesencadeie o sintoma. O eletrocardiograma (ECG) seriado e os biomarcadores cardíacos se\nmostraram sem alterações. Com base no exposto, assinale a alternativa que indica o próximo\npasso a ser seguido nesse caso.","options":{"A":"Solicitar teste ergométrico.","B":"Solicitar parecer da psiquiatria.","C":"Prescrever inibidor de bomba de próton.","D":"Solicitar tomografia de tórax.","E":"Prescrever ácido acetilsalicílico."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-307095","number":"307095","sourceNumber":"307095","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 45 anos de idade compareceu à consulta com queixa de disfagia.\nRefere que apresenta disfagia para alimentos\nsólidos, de início há sete meses, e de caráter\nprogressivo, atualmente com dificuldade de ingestão de líquidos. O esofagograma baritado é\nnormal e não apresenta megaesôfago. A manometria esofágica apresenta aperistalse no corpo\nesofágico e hipertonia do esfíncter esofágico inferior. Nesse caso clínico, o diagnóstico mais\nprovável é:","options":{"A":"Hérnia de hiato esofágico.","B":"Espasmo esofagiano difuso.","C":"Esôfago em quebra-nozes.","D":"Doença do refluxo gastroesofágico.","E":"Acalásia."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-307096","number":"307096","sourceNumber":"307096","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Em relação à doença do refluxo gastroesofágico (DRGE), assinale a alternativa correta.","options":{"A":"O esôfago de Barrett é fator de risco para adenocarcinoma esofágico.","B":"É mais comum em jovens do sexo feminino.","C":"Esofagectomia é o tratamento padrão-ouro para esôfago de Barrett.","D":"A sintomatologia mais comum da DRGE é dor torácica, seguida de lesões orais.","E":"Tem forte associação com carcinoma epidermoide de esôfago."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-307106","number":"307106","sourceNumber":"307106","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente foi atendido em pronto atendimento com queixa de pirose e regurgitação,\nrelatando que, nas últimas semanas, está com\ntosse, odinofagia e eructações. Diante disso, ele foi\ndiagnosticado como doença do refluxo gastroesofágico (DRG). Tendo em vista esse caso clínico,\nassinale a alternativa correta. Alternativas:","options":{"A":"A elevação da cabeceira e a diminuição da ingesta de álcool e gorduras não têm impacto na\nDRG.","B":"O controle do peso não muda o prognóstico dessa doença e seu tratamento.","C":"A correção cirúrgica pode ser indicada quando o paciente, a despeito da aderência adequada ao\ntratamento, segue com esofagite redicivante.","D":"O prognóstico dos pacientes com DRG não tratados é sem complicações e com alto índice de\nresolução.","E":"Na presença de esôfago de Barrett, não há necessidade de exames para controle."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-266409","number":"266409","sourceNumber":"266409","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente do sexo masculino, com 60 anos de idade, procurou ambulatório com\nqueixa de disfagia progressiva, existente\nhavia 10 anos, com piora importante 2 meses antes desse\natendimento ambulatorial. No momento, queixava-se de que não conseguia se alimentar nem de\nlíquidos, com perda ponderal de 8 kg no período. Como antecedentes importantes, apresentava\numa carga tabágica de 20 maços/ano, etilismo de meio litro de destilados ao dia, epidemiologia\npositiva para doença de Chagas, sem históricos de câncer na família. A partir do caso clínico\nhipotético apresentado, julgue o item a seguir. A sorologia para doença de Chagas é essencial para\na definição do tipo de tratamento a ser realizado nesse paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-266410","number":"266410","sourceNumber":"266410","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente do sexo masculino, com 60 anos de idade, procurou ambulatório com\nqueixa de disfagia progressiva, existente\nhavia 10 anos, com piora importante 2 meses antes desse\natendimento ambulatorial. No momento, queixava-se de que não conseguia se alimentar nem de\nlíquidos, com perda ponderal de 8 kg no período. Como antecedentes importantes, apresentava\numa carga tabágica de 20 maços/ano, etilismo de meio litro de destilados ao dia, epidemiologia\npositiva para doença de Chagas, sem históricos de câncer na família. A partir do caso clínico\nhipotético apresentado, julgue o item a seguir. Câncer de esôfago é uma das possíveis hipóteses\ndiagnósticas, pois o paciente apresenta vários fatores de risco para essa doença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-268883","number":"268883","sourceNumber":"268883","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 62 anos de idade procura atendimento em consultório por dor\nepigástrica, saciedade precoce e perda de 5 kg no\núltimo mês, sem alterações nos seus hábitos\nalimentares. É realizada uma endoscopia digestiva alta, associada a ultrassom endoscópico e a\nbiópsia. O resultado do anatomopatológico foi positivo para Helicobacter pylori e para\nadenocarcinoma gástrico que invade a submucosa. Os linfonodos regionais não apresentam\nmetástases. Em relação a esse caso clínico e ao adenocarcinoma gástrico, assinale a alternativa\nCORRETA.","options":{"A":"A classificação de tumor primário (T) é T2.","B":"As tomografias computadorizadas de crânio, tórax, abdome e pelve são mandatórias para a\navaliação de metástases.","C":"Múltiplas biópsias (de seis a oito) devem ser realizadas em áreas diferentes da lesão, a fim de\naumentar o rendimento para 98%.","D":"A tomografia computadorizada por emissão de pósitrons (PET-TC) é essencial para o\ndiagnóstico de metástases a distância, visto que 80% dos cânceres gástricos são PET-ávidos.","E":"A infecção de Helicobacter pylori não representa um agente cancerígeno, sendo desnecessário\no seu tratamento."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-266411","number":"266411","sourceNumber":"266411","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente do sexo masculino, com 60 anos de idade, procurou ambulatório com\nqueixa de disfagia progressiva, existente\nhavia 10 anos, com piora importante 2 meses antes desse\natendimento ambulatorial. No momento, queixava-se de que não conseguia se alimentar nem de\nlíquidos, com perda ponderal de 8 kg no período. Como antecedentes importantes, apresentava\numa carga tabágica de 20 maços/ano, etilismo de meio litro de destilados ao dia, epidemiologia\npositiva para doença de Chagas, sem históricos de câncer na família. A partir do caso clínico\nhipotético apresentado, julgue o item a seguir. O tratamento cirúrgico deve ser realizado de\nimediato, devido à impossibilidade de ingesta oral pelo paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-268884","number":"268884","sourceNumber":"268884","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Uma paciente de 67 anos de idade iniciou fezes escuras com sangue, dor abdominal e\ndisfagia há seis meses. Evoluiu com emagrecimento espontâneo de 5 kg em 15 dias. Realizou\ncolonoscopia e endoscopia para investigação da causa do melena. Na endoscopia digestiva alta,\nfoi encontrado um tumor de 6 cm liso, com ulceração central, localizado no estômago.\n\nConsiderando esse caso clínico, acerca dos tumores estromais gastrointestinais (GIST), assinale a\nalternativa correta.","options":{"A":"Os GIST podem se formar em qualquer segmento do trato gastrointestinal, principalmente, no\nestômago, no intestino delgado e no cólon.","B":"Os fatores de risco mais comuns para malignidade são o tamanho da lesão e os números de\nmetástases linfonodais.","C":"Os lugares mais propícios para a progressão do GIST são o cérebro e o pulmão.","D":"A ruptura do tumor intra-abdominal é extremamente comum e, com a devida estabilidade\nhemodinâmica, ele pode ser embolizado.","E":"A imuno-histoquímica não ajuda no diagnóstico diferencial para outros tumores gástricos."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-266412","number":"266412","sourceNumber":"266412","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente do sexo masculino, com 60 anos de idade, procurou ambulatório com\nqueixa de disfagia progressiva, existente\nhavia 10 anos, com piora importante 2 meses antes desse\natendimento ambulatorial. No momento, queixava-se de que não conseguia se alimentar nem de\nlíquidos, com perda ponderal de 8 kg no período. Como antecedentes importantes, apresentava\numa carga tabágica de 20 maços/ano, etilismo de meio litro de destilados ao dia, epidemiologia\npositiva para doença de Chagas, sem históricos de câncer na família. A partir do caso clínico\nhipotético apresentado, julgue o item a seguir. Os sinais e sintomas da acalasia são causados\nprincipalmente pela falha de relaxamento do esfíncter esofagiano inferior durante a deglutição.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-266428","number":"266428","sourceNumber":"266428","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente do sexo masculino, de 35 anos de idade, procurou atendimento médico\npor apresentar epigastralgia, tipo queimação,\nassociada a pirose havia três meses, principalmente\napós refeições e durante o sono. Foi realizado exame de endoscopia digestiva alta, que sugeriu o\ndiagnóstico de doença do refluxo gastroesofágico (DRGE). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à DRGE, julgue o item a seguir. Obesidade e ingesta de\nalimentos gordurosos são fatores de risco para DRGE.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-273331","number":"273331","sourceNumber":"273331","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Dentre as síndromes de câncer familiar, é correto afirmar que:","options":{"A":"Polipose adenomatosa familiar está relacionada à mutação do gene BRCA 1 (17q12-3) e câncer\nde célula renal.","B":"A síndrome de Li Fraumeni está relacionada à mutação do gene P16 (3p21) e feocromocitoma.","C":"A Neoplasia Endócrina Múltipla tipo 2 (NEM 2) está relacionada à mutação do ret e câncer da\ntireóide, adenoma hipofisário e tumor de pâncreas.","D":"O câncer gástrico difuso hereditário está relacionado à mutação do CDH1 (16q22) e câncer\ngástrico."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-266429","number":"266429","sourceNumber":"266429","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente do sexo masculino, de 35 anos de idade, procurou atendimento médico\npor apresentar epigastralgia, tipo queimação,\nassociada a pirose havia três meses, principalmente\napós refeições e durante o sono. Foi realizado exame de endoscopia digestiva alta, que sugeriu o\ndiagnóstico de doença do refluxo gastroesofágico (DRGE). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à DRGE, julgue o item a seguir. Os sintomas de pirose e\nepigastralgia apresentados pelo paciente são manifestações atípicas da DRGE.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-266430","number":"266430","sourceNumber":"266430","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente do sexo masculino, de 35 anos de idade, procurou atendimento médico\npor apresentar epigastralgia, tipo queimação,\nassociada a pirose havia três meses, principalmente\napós refeições e durante o sono. Foi realizado exame de endoscopia digestiva alta, que sugeriu o\ndiagnóstico de doença do refluxo gastroesofágico (DRGE). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à DRGE, julgue o item a seguir. Mudanças comportamentais,\ncomo dieta fracionada e elevação da cabeceira da cama, são essenciais para a melhora clínica do\npaciente em tela.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-266431","number":"266431","sourceNumber":"266431","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente do sexo masculino, de 35 anos de idade, procurou atendimento médico\npor apresentar epigastralgia, tipo queimação,\nassociada a pirose havia três meses, principalmente\napós refeições e durante o sono. Foi realizado exame de endoscopia digestiva alta, que sugeriu o\ndiagnóstico de doença do refluxo gastroesofágico (DRGE). Com relação ao caso clínico hipotético\nprecedente e a aspectos relacionados à DRGE, julgue o item a seguir. No caso em apreço, a\nrealização do teste terapêutico com inibidor de bomba de prótons (IBP) com resposta clínica\nnegativa excluiria o diagnóstico de DRGE.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-263421","number":"263421","sourceNumber":"263421","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente com 32 anos de idade, tabagista, com histórico de epigastralgia,\napresentou, há cerca de 4 horas, quadro de\nhematêmese e melena. Ao chegar a um pronto-socorro\nhospitalar, encontrava-se com PA = 90 x 50 mmHg e FC = 112 bpm. No local, foram realizadas\nreposição volêmica com normalização dos parâmetros hemodinâmicos bem como endoscopia\ndigestiva alta, que evidenciou úlcera péptica localizada na incisura angularis do estômago, com\nvaso visível, porém sem sangramento ativo. Realizou-se, então, terapia combinada de hemostasia\nda úlcera. Nesse caso, a conduta imediata adequada para o paciente é indicar:","options":{"A":"Internação hospitalar e preparação para a cirurgia de emergência.","B":"Internação hospitalar, octreotide endovenoso e repetição da endoscopia em 48 horas.","C":"Internação hospitalar, inibidor de bomba de prótons endovenoso e monitorização hemodinâmica\nnão invasiva.","D":"Alta hospitalar, inibidor de bomba de prótons por via oral por 30 dias e repetição de endoscopia\ndigestiva alta em 3 meses."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-291552","number":"291552","sourceNumber":"291552","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um homem, com 58 anos de idade, foi atendido em ambulatório de hospital secundário.\nRelatava dor e queimação epigástrica que aumentava após a ingestão de alimentos, acompanhada\nde plenitude pós-prandial. Realizou endoscopia digestiva alta que evidenciou úlcera com 5 mm de\ndiâmetro na parede anterior do antro gástrico, na região pré-pilórica. Com base nos dados\napresentados, assinale a alternativa que apresenta a conduta adequada a ser seguida.","options":{"A":"Solicitar endoscopia com biópsias seriadas para excluir neoplasia gástrica e pesquisar\nHelicobacter pylori.","B":"Indicar tratamento operatório pela localização da úlcera e risco de perfuração.","C":"Prescrever inibidor de secreção gástrica por 6 a 8 semanas e solicitar endoscopia com pesquisa\nde Helicobacter pylori, avaliando a cicatrização.","D":"Prescrever inibidor da secreção gástrica e tratar Helicobacter pylori empiricamente por sua\nprevalência em ulcerosos, evitando recidiva."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-227393","number":"227393","sourceNumber":"227393","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A respeito da Doença de Refluxo Gastroesofágico (DRGE) e da estenose péptica do\nesôfago distal, julgue o item seguinte. O esôfago de Barrett, condição clínica associada à\ncomplicação da DRGE, predispõe a pessoa a carcinoma epidermoide do esôfago distal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-227394","number":"227394","sourceNumber":"227394","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A respeito da doença de refluxo gastroesofágico (DRGE) e da estenose péptica do\nesôfago distal, julgue o item seguinte. O exame radiológico contrastado do esôfago não evidencia\nestenose péptica do esôfago distal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-227395","number":"227395","sourceNumber":"227395","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A respeito da doença de refluxo gastroesofágico (DRGE) e da estenose péptica do\nesôfago distal, julgue o item seguinte. Para\npaciente com esofagite grave por DRGE, deve-se\nprescrever o uso de inibidor de bomba de prótons por duas vezes ao dia, sem tempo determinado\nde tratamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-227396","number":"227396","sourceNumber":"227396","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A respeito da doença de refluxo gastroesofágico (DRGE) e da estenose péptica do\nesôfago distal, julgue o item seguinte. A DRGE resulta de falha de uma das defesas do esôfago,\ncomo a resistência intrínseca do epitélio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-203066","number":"203066","sourceNumber":"203066","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 60 anos de idade, procedente de Santa Maria da Vitória (BA), procura\no ambulatório com histórico de disfagia\nprogressiva há 20 anos, com piora importante há um mês,\nevoluindo com disfagia total. Refere perda de 6 kg em um mês. O paciente é tabagista e etilista há\n45 anos. Considerando esse caso clínico, no momento o exame mais indicado para o paciente e o\n(a):","options":{"A":"Esofagograma.","B":"Sorologia para doença de Chagas.","C":"Endoscopia digestiva alta.","D":"Esofagomanometria.","E":"Tomografia computadorizada de tórax e abdome."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-203056","number":"203056","sourceNumber":"203056","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Considere um paciente de 68 anos de idade com histórico de dor epigástrica há três\nmeses. Ele realizou endoscopia digestiva\nalta com achado de lesão de 2 cm em antrogástrico,\nBormann II, cuja biópsia mostrou adenocarcinoma do tipo intestinal, com células em anel de sinete.\nRealizou estadiamento clínico que sugeriu T2, sem evidências de metástases linfonodais ou a\ndistância. Com relação a esse caso clínico, a conduta indicada é:","options":{"A":"Quimioterapia neoadjuvante.","B":"Ressecção endoscópica.","C":"Gastrectomia total com linfadenectomia à DII.","D":"Gastrectomia subtotal com linfadenectomia à DII.","E":"Quimioterapia e radioterapia exclusivas."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-206178","number":"206178","sourceNumber":"206178","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Apesar de a etiologia ser desconhecida, há fatores hereditários e não hereditários\nclaramente associados ao aparecimento e\ndesenvolvimento do câncer gástrico. Os fatores de risco\nconhecidos devem-se a diversos aspectos. Quanto a isso, indique o item INCORRETO:","options":{"A":"Origem infecciosa, como infecção gástrica pelo Helicobacter pylori.","B":"Características demográficas, como idade avançada e sexo masculino.","C":"Hábitos de vida, como dieta rica em produtos de origem vegetal, dieta pobre em sal, consumo de\nalimentos conservados de determinadas formas, como defumação ou conserva, e exposição a\ndrogas, como tabagismo.","D":"Associação com doenças, como gastrite atrófica crônica, metaplasia intestinal da mucosa\ngástrica, anemia perniciosa, pólipo adenomatoso do estômago, gastrite hipertrófica gigante."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-206165","number":"206165","sourceNumber":"206165","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Quando da suspeita do diagnóstico adenocarcinoma do estômago, o paciente deve ser\nsubmetido à endoscopia digestiva alta, para biopsiar lesões. O tratamento deve ser realizado\npreferencialmente em centros especializados, com grande número de atendimentos, cujos\nresultados sejam validados e apresentados periodicamente. NÃO sendo adequado que:","options":{"A":"Tomografia computadorizada de abdômen total e tórax com contraste oral e venoso deve ser\nrealizada para definir o estadiamento e planejar o tratamento, já que comumente a doença se\napresenta em estágios avançados, e o tratamento é não definido por sua extensão na\napresentação.","B":"Ressonância magnética deve ser solicitada caso seu resultado possa alterar a conduta\nterapêutica inicial.","C":"Outros exames de imagem, como a ultrassonografia endoscópica (também conhecida por\necoendoscopia), podem auxiliar na avaliação da extensão locorregional da doença.","D":"Exames laboratoriais são realizados para avaliar as condições clínicas do paciente."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-206113","number":"206113","sourceNumber":"206113","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre o esôfago de Barret, assinale a alternativa INCORRETA:","options":{"A":"40% dos pacientes com refluxo gastroesofágico desenvolvem o esôfago de Barret.","B":"A Metaplasia Intestinal incompleta que ocorre no esôfago de Barret inclui células gástricas\nsuperficiais, células caliciformes intestinais e células absortivas intestinais.","C":"A ressecção esofágica é recomendada para pacientes com displasia de alto grau. A\nesofagectomia subtotal transhiatal é recomendada para maioria dos pacientes.","D":"Pacientes com esôfago de Barret tem risco 40 vezes maior de desenvolver carcinoma esofágico."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-206136","number":"206136","sourceNumber":"206136","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A mortalidade da hemorragia digestiva alta diminuiu expressivamente após a evolução\nda terapêutica endoscópica, estando em torno de 5 a\n14%. Sobre isso, é INCORRETO afirmar:","options":{"A":"A hemorragia digestiva alta não varicosa é autolimitada em até 80% dos casos, sem\nnecessidade de intervenções.","B":"Não há indício que os hepatopatas tenham maior chance que a população geral de desenvolver\nlesão pulmonar aguda associado à transfusão.","C":"Infecções são comuns em doentes com hemorragia digestiva alta varicosa, chegando a 50%\ndurante o período de internação do doente.","D":"Segundo a Classificação de Forrest, a lesão ulcerosa com coágulo aderido corresponde ao tipo\nIIa."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-206152","number":"206152","sourceNumber":"206152","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Acalasia é a doença mais bem compreendida de todos os distúrbios da motilidade\nesofágica. É INCORRETO afirmar sobre as\ncaracterísticas manométricas esofágicas da Acalasia\ntípica:","options":{"A":"Amplitude pressórica < 40 mmHg.","B":"Ondas de contração simultâneas.","C":"Ausência de peristalse.","D":"Pressão do esfíncter esofágico inferior entre 15 e 25 mmHg."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-206160","number":"206160","sourceNumber":"206160","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre a Vagotomia Troncular para o tratamento da Úlcera Gástrica, assinale a\nalternativa INCORRETA:","options":{"A":"É realizada pela secção do nervo vago esquerdo e direito acima dos ramos hepáticos e celíacos.","B":"É provavelmente a operação mais realizada para doença ulcerosa duodenal.","C":"Quando o bulbo duodenal está muito deformado e fibrosado uma piloplastia Finney pode ser\numa alternativa útil.","D":"Apresentam menores taxas de diarreia e dumping quando comparadas à vagotomia\nsuperseletiva."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-206082","number":"206082","sourceNumber":"206082","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Levantamentos demográficos recentes mostraram que a incidência de neoplasias\nmalignas do intestino delgado tem aumentado ao longo das últimas três décadas. Sobre isso,\nassinale a alternativa INCORRETA:","options":{"A":"Os tumores malignos de intestino delgado mais frequentes são tumores carcinoides,\nadenocarcinoma, linfoma e GIST.","B":"Em crianças menores de 10 anos o tumor maligno do intestino delgado mais comum é o\nLinfoma.","C":"Os Tumores Estromais Gastrintestinais têm o melhor prognóstico de todos os tumores do\nintestino delgado, na forma localizada ou metastática.","D":"Macroscopicamente os linfomas de intestino delgado são volumosos e podem se projetar além\nda mucosa."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-183876","number":"183876","sourceNumber":"183876","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No que se refere às enfermidades gastrointestinais, julgue o item que se segue. Os\nsintomas clínicos de esofagopatia chagásica devem-se, principalmente, ao refluxo gastroesofágico\ncausado pela acalásia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-175128","number":"175128","sourceNumber":"175128","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Segundo a classificação de Lauren para o adenocarcinoma gástrico, aponte a\nalternativa que NÃO corresponde ao tipo intestinal:","options":{"A":"Atrofia gástrica.","B":"Relacionada a fatores familiares.","C":"Disseminação hematogênica.","D":"Formação de glândulas."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-175142","number":"175142","sourceNumber":"175142","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A figura abaixo demonstra o esôfago, pela vista posterior e pelo lado direito. A\nalternativa que corresponde, respectivamente,\naos divertículos do esôfago representados por *, ** e\n\n*** são:","options":{"A":"Faringoesofágico, Tração e Justagástrico.","B":"Tração, Zenker e Epifrênico.","C":"Zenker, Tração e Epifrênico.","D":"Tração, Médio esofágico e Epifrênico."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":["question_bank/media/medcurso/medcurso-gastrologia-gas-1/175142.png"],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-159561","number":"159561","sourceNumber":"159561","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente portadora de artrite reumatoide e que faz uso contínuo de inibidor de bomba\nde prótons compareceu ao ambulatório de\ncirurgia-geral, relatando desconforto retroesternal tipo\nqueimação, regurgitação e episódios de disfagia a sólidos. Após ser submetida a videoendoscopia\ndigestiva alta, constatou-se que a paciente apresentava esofagite erosiva por refluxo tipo C de Los\nAngeles. Em seguida, procedeu-se à avaliação funcional do esôfago por manometria esofágica e\npHmetria esofágica de dois canais, para se avaliar a possibilidade de tratamento cirúrgico. A partir\ndo caso clínico apresentado, julgue o próximo item. É bastante provável que a avaliação\nmanométrica do esôfago dessa paciente indique um esfincter inferior do esôfago hipotônico e\ndistúrbio hipocontrátil dos dois terços inferiores do esôfago distal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-159541","number":"159541","sourceNumber":"159541","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No que se refere ao megaesôfago e ao megacólon decorrentes da tripanossomíase\n\nsul-americana, julgue o item subsecutivo. Fecaloma, vólvulo, colite isquêmica e úlcera colônica são\ncomplicações associadas ao megacólon chagásico.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-159543","number":"159543","sourceNumber":"159543","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No que se refere ao megaesôfago e ao megacólon decorrentes da tripanossomíase\nsul-americana, julgue o item subsecutivo. No\ncaso de paciente de trinta e dois anos de idade com\ndiagnóstico de dolicomegaesôfago, recomenda-se a realização de tratamento com benznidazol\ndurante sete dias.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-158033","number":"158033","sourceNumber":"158033","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 60 anos de idade, sexo feminino, tabagista ativa, procedente do Rio grande\ndo Sul, em investigação de dor epigástrica,\nrealizou endoscopia digestiva alta, que mostrou lesão\nvegetante localizada no fundo gástrico. A biópsia dela confirmou tratar-se de um adenocarcinoma.\nCom base nesse caso clínico e nos conhecimentos médicos a ele relacionados, assinale a\nalternativa CORRETA.","options":{"A":"O adenocarcinoma é o segundo tipo histológico mais comum dos tumores gástricos.","B":"O principal tratamento para o adenocarcinoma gástrico é a quimioterapia associada a\nradiografia.","C":"A ultrassonografia endoscópica parece ser o método mais adequado para avaliar a profundidade\nda lesão.","D":"A laparoscopia ja foi um procedimento de grande importância na avaliação do estádio do câncer\ngástrico, principalmente na avaliação dos cânceres avançados, mas perdeu espaço para a\nressonância magnética de abdome.","E":"A cirurgia-padrão com intuito curativo é a gastrectomia com linfadenectomia D1."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-129015","number":"129015","sourceNumber":"129015","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Acerca da hemorragia gastrointestinal aguda, assinale a alternativa correta.","options":{"A":"A doença ulcerosa péptica representa a causa individual mais frequente de hemorragia alta não\nvaricosa.","B":"A neoplasia dos cólons representa a causa mais comum de hemorragia baixa maciça.","C":"A coagulação com plasma de argônio é a terapia que apresenta melhores resultados no manejo\nconservador das varizes do fundo gástrico.","D":"O exame com radionuclídeos, utilizando eritrócitos marcados com tecnécio-99m, é o método\nmais preciso para a localização do ponto de sangramento nas hemorragias baixas.","E":"A colonoscopia só deve ser realizada após o desaparecimento de qualquer sinal de\nsangramento."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-129021","number":"129021","sourceNumber":"129021","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente com quarenta anos de idade foi submetido à vagotomia troncular com\nantrectomia e reconstrução do trânsito intestinal por gastrojejunostomia do tipo Billroth II para\ntratamento de doença ulcerosa péptica. Por apresentar persistência dos sintomas pépticos no\n\npós-operatório, foi submetido à investigação laboratorial e, embora apresentasse valor de gastrina\nsérica normal no pré-operatório, ela agora estava elevada. Com base nesse caso hipotético,\nassinale a alternativa que apresenta a causa mais provável de hipergastrinemia nesse paciente:","options":{"A":"Hiperplasia de células G.","B":"Síndrome de Zollinger-Ellison.","C":"Síndrome de intestino curto.","D":"Anemia perniciosa.","E":"Antro excluído retido."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-129023","number":"129023","sourceNumber":"129023","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale a alternativa que apresenta a localização mais comum para os linfomas no\ntrato gastrointestinal.","options":{"A":"Esôfago.","B":"Estômago.","C":"Duodeno.","D":"Íleo.","E":"Reto."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-129032","number":"129032","sourceNumber":"129032","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente com 35 anos de idade, portador de doença de Crohn há cerca de quinze\nanos, apresentou-se com sintomas de obstrução\nintestinal alta. Foi submetido a exames de\nimagem, enterotomografia abdominal e enterorressonância de abdome, que demonstraram áreas\nde estenose compatíveis com fibrose. Considerando essa situação hipotética, assinale a alternativa\nque apresenta a conduta mais apropriada para a resolução definitiva da obstrução intestinal.","options":{"A":"Uso de terapia com medicamentos biológicos.","B":"Prescrição de corticoides.","C":"Terapia de nutrição enteral de alta absorção.","D":"Prescrição de medicação estimuladora da motilidade intestinal.","E":"Ressecção intestinal ou plástica das estenoses."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-133990","number":"133990","sourceNumber":"133990","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale a alternativa que não indica complicação clássica pós-gastrectomia.","options":{"A":"Síndrome de Dumping precoce.","B":"Síndrome de Dumping tardia.","C":"Síndrome da alça aferente.","D":"Síndrome da alça eferente.","E":"Fecaloma."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-133932","number":"133932","sourceNumber":"133932","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Quanto ao esôfago em quebra-nozes, é CORRETO afirmar que:","options":{"A":"Esse é o distúrbio motor mais comum do esôfago.","B":"O esôfago, na manometria, apresenta alta pressão (> 180 mmHg).","C":"Dor torácica e tosse são sintomas raros.","D":"As contrações peristálticas podem ser normais, mas o EEI não relaxa.","E":"O tratamento cirúrgico é a primeira escolha, sendo preconizada a miotomia ampla via torácica."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-129055","number":"129055","sourceNumber":"129055","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"No que se refere à doença do refluxo gastroesofágico (DRGE), assinale a alternativa\ncorreta.","options":{"A":"A DRGE decorre do fluxo anterógrado de parte do conteúdo gastroduodenal para o esôfago\ne(ou) para os órgãos adjacentes a ele.","B":"São consideradas causas de DRGE: erosões; úlceras; estenose péptica; e esôfago de Barrett.","C":"O achado incidental e isolado de hérnia de hiato por exame endoscópico é diagnóstico de\nDRGE.","D":"A ausência de alterações endoscópicas da DRGE exclui o seu diagnóstico.","E":"As principais manifestações clínicas típicas da DRGE são pirose e regurgitação ácida."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-133944","number":"133944","sourceNumber":"133944","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale a alternativa que não apresenta fator de risco reconhecidamente para câncer\nde esôfago.","options":{"A":"Etilismo.","B":"Tabagismo.","C":"Esôfago de Barret.","D":"Esclerodermia.","E":"Diabetes mellitus."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-133954","number":"133954","sourceNumber":"133954","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Considere hipoteticamente que determinado paciente de 47 anos de idade, hígido, com\nbom performance status, procurou o serviço de\ncirurgia com disfagia e emagrecimento. Na\nendoscopia digestiva alta, observou-se lesão polipoide de 3 cm limitada a 40% da luz esofágica a\n36 cm da arcada dentária superior. Os exames de imagem indicaram lesão limitada ao esôfago\nsem disseminação a distância, assim como PET-Scan, e a ecoendoscopia classificou como\nT2N0M0. Nesse caso, a conduta mais apropriada para esse paciente é a","options":{"A":"Quimeoterapia exclusiva com cisplatina.","B":"Esofagectomia por via laparoscópica com gastric-pull-up.","C":"Radioterapia e quimioterapia exclusivas","D":"Ressecção endoscópica por ecoendoscopia.","E":"Radioterapia exclusiva com bomba de elétrons."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-133956","number":"133956","sourceNumber":"133956","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação ao câncer gástrico, assinale a alternativa CORRETA.","options":{"A":"O subtipo histológico mais comum é o carcinoma epidermoide.","B":"O GIST é mais comum em indivíduos idosos com mais de 70 anos de idade.","C":"O tratamento para o carcinoide gástrico tipo I é sempre a gastrectomia radical ampliada com\nlinfadenectomia D2.","D":"O adenocarcinoma inicial restrito a mucosa pela ecoendoscopia pode ser tratado com ressecção\nendoscópica.","E":"O tratamento do GIST é amiúde o uso terapia-alvo como imatinibe ou sunitinibe."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-133969","number":"133969","sourceNumber":"133969","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"A respeito do adenocarcinoma gástrico, assinale a alternativa CORRETA.","options":{"A":"É o câncer mais comum no homem no Brasil.","B":"Pode ser familial em até 10% dos casos.","C":"Pode ser identificado, pela classificação de Lauren, em tipo intestinal mais comumente\nobservado no cárdia e de melhor prognóstico\nou tipo difuso, mais comum no antro e com excelente\nprognóstico.","D":"A classificação de Borrmann é preditiva de prognóstico, sendo os tumores vegetantes e\npolipoides, isto é, Borrmann III, os de pior prognóstico.","E":"A ressecção endoscópica por ecoendoscopia é o padrão ouro para as lesões ulceradas menores\nque 3 cm."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-111326","number":"111326","sourceNumber":"111326","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O tronco celíaco, tipicamente, dá origem a três artérias. Assinale-as.","options":{"A":"Hepática direita, hepática esquerda e gástrica direita.","B":"Gastroduodenal, hepática comum e gástrica esquerda.","C":"Esplênica, hepática comum e gástrica esquerda.","D":"Hepática comum, gástrica direita e gastroduodenal.","E":"Hepática direita gástrica direita e esplênica."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-111356","number":"111356","sourceNumber":"111356","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem de 40 anos com quadro agudo de dor súbita no epigástrio e irradiação para\ntodo o abdome há seis horas, vômitos\nclaros no início e parada da eliminação de gases. No exame\nfísico, com contratura abdominal e com sinais de irritação peritoneal em todo o abdome. O exame\ncomplementar inicial a ser realizado será:","options":{"A":"RX de tórax e abdome.","B":"Hemograma completo.","C":"Urina.","D":"Ultrassonografia de abdome total.","E":"Tomografia computadorizada de abdome total."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-111267","number":"111267","sourceNumber":"111267","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O pediatra é chamado para atender um recém-nascido com 27 dias com queixas de\nvômitos, não biliosos, desde os 17 dias de vida. Evacuação 1 vez ao dia. Nasceu com 38 semanas,\npeso de 3 300 g. Aleitamento materno exclusivo. Peso atual 3 500 g. Ao exame físico, observa-se\ndistensão epigástrica, com ondas peristálticas visíveis e palpa-se tumoração cilíndrica, 3 x 2 cm,\nduro, elástica, no hipocôndrio direito, junto à borda do músculo reto abdominal. Qual é a doença\ncompatível com essa descrição e em qual sexo ela é mais prevalente?","options":{"A":"Atresia duodenal, masculino.","B":"Atresia duodenal, feminino.","C":"Estenose hipertrófica de piloro, masculino.","D":"Estenose hipertrófica de piloro, feminino.","E":"Hematoma duodenal, sem prevalência de sexo."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-111323","number":"111323","sourceNumber":"111323","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente do sexo masculino, 72 anos, hipertenso, fez cirurgia gástrica com\ndiagnóstico anatomopatológico de câncer gástrico.\nAlguns meses depois apresentou acidente\nvascular cerebral, com hemiplegia. Na internação constataram-se metástases pulmonares, com\npiora respiratória progressiva e diagnóstico de broncopneumonia uma semana antes do óbito. O\npreenchimento da Declaração de Óbito desse paciente está apresentado abaixo: Parte I- Causa da\nmorte: Broncopneumonia ? 7 dias; Metástases pulmonares - meses; Câncer gástrico - meses; II -\nHipertensão arterial - anos; acidente vascular cerebral - meses. Assinale a alternativa correta em\nrelação ao caso:","options":{"A":"O Câncer gástrico foi considerado, na declaração, a causa básica do óbito.","B":"O Câncer de pulmão deveria ter sido considerado a causa básica do óbito.","C":"A Broncopneumonia foi considerada a causa básica do óbito.","D":"A Hipertensão Arterial e o Acidente Vascular Cerebral foram considerados fatores relevantes\nassociados ao óbito e por isso foram citados na parte II da declaração.","E":"A causa terminal ou imediata do óbito é a causa básica do óbito para efeitos de preenchimento\nda Declaração de Óbito."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-80688","number":"80688","sourceNumber":"80688","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"As manifestações extraesofágicas da doença do refluxo podem incluir:","options":{"A":"Febre alta.","B":"Diarreia.","C":"Vômitos em jato.","D":"Sangramento gengival.","E":"Laringite."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-75482","number":"75482","sourceNumber":"75482","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem com 35 anos de idade, obeso, com hérnia de hiato, é acompanhado\nclinicamente há cerca de dez anos. Sua última\nendoscopia de controle mostrou esofagite com\nesôfago de Barrett em uma extensão de cerca de 5 cm. Foram colhidas biópsias cujo resultado foi\nmetaplasia de Barrett. A conduta inicial para o seguimento deste paciente é:","options":{"A":"indicação imediata de cirurgia antirrefluxo.","B":"indicação imediata de esofagectomia parcial.","C":"orientações higienodietéticas e o uso de antiácidos orais.","D":"uso de inibidores de bomba de prótons - 60 a 80 mg/dia - por três meses.","E":"erradicação de H. pylori com amoxicilina - 2,0 g/dia e claritromicina - 1,0 g/dia."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-64426","number":"64426","sourceNumber":"64426","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Na gastrite atrófica, ocorre deficiência na secreção de fator intrínseco, comprometendo\na absorção de:","options":{"A":"Vitamina K","B":"Proteínas","C":"Gorduras","D":"Vitamina B12","E":"Cálcio"},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-64441","number":"64441","sourceNumber":"64441","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Indique a droga que auxilia na cicatrização da úlcera gástrica independente de sua\ncausa:","options":{"A":"Hidróxido de alumínio","B":"Omeprazol","C":"Doxiciclina","D":"Metronidazol","E":"Amoxicilina"},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-75505","number":"75505","sourceNumber":"75505","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem com 50 anos de idade foi atendido no ambulatório de Clínica Médica por\napresentar dor epigástrica em queimação pós-prandial, de moderada intensidade. Informa que,\nocasionalmente, acorda durante a noite por causa da dor. O exame físico é sem alterações. O\npaciente foi submetido à endoscopia digestiva alta que revelou pequena ulceração em bulbo\nduodenal, de aspecto endoscópico benigno e teste da urease positivo. A conduta terapêutica\nindicada para o paciente é prescrever:","options":{"A":"pantoprazol, tetraciclina e metronidazol por 14 dias.","B":"lansoprazol, metronidazol e amoxicilina por 21 dias.","C":"rabeprazol por 21 dias, tetraciclina e levofloxacina por 15 dias.","D":"omeprazol por 28 dias e claritromicina e amoxicilina por 14 dias.","E":"esomeprazol, levofloxacina e claritromicina por 14 dias."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-137568","number":"137568","sourceNumber":"137568","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 51 anos de idade, do sexo masculino, procura ambulatório de atenção\nsecundária com queixa de pirose intermitente, frequentemente deflagrada por ingestão de\nalimentos gordurosos e álcool, por prática de exercícios físicos e por deitar-se após\nalimentação. Relata ainda eventuais episódios de regurgitação. Nega vômitos, náuseas, disfagia\nou odinofagia. Não faz uso de medicamentos em sua rotina diária. Além de sobrepeso, nada foi\nencontrado de anormal no exame físico. A abordagem mais custo-efetiva e benéfica para esse\npaciente é","options":{"A":"proceder estudo manométrico de esôfago.","B":"solicitar endoscopia digestiva alta com biópsia.","C":"prescrever inibidores de bomba de prótons por via oral.","D":"administrar antiácidos por via oral nos intervalos das refeições.","E":"realizar teste não invasivo para detecção de Helicobacter\nPylori."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-137609","number":"137609","sourceNumber":"137609","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um homem de 39 anos de idade vem, há três anos, em tratamento ambulatorial\npara doença do refluxo gastroesofágico (DRGE),\nem uso contínuo de inibidores de bomba de\nprótons (IBP). Sempre que tenta fazer desmame dos\n\nIBP, volta a apresentar graves sintomas da DRGE. Esofagogastroduodenoscopia com biópsia\nrealizada há dois anos evidenciou\nesofagite, pequena hérnia de hiato (< 3 cm) e estômago\nnormal. O paciente interrompeu o uso de IBP há quatro meses e, devido ao quadro de\npirose e dor retroesternal, foi submetido a nova endoscopia digestiva, que revelou processo\ninflamatório grave e úlceras no terço distal do esôfago. O estômago apresenta-se normal e\no teste da urease é positivo. Não foi visualizada hérnia hiatal. Devido ao intenso processo\ninflamatório, não foi realizada biópsia. O paciente, que não apresenta outras queixas ou\n\nco-morbidades, é etilista social, tabagista (média de 1,5 maços/dia há 22 anos) e apresenta\nobesidade leve. Não há outras alterações ao exame físico. O que deve ser feito para\nencaminhar corretamente o caso acima descrito?","options":{"A":"Reiniciar o tratamento com IBP, utilizando o dobro da dose. Após seis semanas de\ntratamento, repetir endoscopia com biópsia.","B":"Manter o tratamento com IBP na dose habitual e encaminhar, de imediato, o paciente\npara ambulatório especializado de Cirurgia\nLaparoscópica.","C":"Solicitar imediatamente nova endoscopia, já que a biópsia é indispensável, e encaminhar o\npaciente para ambulatório especializado de Cirurgia Laparoscópica.","D":"Reiniciar o tratamento com IBP, utilizando o dobro da dose, associado ao tratamento do\nH.Pylori. Em seguida, tratamento de manutenção com IBP por tempo indefinido.","E":"Reiniciar tratamento com IBP , utilizando o dobro da dose por seis semanas. Após esse\nperíodo, tratamento de manutenção com IBP por tempo indefinido."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-138379","number":"138379","sourceNumber":"138379","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um homem de 40 anos de idade apresentou úlcera duodenal com biópsia positiva para\nHelicobacter Pylori. Fez tratamento durante 7 dias com omeprazol, amoxicilina e claritromicina, em\ndoses padrão. Endoscopia de controle repetida após oito semanas de tratamento revela\npersistência de H. Pylori na biópsia. Qual a conduta mais adequada para o tratamento desse\npaciente?","options":{"A":"Omeprazol, amoxicilina e furazolidona por 10 dias.","B":"Omeprazol, levofloxacina e amoxicilina por 10 dias.","C":"Pantoprazol, amoxicilina e claritromicina por 14 dias.","D":"Pantoprazol, sais de bismuto, furazolidona e claritromicina por 10 dias.","E":"Pantoprazol, sais de bismuto, levofloxacina e claritromicina por 10 dias."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-30949","number":"30949","sourceNumber":"30949","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Julgue o item seguinte, a respeito da anatomia e fisiologia humanas. O fator intrínseco,\nmucoproteína secretada pelas células parietais gástricas, é essencial para a absorção de vitamina\nB12 no íleo terminal?","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-138607","number":"138607","sourceNumber":"138607","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo feminino, com 34 anos de idade, sem antecedentes patológicos\npregressos significativos, procurou a Unidade Básica\nde Saúde com história de pirose e\nregurgitação há mais ou menos seis meses, e piora do quadro no último mês. Relata ganho\nponderal de 10 kg nos últimos três meses (Índice de massa corpóreo atual = 36,8 kg/m2 ). Faz uso\nirregular de antiácido por conta própria. Trazia consigo um resultado de endoscopia digestiva alta\ncom o seguinte laudo: ?erosões lineares de até 5 mm, não confluentes, localizadas em esôfago\ndistal?. Baseado no diagnóstico acima, você prescreve um inibidor de bomba de prótons durante\noito semanas e orienta a paciente a","options":{"A":"perder peso e evitar deitar-se imediatamente após\nas refeições.","B":"evitar ingestão de café e praticar esportes.","C":"suspender carne vermelha da alimentação e ingestão de bebidas gaseificadas.","D":"dormir com cabeceira da cama elevada e abolir\nfibras na dieta.","E":"aumentar a ingesta de proteínas e reduzir a ingesta\nde carboidratos"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-138664","number":"138664","sourceNumber":"138664","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem, com 45 anos de idade, com dor epigástrica diária, ocorrendo no período\npós-prandial e à noite, e perda ponderal de 4 kg, começou uso de inibidor de bomba de próton\n\n(IBP) com alguma melhora. Informa que não usa álcool ou antinflamatórios não hormonais. Ainda\nna vigência da medicação realizou endoscopia\ndigestiva alta que revelou gastrite nodosa de antro e\ncorpo, e úlcera duodenal em fase de cicatrização. Biópsias de mucosa gástrica foram realizadas\ndurante o procedimento, e submetidas ao teste rápido de urease em fase líquida, cujo resultado foi\nnegativo. Quanto ao tratamento para Helicobacter pylori nesse paciente, conclui-se que","options":{"A":"não há necessidade de tratamento, pois o agente etiológico não é o Helicobacter pylori.","B":"não há necessidade de tratamento, pois a cicatrização da úlcera ocorre após a erradicação da\nbactéria.","C":"o tratamento está indicado e o uso de IBP interfere no teste de urease.","D":"há necessidade de tratamento profi lático contra reinfecção, mesmo havendo cura.","E":"há necessidade de tratamento especial para Helicobacter pylori resistente aos antibióticos."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-22155","number":"22155","sourceNumber":"22155","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Acerca das doenças que acometem o esôfago, julgue o item a seguir. Dilatação do\ncorpo do esôfago, perda da peristalse\nesofágica e extremidade distal do esôfago com afunilamento\nuniforme em bico são exemplos de alterações radiológicas observadas em esofagramas baritados\nde paciente com diagnóstico de acalasia de esôfago.","options":{"A":"certo","B":"errado"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-22156","number":"22156","sourceNumber":"22156","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Acerca das doenças que acometem o esôfago, julgue os itens a seguir. A esofagite\ncáustica por ingestão de medicamentos pode ser\ncausada por clindamicina, anti-inflamatórios não\nesteroidais, comprimidos de cloreto de potássio e vitamina C, entre outros, e pode ser prevenida\npela ingestão de vários goles de água (antes e após a ingestão de medicamento) e pela\nmanutenção de posição ortostática após a ingestão da medicação.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-22157","number":"22157","sourceNumber":"22157","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Acerca das doenças que acometem o esôfago, julgue os itens a seguir. O esôfago de\nBarrett é uma complicação da doença por refluxo gastroesofágico e representa uma condição na\nqual o epitélio escamoso do esôfago é substituído por epitélio colunar metaplásico.","options":{"A":"certo","B":"errado"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-8639","number":"8639","sourceNumber":"8639","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente de 29 anos de idade, com queixas de disfagia para sólidos há 10 anos e\npiora progressiva nos últimos meses, procurou atendimento médico. O exame físico evidenciou\npaciente muito emagrecido, mas em bom estado geral. Considerando o caso clínico descrito, julgue\no item subsequente. Durante a investigação diagnóstica do caso em apreço, a ausência de ondas\nterciárias no esôfago será indicativa de que o paciente deverá ser submetido a uma cardioplastia\nou ressecção esofágica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-352186","number":"352186","sourceNumber":"352186","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente feminina, parda, 36 anos, obesa, apresenta pirose e regurgitação diariamente\nhá cerca de 3 meses. Nega disfagia, perda de\npeso, hiporexia, hemorragia digestiva ou outras\nqueixas. Nega comorbidades. Ao terminar de contar a sua história, a paciente fez uma pergunta:\npreciso fazer algum exame para saber o que eu tenho? Marque a alternativa com a resposta\ncorreta a esse questionamento.","options":{"A":"Sim. Está indicada a realização de uma pHmetria de 24 horas, uma vez que é o exame padrão\nouro para o diagnóstico.","B":"Não. A paciente apresenta sintomas típicos de doença do refluxo gastroesofágico e, como não\ntem sinais de alarme, não está indicada a\nrealização de endoscopia digestiva alta ou qualquer outro\nexame para confirmação diagnóstica.","C":"Sim. Deve ser realizada uma endoscopia digestiva alta em todos os pacientes com sintomas\nsugestivos de doença do refluxo gastroesofágico.","D":"Sim. É necessário realizar uma endoscopia digestiva alta e um Raio-X contrastado do esôfago\npara o diagnóstico diferencial com\nacalasia."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-368181","number":"368181","sourceNumber":"368181","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente com 54 anos de idade, usuário de diclofenaco sódico por lombalgia,\napresenta, há algumas horas, dor súbita em\nepigástrio, que rapidamente se irradia para todo o\nabdome. Não apresenta vômitos. Está taquicárdico e taquipneico. Ao exame abdominal, nota-se\nabdome em tábua, mas com sinal de Jobert ausente. A radiografia de abdome e de tórax com\ncúpulas é normal. Nesse caso, o diagnóstico mais provável é","options":{"A":"necrose intestinal.","B":"infarto do miocárdio.","C":"perfuração de úlcera péptica.","D":"pancreatite aguda."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-351614","number":"351614","sourceNumber":"351614","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O quadro clínico na infecção pelo Helicobacter pylori (H. pylori) é diversificado e\nrelaciona-se a alguns sinais e sintomas. Com\nrelação a esses sinais, é CORRETO afirmar que após\na infecção primária pelo H. pylori","options":{"A":"metade das pessoas infectadas pode apresentar sintomas de gastroenterite.","B":"raramente ocorre evolução para quadro de úlcera péptica gástrica e duodenal.","C":"ocorrem náuseas e vômitos, o que provoca uma diminuição transitória de secreção ácida e\nhipercloridria.","D":"metade das pessoas infectadas pode apresentar sintomas de gastrite aguda."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-368186","number":"368186","sourceNumber":"368186","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Uma paciente do sexo feminino, 33 anos de idade,1,64 m, 55 kg, operada de refluxo há\ndois anos, refere queixa de azia regular há um ano e meio. Relata que faz uso de antiácido, sem\nreceita médica, com pouca melhora. Faz uso também de anticoncepcional oral, cálcio e vitamina D.\nRealizou uma endoscopia recente com esofagite não erosiva e fundoplicatura continente com boas\npregas envolvendo o aparelho de endoscopia. Foi prescrito inibidor de bomba de próton (IBP), com\npouca melhora em duas semanas. Após aumento da dose, a paciente se apresenta para avaliação\ndo cirurgião, mas não refere melhora nos sintomas. A conduta que deve ser adotada para essa\npaciente é","options":{"A":"realizar a reoperação à Nissen, laparoscópica.","B":"aumentar a dose de IBP.","C":"realizar a endoscopia digestiva alta.","D":"fazer o registro de pH esofágico prolongado."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-337619","number":"337619","sourceNumber":"337619","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem, 71 anos, tem história de cirurgia de gastrectomia parcial e reconstrução a\nBillroth II por úlcera gástrica\nestenosante. Procura atendimento com queixa de episódios de dor\nabdominal associada a náuseas e distensão, com alívio imediato após vômitos biliares. Em relação\nao diagnóstico e tratamento desse paciente, analise as afirmativas a seguir: I- A principal\nhipótese é\nde gastrite alcalina e deve ser solicitada impedâncio-Phmetria. II- O quadro clínico é compatível\ncom a síndrome da alça aferente. III- O tratamento para este caso deve ser o de fazer a Bilroth II\nem um Y de Roux. IV- A principal hipótese é de obstrução da alça eferente, e a melhor conduta é\nconverter para uma Bilroth I. Está(ão) CORRETA(S) as afirmativas:","options":{"A":"IV apenas.","B":"II e III apenas.","C":"I apenas.","D":"I e IV apenas."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-346842","number":"346842","sourceNumber":"346842","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem de 72 anos queixava-se de epigastralgia em queimação há 3 semanas. É\nportador de HAS e faz uso de enalapril,\nsinvastatina e AAS para prevenção primária de eventos\ncardiovasculares. Realizou EDA. Após o resultado, recebeu a prescrição de omeprazol 20mg em\njejum por 4 semanas, com resolução completa dos sintomas. Endoscopia Digestiva Alta (EDA):\ngastrite endoscópica enantematosa moderada do antro; úlcera na transição do corpo para o antro\nna curvatura menor, de fundo limpo, bordas regulares e planas, de 8mm, sem sinais de\nsangramento recente. Teste da urease negativo. Bx: gastrite crônica do antro; sem sinais de\nmalignidade. Assinale a alternativa que apresenta a conduta MAIS adequada para esse paciente\nnesse momento.","options":{"A":"Repetir a EDA.","B":"Suspender o uso do AAS.","C":"Substituir o AAS por prasugrel.","D":"Manter o uso do omeprazol por tempo indeterminado."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-345720","number":"345720","sourceNumber":"345720","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um dos eventos mais temidos nos pacientes com hemorragia digestiva alta é o\nressangramento. Diante disso, vários escores\nsão utilizados para prever tal evento. Considerando a\nclassificação de Forrest, os pacientes que apresentam maior risco de ressangramento são os\nclassificados em Forrest:","options":{"A":"IA.","B":"IB.","C":"IIA.","D":"IIB."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-291923","number":"291923","sourceNumber":"291923","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Com relação às complicações da doença do refluxo gastroesofágico, é CORRETO\nafirmar que:","options":{"A":"O uso de anti-inflamatórios não hormonais pode ter um efeito profilático no desenvolvimento de\nadenocarcinoma em pacientes portadores de esôfago de Barrett.","B":"O diagnóstico de esôfago de Barrett é confirmado através da visualização endoscópica de\nepitélio metaplásico substituindo o epitélio escamoso do esôfago.","C":"O achado endoscópico de úlceras esofágicas profundas é típico da doença do refluxo\ngastroesofágico.","D":"O esôfago distal é a sede das estenoses pépticas com, geralmente, mais de 3cm."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-305001","number":"305001","sourceNumber":"305001","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Analise os fatores a seguir. I. Abuso de álcool; II. Sobrepeso associado ao estresse;\nIII.\nSíndrome de Zollinger-Ellison; IV. Overdose de radioterapia no abdome superior; São fatores\npossivelmente associados à gênese da úlcera péptica;","options":{"A":"I e II, apenas.","B":"I, III e IV, apenas.","C":"II e III, apenas.","D":"I, II, III e IV."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-287848","number":"287848","sourceNumber":"287848","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente apresenta dor epigástrica abrupta, intensa, que se difunde para a fossa ilíaca\ndireita e, em seguida, para todo o abdome, e ao exame, o abdome apresenta-se distendido, com\nperitonismo difuso e rigidez involuntária. Com base nessas informações, assinalar a alternativa que\napresenta o diagnóstico mais provável:","options":{"A":"Pancreatite aguda.","B":"Apendicite aguda.","C":"Isquemia mesentérica.","D":"Úlcera péptica perfurada.","E":"Diverticulite aguda."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-283902","number":"283902","sourceNumber":"283902","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 72 anos chega ao consultório se queixando de disfagia. Relata também\nque vem apresentando tosse, salivação\nexcessiva, regurgitação de alimentos mal digeridos e\nhalitose. Qual o provável diagnóstico?","options":{"A":"Divertículo de Meckel.","B":"Úlcera gástrica.","C":"Volvo intestinal.","D":"Divertículo de Zenker.","E":"Divertículo epifrênico."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-266401","number":"266401","sourceNumber":"266401","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente masculino, 63 anos, pedreiro, com dor crônica em região lombar fazendo uso\nde anti-inflamatório há 03 meses consecutivos. Deu\nentrada na Unidade de Pronto Atendimento\ncom dor abdominal súbita, de forte intensidade. Ao exame apresenta taquicardia, taquipneia e\nsinais de irritação peritoneal. Raio X de tórax e Rx de abdome em pé evidenciam pneumoperitônio.\nQual o mais provável diagnóstico?","options":{"A":"Úlcera perfurada.","B":"Diverticulite aguda.","C":"Neoplasia de cólon.","D":"Isquemia mesentérica."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-260708","number":"260708","sourceNumber":"260708","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre as lesões cáusticas do trato gastrointetinal é correto afirmar:","options":{"A":"A mortalidade destas lesões é relativamente baixa (<5%).","B":"A ocorrência de carcinoma epidermóide esofágico não se modifica nestes pacientes.","C":"O prognóstico do carcinoma esofágico associado à ingestão de cáusticos é pior que o do\nesporádico.","D":"A complicação tardia mais frequente é a estenose antro-pilórica.","E":"Hemorragia digestiva alta maciça é um evento comum."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-260709","number":"260709","sourceNumber":"260709","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"De qual artéria se origina a artéria gastroepiplóica direita:","options":{"A":"Hepática.","B":"Esplênica.","C":"Gástrica direita.","D":"Celíca.","E":"Gastroduodenal."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-227103","number":"227103","sourceNumber":"227103","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente do sexo masculino, 43 anos, com quadro de dor em região epigástrica há 24\nhoras, é admitido no pronto-socorro. Na\nhistória tem antecedente de hipertensão arterial sistêmica e\nDiabetes Mellitus. Ao exame clínico, apresenta palpação dolorosa em região epigástrica e flancos.\nRaio X abdominal em posição ortostática revela presença de sinal de Rigler. Hemograma com\nleucocitose e dosagem de amilase com valor de 363mgr/dl. Considerando o caso descrito, assinale\no diagnóstico MAIS PROVÁVEL para esse paciente.","options":{"A":"Pancreatite aguda.","B":"Úlcera duodenal perfurada.","C":"Colecistite aguda.","D":"Colangite aguda."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-227105","number":"227105","sourceNumber":"227105","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente masculino, 70 anos, apresenta adenocarcinoma tipo intestinal de Lauren no\nantro gástrico. No exame físico não demonstra presença de metástases à distância. A tomografia\nde abdômen não apresentou ascite e nem suspeita de lesão hepática. Considerando o caso\ndescrito, a cirurgia MAIS ADEQUADA a ser realizada seria a:","options":{"A":"Gastrectomia total + linfadenectomia D2.","B":"Gastrectomia total + linfadenectomia de ao menos 15 linfonodos perigástricos.","C":"Gastrectomia subtotal + linfadenectomia D2.","D":"Gastroenteroanastomose paliativa."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-232136","number":"232136","sourceNumber":"232136","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"São situações especiais em que está indicada a escolha do uso de inibidores H2\n(Ranitidina) para profilaxia de úlcera de estresse em detrimento aos bloqueadores de bomba de\nprótons (Omeprazol) por motivos de interação medicamentosa:","options":{"A":"Pacientes em uso de ácido acetilsalicílico e clopidogrel.","B":"Pacientes em uso de ácido acetilsalicílico.","C":"Pacientes em uso de clopidogrel, fenitoína e corticoides via enteral.","D":"Pacientes em uso de clopidogrel e corticóde via enteral.","E":"Pacientes em uso de clopidogrel e fenitoína via enteral."},"answer":"E","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-232145","number":"232145","sourceNumber":"232145","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Assinale, abaixo, de qual estrutura vascular a artéria gástrica direita é ramo:","options":{"A":"Artéria esplênica.","B":"Artéria hepática.","C":"Troco celíaco.","D":"Artéria gastroepiplóica esquerda.","E":"Artéria pancreatoduodenal superior."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-232147","number":"232147","sourceNumber":"232147","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre o câncer gástrico, avalie as seguintes afirmações: I. Mais de 95% dos tumores\nmalignos do estômago são adenocarcinomas; II. A constipação está presente em 10% dos\npacientes; III. 40% dos pacientes apresentam sinais de anemia crônica; IV. A presença do nódulo\nde Virchow demonstra doença avançada e é caracterizado pela presença de lesão em região\numbilical; Assinale a opção que contém as afirmativas corretas:","options":{"A":"I e III.","B":"I e II.","C":"I, II e III.","D":"I, II e IV.","E":"II, III e IV."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-227291","number":"227291","sourceNumber":"227291","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"V.C.X., feminino, 39 anos, com diagnóstico prévio de doença do refluxo gastroesofágico\nhá 10 anos, inicialmente com sintomas\n3?4x/semana, com melhora completa dos sintomas após\ntratamento com Inibidores de Bomba de Prótons (IBP). Durante endoscopia digestiva alta realizada\nde controle de esofagite erosiva, foi evidenciada mucosa esofágica distal de cor rósea, de cerca de\n02 cm de extensão e foram realizadas múltiplas biópsias que evidenciaram metaplasia intestinal\nsem sinais de displasia. No momento, paciente com controle adequado de sintomas com IBP.\nDiante do quadro, qual a recomendação para a paciente?","options":{"A":"Fundoplicatura a Nissen.","B":"Ressecção endoscópica.","C":"Ablação endoscópica.","D":"Repetir endoscopia a cada 3 a 5 anos."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-227304","number":"227304","sourceNumber":"227304","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente de 60 anos, classe social baixa, tabagista 60 anos/maço, 60kg, previamente\nhígida, relata início de quadro de\nepigastralgia atípica, sem irradiação, associado a hiporexia,\nplenitude pós prandial e anemia de difícil controle, de início há cerca de 06 meses, com\nemagrecimento de 06 kg. Nega relação da dor com atividade física. Ao exame, hipocorada,\nemagrecida, sem massas ou visceromegalias palpáveis, restante do exame físico normal. Diante do\nquadro clínico e principal suspeita diagnóstica, qual o exame complementar inicial a ser\nsolicitado?","options":{"A":"Tomografia Computadorizada de Abdome.","B":"Ultrassonografia de Abdome.","C":"Endoscopia Digestiva Alta.","D":"Raio X de abdome agudo."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-246781","number":"246781","sourceNumber":"246781","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"FMC, masculino, 70 anos, queixa-se de disfagia há 3 anos associada a halitose e\nregurgitação de alimentos não digeridos. Refere também que frequentemente percebe\nabaulamento na região cervical, mas que nem sempre é perceptível. Sobre o caso clínico podemos\nafirmar:","options":{"A":"Trata-se de provável distúrbio motor do esôfago. Assim o diagnóstico será confirmado após uma\nesofagomanometria.","B":"Devido a idade, devemos considerar como principal hipótese o câncer de esôfago. Assim,\nrealizar uma endoscopia digestiva alta deve ser a primeira medida.","C":"a principal hipótese é de divertículo esofágico verdadeiro, formado em área de fraqueza entre\nhipofaringe e esôfago conhecida como trígono de Killian","D":"considerando a principal hipótese de divertículo de Zencker, devemos evitar a indicação inicial\nda endoscopia digestiva alta, pelo risco de\nperfuração acidental.","E":"A confirmação diagnóstica provavelmente será mediante uma pHmetria ou após melhora clínica\ncom IBP (prova terapêutica)."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-246784","number":"246784","sourceNumber":"246784","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Sobre a doença do refluxo gastroesofágico (DRGE) e a obesidade, podemos afirmar,\nEXCETO:","options":{"A":"A obesidade atua como fator de risco para a DRGE, tanto por interferir no funcionamento do\nesfíncter esofageano inferior quanto pelo aumento da pressão intra-abdominal.","B":"Atualmente a DRGE é considerada comorbidade associada/agravada pela obesidade, podendo\nvir a indicar cirurgia bariátrica quando\npaciente tiver IMC acima de 35.","C":"Os pacientes obesos, com IMC acima de 35 e refratários ao tratamento da DRGE com IBP, têm\na opção da fundoplicatura gástrica com\nválvula total (Nissen) como indicação terapêutica pertinente\ne com bons resultados na remissão dos sintomas.","D":"os pacientes com obesidade severa (IMC>40) e DRGE têm na cirurgia bariátrica o melhor aliado\npara tratamento das duas doenças e o Bypass Gástrico em Y de Roux tem sido a técnica mais\nadequada nestes pacientes, quando comparada ao Sleeve (gastrectomia vertical).","E":"Tanto a obesidade quanto a DRGE atuam como fatores de risco para o adenocarcinoma de\nesôfago."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-243057","number":"243057","sourceNumber":"243057","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Qual a conduta mais adequada em um paciente com performance status ECOG-PS1\nportador de carcinoma epidermoide de\nesôfago médio cujos exames de estadiamento (tomografia\nde tórax e abdome) não evidenciaram doença metastática ? estádio clinico T3N0M0:","options":{"A":"esofagectomia seguido de quimioterapia adjuvante.","B":"radioquimioterapia neoadjuvante seguido de esofagectomia.","C":"radioterapia neoadjuvante seguido de esofagectomia e quimioterapia adjuvante.","D":"radioquimioterapia exclusiva sem esofagectomia.","E":"esofagectomia exclusiva sem radioterapia ou quimioterapia."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-196781","number":"196781","sourceNumber":"196781","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"O procedimento cirúrgico de escolha para o tratamento da doença do refluxo\ngastroesofágico, na maioria dos pacientes, deve ser a cirurgia de:","options":{"A":"Lind.","B":"Thal.","C":"Heller modificada.","D":"Nissen."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-215153","number":"215153","sourceNumber":"215153","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Uma paciente de 41 anos de idade, com queixa de dor epigástrica em queimação de\nlonga data relacionada à ingesta de alimentos condimentados, retorna em consulta ambulatorial\ntendo como resultado de endoscopia digestiva alta o diagnóstico de úlcera duodenal e pesquisa de\n\nH. pylori positivo. Relatava uso esporádico de antiácidos, mas com pouca melhora da dor. Nega\nuso de Anti-inflamatórios não Esteroidais\n(AINES). Qual a associação de medicamentos com\nmelhor nível de evidência científica para o tratamento desse caso?","options":{"A":"Agente antissecretor, omeprazol e claritromicina.","B":"Inibidor da bomba de prótons, eritromicina e amoxicilina.","C":"Inibidor da bomba de prótons, amoxicilina e claritromicina.","D":"Antagonistas do receptor H2 de histamina, claritromicina e amoxicilina.","E":"Manter antiácidos e iniciar inibidor de bomba de prótons."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-199600","number":"199600","sourceNumber":"199600","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Julgue as afirmativas abaixo sobre a Doença Ácido-Péptica em Verdadeiras (V) ou\nFalsa (F) e em seguida assinale a alternativa correta. ( ) Cerca de duas semanas após o início do\nuso de anti-inflamatórios não esteroidais, cerca de 5% dos pacientes desenvolvem erosões e\núlceras gástricas. ( ) O risco de desenvolver úlcera durante o uso de anti-inflamatórios não\nesteroidais é maior em pacientes acima de 60 anos de idade, em pacientes que previamente\ntiveram úlcera, em pacientes que usam corticosteroides e em pacientes com comorbidades\nimportantes. ( ) O risco de desenvolvimento de úlcera na presença do Helicobacter Pylori é\ndeterminado por fatores relacionados a bactéria, não tendo os fatores do hospedeiro qualquer\ninterferência nesse processo. ( ) A hemorragia é a complicação mais comum da úlcera péptica,\nsendo as úlceras causadas pelos anti-inflamatórios não esteroidais responsáveis por uma\nproporção maior dessa complicação.","options":{"A":"V, V, F, V.","B":"F, F, F, V.","C":"V, F, F, V.","D":"F, V, F, F."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-202737","number":"202737","sourceNumber":"202737","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente feminina, 72 anos, hipertensa, diabética, renal crônica em tratamento\nconservador, dá entrada no pronto\natendimento, com história de vômitos em borra de café.\nRealizada endoscopia de urgência: identificada úlcera ativa em bulbo duodenal com estigmas\nendoscópicos de sangramento recente. Com relação à propedêutica, em caso de presença de\núlcera péptica ativa, podemos afirmar que:","options":{"A":"Tanto a úlcera gástrica quanto a úlcera duodenal devem ser biopsiadas durante a realização de\nendoscopia para fins de diagnóstico diferencial com neoplasia, não havendo necessidade de\nrealizar nova endoscopia após o tratamento para controle de cura.","B":"Apenas a úlcera gástrica deve ser biopsiada durante a realização de endoscopia para fins de\ndiagnóstico diferencial com neoplasia, havendo necessidade de realizar nova endoscopia após o\ntratamento para controle de cura.","C":"Apenas a úlcera duodenal deve ser biopsiada durante a realização de endoscopia para fins de\ndiagnóstico diferencial com neoplasia, sendo necessário realizar nova endoscopia após o\ntratamento para controle de cura.","D":"Tanto a úlcera gástrica quanto a úlcera duodenal devem ser biopsiadas durante a realização de\nendoscopia para fins de diagnóstico diferencial com neoplasia, havendo necessidade de realizar\nnova endoscopia após o tratamento para controle de cura.","E":"Apenas a úlcera gástrica deve ser biopsiada durante a realização de endoscopia para fins de\ndiagnóstico diferencial com neoplasia, não havendo necessidade de realizar nova endoscopia após\no tratamento para controle de cura."},"answer":"B","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-199518","number":"199518","sourceNumber":"199518","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Homem, 68 anos, queixa de empachamento e plenitude pós-prandial há 5 meses, com\npiora no último mês, quando passou a se alimentar de dieta líquida, pois vomita ao ingerir sólidos.\nNo exame físico: não apresenta linfonodos periféricos ou massas abdominais palpáveis. Presença\nde prateleira de Blumer no toque retal e sinal de piparote positivo. A endoscopia mostrou uma lesão\nulceroinfiltrativa da região antro-pilórica, cuja biópsia revelou adenocarcinoma. US: não evidenciou\nmetástases hepáticas no abdômen. O estadiamento oncológico MAIS PROVÁVEL desse paciente\né o:","options":{"A":"I.","B":"II.","C":"III.","D":"IV."},"answer":"D","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-202748","number":"202748","sourceNumber":"202748","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Paciente feminina, 72 anos, hipertensa, diabética, renal crônica em tratamento\nconservador, dá entrada no pronto atendimento,\ncom história de vômitos em borra de café.\nRealizada endoscopia de urgência: identificada úlcera ativa em bulbo duodenal com estigmas\nendoscópicos de sangramento recente. Com relação à classificação endoscópica dos estigmas de\nsangramento, encontrados nas lesões em paciente com HDA não varicosa, e a indicação de\ntratamento endoscópico dos mesmos, podemos afirmar que:","options":{"A":"Úlcera Forrest IIb apresenta-se com coágulo aderido e deve receber tratamento endoscópico.","B":"Úlcera Forrest Ib apresenta-se com coágulo aderido e não deve receber tratamento\nendoscópico.","C":"Úlcera Forrest IIa apresenta-se com sangramento em jato e deve receber tratamento\nendoscópico.","D":"Úlcera Forrest IIc apresenta-se com coto vascular visível e não deve receber tratamento\nendoscópico.","E":"Úlcera Forrest III apresenta-se com hematina e deve receber tratamento endoscópico."},"answer":"A","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gastrologia-gas-1-199492","number":"199492","sourceNumber":"199492","collectionBlock":"medcurso:medcurso-gastrologia-gas-1","collectionLabel":"Medcurso · GAS 1","documentBlock":"","area":"Gastroenterologia","specialty":"Gastroenterologia","topic":"GAS 1","subtopic":"","stem":"Um paciente apresenta um diagnóstico de neoplasia gástrica na biópsia realizada por\nendoscopia digestiva alta. Na classificação histológica dos tipos de Lauren, existem os tipos\nintestinal e difuso. Nesse contexto, assinale a alternativa CORRETA:","options":{"A":"No subtipo intestinal, ocorre menor frequência de atrofia da mucosa gástrica e de gastrite\ncrônica.","B":"O acometimento do sexo feminino, abaixo de 60 anos, é mais frequente no tipo difuso, mas o\nprognóstico é melhor que o do tipo intestinal.","C":"As células malignas tendem a formar glândulas no subtipo intestinal.","D":"A invasão linfática e a presença de células em anel de sinete são mais frequentes no subtipo\n\nintestinal do que no tipo difuso."},"answer":"C","source":"Gastrologia/GAS 1/GAS 1.txt","sourceLabel":"Medcurso · GAS 1","images":[],"optionImages":{},"commentImages":[],"tags":["Gastroenterologia","GAS 1","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
